INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fNk_zzaMoSs','hn',25.0,'{"vid":"fNk_zzaMoSs","title":"Vectors | Chapter 1, Essence of linear algebra","channel":"3Blue1Brown","summary":"The first chapter of 3Blue1Brown''s Essence of Linear Algebra series, introducing vectors with animated geometric visuals. It begins a series that builds intuition for linear algebra from the basics.","why":"HN''s go-to recommendation for learning linear algebra intuition, repeatedly credited with making concepts click and complementing textbooks.","type":"course","level":"intro","score":25.0,"topics":["Math for ML"],"recs":17,"years":[2018,2026],"quote":"the most welcoming and informative introduction to the topic I''ve ever seen","quote_url":"https://news.ycombinator.com/item?id=18679785","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('FITJMJjASUs','hn',22.5,'{"vid":"FITJMJjASUs","title":"Ruby Conf 12 - Y Not- Adventures in Functional Programming by Jim Weirich","channel":"Confreaks","summary":"Jim Weirich''s RubyConf 2012 talk derives the Y combinator step by step, live-coding in Ruby lambdas. It builds up an understanding of functional programming and lambda calculus from first principles.","why":"HN recommends it repeatedly as one of the best and most entertaining programming talks, and as the talk that makes the Y combinator click, even for people who do not use Ruby.","type":"talk","level":"intermediate","score":22.5,"topics":["Languages & compilers","Math & theory"],"recs":17,"years":[2013,2026],"quote":"perhaps the most entertaining and interesting technical talk I''ve ever seen.","quote_url":"https://news.ycombinator.com/item?id=10562564","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('VMj-3S1tku0','hn',21.0,'{"vid":"VMj-3S1tku0","title":"The spelled-out intro to neural networks and backpropagation: building micrograd","channel":"Andrej Karpathy","summary":"Andrej Karpathy''s first Neural Networks: Zero to Hero lecture, which builds micrograd, a tiny autograd engine, from scratch in Python. It explains backpropagation and neural network training step by step, assuming only basic Python and some high-school calculus.","why":"HN treats it as the best starting point for really understanding backprop and neural nets, because Karpathy explains the why with intuition and builds everything in code.","type":"lecture","level":"intro","score":21.0,"topics":["Karpathy","Python","AI & ML","Languages & compilers"],"recs":17,"years":[2022,2025],"quote":"It''s especially useful because he explains the why and provides intuitive explanations instead of just talking about the what and how.","quote_url":"https://news.ycombinator.com/item?id=36428875","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('qCGofLIzX6g','hn',19.5,'{"vid":"qCGofLIzX6g","title":"How Python was Shaped by leaky Internals, Armin Ronacher, Flask framework","channel":"Видео с мероприятий {speach!","summary":"Armin Ronacher, creator of Flask, explains how CPython''s internals and C API leak into the language''s semantics. Using examples like the complexity of the add operation, he shows why Python is hard to optimize or reimplement.","why":"It is HN''s standard answer to why Python cannot easily get much faster, and is recommended by people who work on JITs and alternative runtimes.","type":"talk","level":"advanced","score":19.5,"topics":["Python","Languages & compilers","Systems & performance"],"recs":15,"years":[2017,2025],"quote":"This excellent talk describes how the semantics of the \"add\" operation are much more complex than generally described.","quote_url":"https://news.ycombinator.com/item?id=28706370","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8bZh5LMaSmE','hn',18.5,'{"vid":"8bZh5LMaSmE","title":"RailsConf 2014 - All the Little Things by Sandi Metz","channel":"Confreaks","summary":"Sandi Metz takes an ugly section of conditional code and refactors it into a few simple objects, bridging object-oriented theory and practice. The talk includes her take on the Gilded Rose refactoring kata and the idea that duplication is cheaper than the wrong abstraction.","why":"HN treats it as a top-tier programming talk for learning refactoring and for the wrong-abstraction principle, recommended repeatedly over a decade.","type":"talk","level":"intermediate","score":18.5,"topics":["Software design & craft","Languages & compilers"],"recs":15,"years":[2015,2025],"quote":"this talk captures all the important values in a single example.","quote_url":"https://news.ycombinator.com/item?id=13129780","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JvBT4XBdoUE','hn',17.5,'{"vid":"JvBT4XBdoUE","title":"The Soul of Erlang and Elixir • Sasa Juric • GOTO 2019","channel":"GOTO Conferences","summary":"Sasa Juric explains what makes Erlang and Elixir suited to server-side systems, focusing on the BEAM concurrency model rather than syntax or ecosystem. He demonstrates processes, supervision, and fault tolerance.","why":"It is HN''s favorite pitch for Elixir and the BEAM, credited with convincing many people to adopt them.","type":"talk","level":"intermediate","score":17.5,"topics":["Languages & compilers","Databases & distributed"],"recs":16,"years":[2019,2024],"quote":"Watch this if you want to understand why so many people fall in love with it.","quote_url":"https://news.ycombinator.com/item?id=27684911","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SxdOUGdseq4','hn',17.0,'{"vid":"SxdOUGdseq4","title":"\"Simple Made Easy\" - Rich Hickey (2011)","channel":"Strange Loop Conference","summary":"Rich Hickey''s Strange Loop 2011 keynote distinguishing ''simple'' (not intertwined) from ''easy'' (familiar or near at hand). It argues that software complexity comes from complecting things and that we should pick simple constructs.","why":"HN treats it as the canonical talk on software complexity, shared constantly and recommended to every programmer regardless of language.","type":"talk","level":"intermediate","score":17.0,"topics":["Software design & craft","Languages & compilers"],"recs":14,"years":[2022,2026],"quote":"is a must-watch (even if you never touch Clojure)","quote_url":"https://news.ycombinator.com/item?id=34050492","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8aGhZQkoFbQ','hn',16.5,'{"vid":"8aGhZQkoFbQ","title":"What the heck is the event loop anyway? | Philip Roberts | JSConf EU","channel":"JSConf","summary":"Philip Roberts explains the JavaScript event loop, call stack, callbacks and asynchronous behavior with live visualizations using a tool he built. It demystifies terms like non-blocking and single-threaded.","why":"HN commenters repeatedly name it as the best explanation of the JS event loop and the first thing to watch before tackling async code.","type":"talk","level":"intermediate","score":16.5,"topics":["Web","Languages & compilers"],"recs":16,"years":[2015,2025],"quote":"The tool he created to display the event loop in real time is fantastic.","quote_url":"https://news.ycombinator.com/item?id=18218222","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('aircAruvnKk','hn',16.5,'{"vid":"aircAruvnKk","title":"But what is a neural network? | Deep learning chapter 1","channel":"3Blue1Brown","summary":"3Blue1Brown''s first chapter on deep learning explains what neurons and layers are and the math underlying a basic neural network, using handwritten digit recognition with visual animations.","why":"HN treats it as the standard first stop for learning neural networks, praised for making the math intuitive.","type":"explainer","level":"intro","score":16.5,"topics":["AI & ML"],"recs":16,"years":[2017,2025],"quote":"the visualisations and explanations of the math/concepts are so amazing","quote_url":"https://news.ycombinator.com/item?id=16040048","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('AdNJ3fydeao','hn',15.5,'{"vid":"AdNJ3fydeao","title":"Rich Harris - Rethinking reactivity","channel":"You Gotta Love Frontend","summary":"Svelte creator Rich Harris explains moving reactivity into the compiler and language rather than tracking state at runtime, with a history of spreadsheets as reactive systems and comparisons to React.","why":"The most recommended introduction to Svelte, credited with sparking its adoption.","type":"talk","level":"intermediate","score":15.5,"topics":["Web","Languages & compilers"],"recs":15,"years":[2019,2026],"quote":"you can (and I heartily recommend doing so) watch the \"Rethinking reactivity\" video here","quote_url":"https://news.ycombinator.com/item?id=20336598","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IcgmSRJHu_8','hn',15.5,'{"vid":"IcgmSRJHu_8","title":"\"Making Impossible States Impossible\" by Richard Feldman","channel":"elm-conf","summary":"Richard Feldman''s elm-conf talk on designing models so that bugs from impossible application states cannot occur, using Elm''s compiler and types. It demonstrates techniques for making invalid states unrepresentable.","why":"HN repeatedly recommends it as a talk that changed how people model data, with ideas that apply well beyond Elm to any typed language.","type":"talk","level":"intermediate","score":15.5,"topics":["Languages & compilers","Software design & craft"],"recs":9,"years":[2017,2026],"quote":"the talk is Elm lang focused, but the concepts still apply to other languages.","quote_url":"https://news.ycombinator.com/item?id=40164027","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('LIb3L4vKZ7U','hn',14.5,'{"vid":"LIb3L4vKZ7U","title":"CppCon 2015: Andrei Alexandrescu “std::allocator...”","channel":"CppCon","summary":"Andrei Alexandrescu''s CppCon 2015 talk argues that std::allocator is badly designed. He proposes building high-performance allocators from small composable, templated pieces.","why":"HN repeatedly recommends it as an entertaining, mind-opening talk on allocator design and composable generic programming.","type":"talk","level":"advanced","score":14.5,"topics":["Systems & performance"],"recs":7,"years":[2017,2025],"quote":"It really opened my eyes to how one could very elegantly make a very complex and high-performance heap allocator","quote_url":"https://news.ycombinator.com/item?id=42690180","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HxaD_trXwRE','hn',14.0,'{"vid":"HxaD_trXwRE","title":"Lexical Scanning in Go - Rob Pike","channel":"GoogleFOSSSydney","summary":"Rob Pike shows how the Go text/template lexer is built, using state functions, goroutines and channels. The talk was given at a Google Technology User Group in Sydney in 2011.","why":"HN returns to it for years as an elegant introduction to writing a lexer that is easy to follow even without a parsing background.","type":"talk","level":"intermediate","score":14.0,"topics":["Languages & compilers","Systems & performance"],"recs":13,"years":[2012,2025],"quote":"It''s far more interesting than it sounds, and even if you don''t know much about lexing/parsing it''s easy to follow.","quote_url":"https://news.ycombinator.com/item?id=7822010","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OyfBQmvr2Hc','hn',14.0,'{"vid":"OyfBQmvr2Hc","title":"William Byrd on \"The Most Beautiful Program Ever Written\" [PWL NYC]","channel":"PapersWeLove","summary":"William Byrd presents at Papers We Love NYC on what he calls the most beautiful program ever written, a Lisp interpreter written in Lisp. He walks through the metacircular interpreter and related ideas, and demos relational programming and program synthesis near the end.","why":"HN repeatedly recommends it as an amazing talk that derives the essence of Lisp and shows miniKanren-style program synthesis.","type":"talk","level":"intermediate","score":14.0,"topics":["Languages & compilers"],"recs":11,"years":[2017,2026],"quote":"I can''t recommend the talk Dr Byrd did on this enough","quote_url":"https://news.ycombinator.com/item?id=28116076","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4fFDFbi3toc','hn',13.5,'{"vid":"4fFDFbi3toc","title":"\"Testing Distributed Systems w/ Deterministic Simulation\" by Will Wilson","channel":"Strange Loop Conference","summary":"Will Wilson of FoundationDB explains how the team tested their distributed database using deterministic simulation. By running the whole system in a simulator with injected faults and reproducible seeds, they could find rare concurrency and network bugs.","why":"HN treats it as the canonical talk on simulation testing and a mind-blowing example of how far rigorous testing can go.","type":"talk","level":"intermediate","score":13.5,"topics":["Databases & distributed","Software design & craft"],"recs":12,"years":[2014,2024],"quote":"this is one of the most amazing talks on distributed systems","quote_url":"https://news.ycombinator.com/item?id=18563988","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('EZ05e7EMOLM','hn',13.5,'{"vid":"EZ05e7EMOLM","title":"🚀  TDD, Where Did It All Go Wrong (Ian Cooper)","channel":"DevTernity Conference","summary":"Ian Cooper''s DevTernity talk revisits Kent Beck''s original TDD ideas and shows where misunderstandings crept in. It argues tests should target behaviors through public interfaces rather than implementation details, so suites support refactoring instead of resisting it.","why":"HN repeatedly calls it the best talk on testing, and many say it changed how they approach tests, mocks and the meaning of a unit.","type":"talk","level":"intermediate","score":13.5,"topics":["Software design & craft"],"recs":11,"years":[2018,2024],"quote":"This excellent talk completely changed the way I approached testing. Every developer who writes tests needs to watch this now!","quote_url":"https://news.ycombinator.com/item?id=26531969","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('aAb7hSCtvGw','hn',13.5,'{"vid":"aAb7hSCtvGw","title":"How To Design A Good API and Why it Matters","channel":"Google TechTalks","summary":"Joshua Bloch''s Google Tech Talk on how to design good APIs and why it matters, with concrete principles and examples. It treats every programmer as an occasional API designer.","why":"HN repeatedly names it the best resource on API design, a staple answer to any ''how do I design an API'' question.","type":"talk","level":"intermediate","score":13.5,"topics":["Software design & craft","Languages & compilers"],"recs":12,"years":[2011,2025],"quote":"Absolutely far and away the best resource that I found was this Google TechTalk by Joshua Bloch","quote_url":"https://news.ycombinator.com/item?id=3663104","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-6BsiVyC1kM','hn',13.0,'{"vid":"-6BsiVyC1kM","title":"The Value of Values with Rich Hickey","channel":"InfoQ","summary":"Rich Hickey''s JaxConf 2012 keynote examines what values are and why immutable values matter as information systems grow more complex and data gets bigger. It contrasts places with values and builds the case for immutability.","why":"HN commenters cite it as the talk that convinced them of immutability and functional programming.","type":"talk","level":"intermediate","score":13.0,"topics":["Languages & compilers","Databases & distributed"],"recs":10,"years":[2014,2023],"quote":"is what finally sold me on the benefits of pure functional programming and immutable data structures.","quote_url":"https://news.ycombinator.com/item?id=19296780","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QyJZzq0v7Z4','hn',13.0,'{"vid":"QyJZzq0v7Z4","title":"Why Isn''t Functional Programming the Norm? – Richard Feldman","channel":"Metosin","summary":"Richard Feldman argues that functional programming is not the norm largely because of historical accidents, such as C++ popularity, platform exclusivity, marketing spend and network effects, rather than merit. He traces the history of how languages become mainstream.","why":"HN treats it as the standard answer to why FP isn''t mainstream and why languages succeed.","type":"talk","level":"general","score":13.0,"topics":["Languages & compilers"],"recs":12,"years":[2019,2025],"quote":"This talk by Richard Feldman is an excellent discussion about why Functional Programming is not the norm","quote_url":"https://news.ycombinator.com/item?id=28515333","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YR5WdGrpoug','hn',13.0,'{"vid":"YR5WdGrpoug","title":"Maybe Not - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s Clojure/Conj 2018 keynote argues that Maybe/Option types and rigid type signatures are a poor way to model data that changes over time. He builds the case around optionality, schema growth and compatibility, and presents the ideas behind Clojure spec as an alternative.","why":"HN commenters send people to it whenever nulls, Maybe/Option or static typing come up, as a thoughtful dissent from the type-system orthodoxy that changes how some people model data.","type":"talk","level":"intermediate","score":13.0,"topics":["Languages & compilers"],"recs":14,"years":[2018,2025],"quote":"Rich Hickey''s \"Maybe Not\" should be watched by anyone who thinks nulls/nils/undefineds are okay.","quote_url":"https://news.ycombinator.com/item?id=18603634","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vK1DazRK_a0','hn',13.0,'{"vid":"vK1DazRK_a0","title":"Solving Problems the Clojure Way - Rafal Dittwald","channel":"Clojure/north","summary":"Rafal Dittwald''s Clojure/north talk shows how to move from writing Java-style code in Clojure to thinking in data-driven, functional terms. He walks through a JavaScript example, refactoring imperative code step by step into a functional core.","why":"HN repeatedly recommends it as a fantastic demonstration of procedural, OOP and FP approaches to the same problem, and of functional core and imperative shell.","type":"talk","level":"intermediate","score":13.0,"topics":["Languages & compilers","Software design & craft"],"recs":10,"years":[2019,2025],"quote":"I urge you to watch this fantastic video which illustrates procedural, OOP(lite), and FP approaches to a sample problem","quote_url":"https://news.ycombinator.com/item?id=30294814","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wjZofJX0v4M','hn',13.0,'{"vid":"wjZofJX0v4M","title":"Transformers, the tech behind LLMs | Deep Learning Chapter 5","channel":"3Blue1Brown","summary":"3Blue1Brown''s visual explanation of how transformers and GPT-style language models work, tracing data through tokens, embeddings and attention.","why":"HN treats it as the go-to visual introduction to transformers, and many say it finally made attention and embeddings click.","type":"explainer","level":"intro","score":13.0,"topics":["AI & ML","LLMs"],"recs":13,"years":[2024,2026],"quote":"what bade me finally understand the transformer architecture [0] and attention [1], are 3Blue1Brown''s videos.","quote_url":"https://news.ycombinator.com/item?id=40873442","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-J_xL4IGhJA','hn',12.5,'{"vid":"-J_xL4IGhJA","title":"Lecture 1A: Overview and Introduction to Lisp","channel":"MIT OpenCourseWare","summary":"The first lecture of MIT''s 6.001 (SICP) with Abelson and Sussman, giving an overview of the course and an introduction to Lisp. It argues that computer science is about managing complexity and abstraction, not computers.","why":"HN people recommend the SICP lectures as a deeper, livelier route into the book and a formative course even for seasoned programmers.","type":"lecture","level":"intro","score":12.5,"topics":["DSA","Languages & compilers"],"recs":10,"years":[2019,2026],"quote":"I watched and cannot recommend it enough, even for seasoned programmers","quote_url":"https://news.ycombinator.com/item?id=26298412","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZSRHeXYDLko','hn',12.5,'{"vid":"ZSRHeXYDLko","title":"Preventing the Collapse of Civilization / Jonathan Blow (Thekla, Inc)","channel":"DevGAMM","summary":"A DevGAMM talk by Jonathan Blow arguing that civilizations can lose technological capability and that software quality is already deteriorating. He discusses how knowledge fails to transfer between generations.","why":"It is the standard link in HN threads about software decay, lost knowledge and fragile technological civilization.","type":"talk","level":"general","score":12.5,"topics":["Systems & performance"],"recs":14,"years":[2020,2025],"quote":"Anyone who finds this concept interesting to think about and hasn''t seen this video may enjoy it","quote_url":"https://news.ycombinator.com/item?id=29568085","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('a9xAKttWgP4','hn',12.5,'{"vid":"a9xAKttWgP4","title":"Conway''s Game Of Life in APL","channel":"Dyalog","summary":"A short Dyalog demonstration building Conway''s Game of Life in a single line of APL, step by step. It shows how array operations replace loops.","why":"Recommended whenever APL or array languages come up as the quickest way to see why the paradigm is so striking.","type":"demo","level":"intro","score":12.5,"topics":["Languages & compilers"],"recs":11,"years":[2010,2024],"quote":"Try watching this video; it will only take you 8 minutes","quote_url":"https://news.ycombinator.com/item?id=21302127","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('r-TLSBdHe1A','hn',12.5,'{"vid":"r-TLSBdHe1A","title":"\"Performance Matters\" by Emery Berger","channel":"Strange Loop Conference","summary":"Emery Berger explains why performance is hard to measure and deliver on modern hardware, showing how code layout and alignment can swamp optimization effects. He presents Stabilizer for statistically sound evaluation and Coz, a causal profiler.","why":"It is the standard recommendation for anyone puzzled by unexplained benchmark changes from tiny code edits, and for learning about causal profiling.","type":"talk","level":"intermediate","score":12.5,"topics":["Systems & performance","Software design & craft"],"recs":12,"years":[2019,2025],"quote":"this is the most amazing optimisation information I have seen","quote_url":"https://news.ycombinator.com/item?id=23056029","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JxAXlJEmNMg','hn',12.0,'{"vid":"JxAXlJEmNMg","title":"Crockford on JavaScript - Volume 1: The Early Years","channel":"YUI Library","summary":"Douglas Crockford''s first Yahoo lecture puts JavaScript in historical context. He traces the language''s structure and quirks back through the early decades of computer science and programming language history.","why":"HN repeatedly recommends the Crockford series as a must-watch history of computing and programming languages, and as a way to learn to think in JavaScript.","type":"lecture","level":"intro","score":12.0,"topics":["Web","Languages & compilers"],"recs":10,"years":[2013,2022],"quote":"I urge you to watch this. It really is worth it!","quote_url":"https://news.ycombinator.com/item?id=7150830","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SWEts0rlezA','hn',12.0,'{"vid":"SWEts0rlezA","title":"RailsConf 2016 -  Turbolinks 5: I Can’t Believe It’s Not Native! by Sam Stephenson","channel":"Confreaks","summary":"Sam Stephenson''s RailsConf 2016 talk on Turbolinks 5, showing how small teams can ship fast Rails apps in the browser and hybrid iOS and Android apps sharing one set of web views.","why":"Repeatedly urged on people choosing a stack, as a case against heavy SPA complexity and for shared web and native code.","type":"talk","level":"intermediate","score":12.0,"topics":["Web","Languages & compilers"],"recs":6,"years":[2017,2020],"quote":"I highly recommend this talk on managing the complexity of basecamp and sharing a codebase between web and native apps.","quote_url":"https://news.ycombinator.com/item?id=16549202","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('_ahvzDzKdB0','hn',12.0,'{"vid":"_ahvzDzKdB0","title":"Growing a Language, by Guy Steele","channel":"Bill Pugh","summary":"Guy Steele''s 1998 OOPSLA keynote on designing a programming language that its users can grow. He builds the talk using only one-syllable words and terms he has defined, to demonstrate the idea.","why":"HN considers it one of the best technical talks ever and cites it in discussions of language design, small cores and extensibility.","type":"talk","level":"intermediate","score":12.0,"topics":["Languages & compilers"],"recs":11,"years":[2014,2026],"quote":"This is probably the best talk ever on the general topic","quote_url":"https://news.ycombinator.com/item?id=31210903","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bmSAYlu0NcY','hn',12.0,'{"vid":"bmSAYlu0NcY","title":"A Philosophy of Software Design | John Ousterhout | Talks at Google","channel":"Talks at Google","summary":"John Ousterhout, Stanford professor and creator of Tcl, presents the ideas of his book A Philosophy of Software Design in a Talks at Google session. He covers managing complexity, deep modules and interfaces, and what he teaches in his Stanford software design course.","why":"HN treats it as the standard one-hour teaser for the book and recommends it for its deep-modules thinking before buying or reading the book.","type":"talk","level":"intermediate","score":12.0,"topics":["Software design & craft"],"recs":11,"years":[2018,2026],"quote":"This google talk is a condensed version of the (already small - 150 pags IIRC) book. I highly recommend both.","quote_url":"https://news.ycombinator.com/item?id=41019916","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kZRE7HIO3vk','hn',12.0,'{"vid":"kZRE7HIO3vk","title":"The Thirty Million Line Problem","channel":"Molly Rocket","summary":"Casey Muratori''s long talk arguing that modern software has ballooned to tens of millions of lines because of hardware and OS diversity. He proposes a stable ISA for entire system-on-a-chip packages and recalls when games shipped with their own boot disk.","why":"HN recommends it, long as it is, as an eye-opening rant on software complexity and why systems became so complicated.","type":"talk","level":"intermediate","score":12.0,"topics":["Systems & performance"],"recs":11,"years":[2018,2024],"quote":"The video is long, but it''s worth watching all of it.","quote_url":"https://news.ycombinator.com/item?id=17062666","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ncHmEUmJZf4','hn',12.0,'{"vid":"ncHmEUmJZf4","title":"CppCon 2017: Matt Kulukundis “Designing a Fast, Efficient, Cache-friendly Hash Table, Step by Step”","channel":"CppCon","summary":"Matt Kulukundis explains how Google designed SwissTable, a fast, cache-friendly hash table, step by step from std::unordered_map. The talk covers open addressing, SIMD probing and the tradeoffs of changing a fundamental data structure.","why":"HN repeatedly cites it as the definitive explanation of SwissTable, the design behind Abseil, Rust''s hash map and Go''s maps.","type":"talk","level":"advanced","score":12.0,"topics":["DSA","Systems & performance"],"recs":9,"years":[2018,2026],"quote":"Excellent talk which explains the concepts really clearly and concisely.","quote_url":"https://news.ycombinator.com/item?id=49082650","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2V1FtfBDsLU','hn',11.5,'{"vid":"2V1FtfBDsLU","title":"Effective Programs - 10 Years of Clojure - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s talk at Clojure''s tenth anniversary on the kind of programs Clojure is designed for. He argues for situated programs that deal with changing requirements, and for dynamic typing and data over static types.","why":"HN''s go-to link in typing debates and for talk lists, and several call it their favorite programming talk even for non-Clojure users.","type":"talk","level":"intermediate","score":11.5,"topics":["Languages & compilers"],"recs":10,"years":[2017,2026],"quote":"Whole video is gold, is my fav programming talk of all time.","quote_url":"https://news.ycombinator.com/item?id=23420385","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2y5Pv4yN0b0','hn',11.5,'{"vid":"2y5Pv4yN0b0","title":"Brian Goetz - Stewardship: the Sobering Parts","channel":"ClojureTV","summary":"Java Language Architect Brian Goetz talks at a Clojure conference about the challenges of evolving a mature language like Java while preserving compatibility with existing code and developer expectations. It also gives a look at where the platform is headed.","why":"HN repeatedly recommends it as the definitive explanation of why Java evolves cautiously and why compatibility matters in language design.","type":"talk","level":"intermediate","score":11.5,"topics":["Languages & compilers"],"recs":10,"years":[2014,2025],"quote":"Brian Goetz''s talk nails it on the head why the languages in my day-to-day are sub-optimal","quote_url":"https://news.ycombinator.com/item?id=9488098","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HaEPXoXVf2k','hn',11.5,'{"vid":"HaEPXoXVf2k","title":"AWS re:Invent 2018: Amazon DynamoDB Deep Dive: Advanced Design Patterns for DynamoDB (DAT401)","channel":"Amazon Web Services","summary":"Rick Houlihan''s AWS re:Invent 2018 deep dive on advanced DynamoDB design patterns. It covers index overloading, GSI sharding, composite keys, graph processing and transactions.","why":"The go-to recommendation for learning DynamoDB data modeling, with many saying it made access-pattern-driven design click.","type":"talk","level":"advanced","score":11.5,"topics":["Databases & distributed"],"recs":12,"years":[2019,2025],"quote":"I highly recommend every engineer to watch it: it''s a great overview of SQL vs NoSQL","quote_url":"https://news.ycombinator.com/item?id=30009915","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('UzxYlbK2c7E','hn',11.5,'{"vid":"UzxYlbK2c7E","title":"Lecture 1 | Machine Learning (Stanford)","channel":"Stanford","summary":"The first lecture of Andrew Ng''s Stanford CS229 Machine Learning course, giving an overview of the course. It introduces supervised and unsupervised learning, learning theory and reinforcement learning.","why":"Recommended as the rigorous, math-heavy original course, deeper than the Coursera version, for learning machine learning.","type":"course","level":"intermediate","score":11.5,"topics":["AI & ML"],"recs":11,"years":[2008,2020],"quote":"I''d suggest going back to the original youtube[1] and course materials[2].","quote_url":"https://news.ycombinator.com/item?id=7120893","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('WpkDN78P884','hn',11.5,'{"vid":"WpkDN78P884","title":"Ruby Midwest 2011 - Keynote: Architecture the Lost Years by Robert Martin","channel":"Confreaks","summary":"Robert C. Martin''s Ruby Midwest 2011 keynote argues that software architecture should express the application''s intent rather than its framework. He covers separating entities, interactors and boundaries so the web, database and framework are details.","why":"Frequently recommended as an influential talk on decoupled, testable architecture, though some commenters push back on Martin''s TDD advocacy.","type":"talk","level":"intermediate","score":11.5,"topics":["Software design & craft","Languages & compilers"],"recs":10,"years":[2013,2022],"quote":"The talk that had the most influence on how I write software is Robert ''Uncle Bob'' Martin''s \"Architecture: The Lost Years","quote_url":"https://news.ycombinator.com/item?id=18218259","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('c12cYAUTXXs','hn',11.5,'{"vid":"c12cYAUTXXs","title":"Erlang Factory 2014 - That''s ''Billion'' with a ''B'': Scaling to the Next Level at WhatsApp","channel":"Erlang Solutions","summary":"Rick Reed of WhatsApp explains at Erlang Factory 2014 how the service scaled to billions of messages with a very small engineering team. He covers the FreeBSD and Erlang stack, Mnesia usage, server counts and bottleneck work.","why":"The go-to talk showing how Erlang let a tiny team run a massive messaging system.","type":"talk","level":"advanced","score":11.5,"topics":["Databases & distributed","Languages & compilers"],"recs":6,"years":[2014,2022],"quote":"watch this talk and imagine trying to recreate that system with only a handful of server engineers","quote_url":"https://news.ycombinator.com/item?id=14748689","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dP1xVpMPn8M','hn',11.5,'{"vid":"dP1xVpMPn8M","title":"A Tour of the Acme Editor","channel":"Russ Cox","summary":"Russ Cox gives a 23-minute tour of the Acme text editor from Plan 9, showing its mouse-driven interface, executing commands from text, and its filesystem-based interface to other programs.","why":"HN points people to it as the best introduction to Acme and its very different take on editors, shells, and GUIs.","type":"tutorial","level":"intro","score":11.5,"topics":["Software design & craft"],"recs":11,"years":[2012,2026],"quote":"Russ Cox has a great video tour of Acme''s features here","quote_url":"https://news.ycombinator.com/item?id=7828961","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('f84n5oFoZBc','hn',11.5,'{"vid":"f84n5oFoZBc","title":"Hammock Driven Development - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s philosophical talk from the first Clojure Conj in 2010. He argues that good design comes from deliberate, away-from-keyboard thinking, and describes how to feed the background mind so it solves problems.","why":"HN returns to it constantly as permission and method for thinking deeply before coding, and as an antidote to always-working anxiety.","type":"talk","level":"general","score":11.5,"topics":["Languages & compilers","Software design & craft"],"recs":12,"years":[2014,2024],"quote":"Both of these talks are in my top 5.","quote_url":"https://news.ycombinator.com/item?id=11183901","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hQVTIJBZook','hn',11.5,'{"vid":"hQVTIJBZook","title":"JavaScript: The Good Parts","channel":"Google TechTalks","summary":"Douglas Crockford''s 2009 Google tech talk on the good and bad parts of JavaScript, based on his book. He argues for using a reliable subset of the language and avoiding its flawed features.","why":"A classic recommended to people learning JavaScript, even though some find it dogmatic and dated.","type":"talk","level":"intermediate","score":11.5,"topics":["Web","Languages & compilers"],"recs":11,"years":[2009,2020],"quote":"This video changed my mind","quote_url":"https://news.ycombinator.com/item?id=6634645","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-zRN7XLCRhc','hn',11.0,'{"vid":"-zRN7XLCRhc","title":"LISA11 - Fork Yeah! The Rise and Development of illumos","channel":"USENIX","summary":"Bryan Cantrill''s LISA11 talk on how illumos arose after Oracle closed OpenSolaris. It covers the history of Sun, ZFS, DTrace and Zones, and the diaspora of kernel engineers, with a famous rant about Oracle and Larry Ellison.","why":"HN points to it as the definitive, entertaining account of Sun''s fate under Oracle, and quotes its Ellison lawnmower advice whenever Oracle behaves badly.","type":"talk","level":"general","score":11.0,"topics":["Systems & performance"],"recs":9,"years":[2012,2026],"quote":"If you''re interested how it came to be check out this epic talk by Bryan Cantrill","quote_url":"https://news.ycombinator.com/item?id=13082671","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4XpnKHJAok8','hn',11.0,'{"vid":"4XpnKHJAok8","title":"Tech Talk: Linus Torvalds on git","channel":"Google","summary":"Linus Torvalds gives a Google tech talk on git, the source control system he created two years earlier. He argues for distributed version control over centralized systems such as CVS and Subversion.","why":"HN repeatedly recommends it as the iconic explanation of why git is designed as it is and why distributed VCS beats centralized ones.","type":"talk","level":"general","score":11.0,"topics":["Software design & craft"],"recs":9,"years":[2007,2023],"quote":"This talk by Linus is iconic, if you haven''t watched it you should.","quote_url":"https://news.ycombinator.com/item?id=38128071","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7xTGNNLPyMI','hn',11.0,'{"vid":"7xTGNNLPyMI","title":"Deep Dive into LLMs like ChatGPT","channel":"Andrej Karpathy","summary":"Andrej Karpathy''s three-hour-plus general-audience deep dive into how ChatGPT-style LLMs are built, covering the full training stack from pretraining to post-training. It also gives mental models for their quirks, like hallucination, and how to use them well.","why":"HN''s most frequent recommendation for a clear, approachable foundation in how LLMs work without heavy math.","type":"lecture","level":"intro","score":11.0,"topics":["Karpathy","AI & ML","LLMs"],"recs":10,"years":[2025,2026],"quote":"I highly recommend Andrej Karpathy''s Deep Dive into LLMs like ChatGPT","quote_url":"https://news.ycombinator.com/item?id=47002572","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ShEez0JkOFw','hn',11.0,'{"vid":"ShEez0JkOFw","title":"Tim Ewald - Clojure: Programming with Hand Tools","channel":"ClojureTV","summary":"Tim Ewald''s Clojure/conj talk uses furniture making with hand tools versus machine tools as an allegory for software. It explores how automation changes what we make and how we think about our work, and why Clojure''s small set of simple tools matters.","why":"HN repeatedly names it among the best programming talks, loved for its craftsmanship message that complex tooling can hide simpler solutions.","type":"talk","level":"general","score":11.0,"topics":["Languages & compilers"],"recs":9,"years":[2014,2024],"quote":"I loved this talk on how as your tooling becomes more complex and automated, you start to lose sight of simpler solutions to problems.","quote_url":"https://news.ycombinator.com/item?id=18218165","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZhuHCtR3xq8','hn',11.0,'{"vid":"ZhuHCtR3xq8","title":"Brian Beckman: Don''t fear the Monad","channel":"jasonofthel33t","summary":"Microsoft''s Brian Beckman gives an hour-long, whiteboard-style walk through monads, building from function composition and monoids using school-level math. It is aimed at practicing programmers rather than category theorists.","why":"HN repeatedly recommends it as the clearest and most correct beginner explanation of monads, with several commenters saying it finally made them click.","type":"lecture","level":"intro","score":11.0,"topics":["Languages & compilers"],"recs":9,"years":[2012,2024],"quote":"This video is all you, as a practicing programmer, need to know about monads and it''s just 1 hour long.","quote_url":"https://news.ycombinator.com/item?id=10058830","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fU9hR3kiOK0','hn',11.0,'{"vid":"fU9hR3kiOK0","title":"\"Turning the database inside out with Apache Samza\" by Martin Kleppmann","channel":"Strange Loop Conference","summary":"Martin Kleppmann argues that databases are global shared mutable state and proposes treating them as an ever-growing log of immutable facts. Derived data such as caches, indexes and views is then built by stream processors like Apache Samza. The talk draws on Kafka and LinkedIn''s experience with commit logs.","why":"Commenters repeatedly cite it as the talk that reframed how they think about caching, derived data and event sourcing.","type":"talk","level":"intermediate","score":11.0,"topics":["Databases & distributed"],"recs":9,"years":[2015,2025],"quote":"This talk on Apache Samza completely changed how I think about caching and derived data in general","quote_url":"https://news.ycombinator.com/item?id=45084830","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lJ8ydIuPFeU','hn',11.0,'{"vid":"lJ8ydIuPFeU","title":"\"How NOT to Measure Latency\" by Gil Tene","channel":"Strange Loop Conference","summary":"Gil Tene of Azul Systems explains common pitfalls in measuring latency and response time, including why averages mislead and the problem of coordinated omission. He introduces open source tools like HdrHistogram for better measurement and reporting.","why":"The canonical recommendation whenever percentiles, tail latency, load testing or averages come up, described by some as life changing.","type":"talk","level":"intermediate","score":11.0,"topics":["Systems & performance","Software design & craft"],"recs":9,"years":[2015,2026],"quote":"This a life changing video by Gil Tene on this topic.","quote_url":"https://news.ycombinator.com/item?id=22797291","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('yTkzNHF6rMs','hn',11.0,'{"vid":"yTkzNHF6rMs","title":"Ruby Conf 12 - Boundaries by Gary Bernhardt","channel":"Confreaks","summary":"Gary Bernhardt''s RubyConf 2012 talk on testing in isolation without mocking everything. It goes through behavior versus data, mutation versus immutability, and how a functional core with an imperative shell yields natural isolation and parallelism.","why":"HN recommends it as the canonical presentation of ''functional core, imperative shell'' and a practical answer to unit versus integration testing.","type":"talk","level":"intermediate","score":11.0,"topics":["Software design & craft"],"recs":8,"years":[2015,2024],"quote":"I highly recommend this video for a more philosophical take on how to do \"impure FP\" without OO","quote_url":"https://news.ycombinator.com/item?id=22558873","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zBkNBP00wJE','hn',11.0,'{"vid":"zBkNBP00wJE","title":"CppCon 2016: Jason Turner “Rich Code for Tiny Computers: A Simple Commodore 64 Game in C++17”","channel":"CppCon","summary":"Jason Turner''s CppCon 2016 talk builds a simple Commodore 64 game using C++17, showing how constexpr and const let a modern compiler produce tight 6502 code. He walks through assembly output to show abstractions being optimized away.","why":"A perennial favorite, recommended as proof that expressive modern C++ can compile to efficient code even on tiny retro hardware.","type":"talk","level":"intermediate","score":11.0,"topics":["Systems & performance"],"recs":13,"years":[2016,2024],"quote":"there is a wonderful talk by Jason Turner about writing a simple Pong clone for the Commodore 64 in modern C++","quote_url":"https://news.ycombinator.com/item?id=12774487","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('36myc8wQhLo','hn',10.5,'{"vid":"36myc8wQhLo","title":"USENIX ATC ''21/OSDI ''21 Joint Keynote Address-It''s Time for Operating Systems to Rediscover Hardware","channel":"USENIX","summary":"Timothy Roscoe of ETH Zurich delivers the joint USENIX ATC/OSDI 2021 keynote arguing that operating systems must reckon with modern hardware, which is a heterogeneous collection of processors, firmware and coprocessors rather than a simple machine. It shows how much runs below and beside Linux.","why":"Repeatedly recommended as a revelatory talk on how little control the main OS has over modern SoCs and PCs.","type":"talk","level":"intermediate","score":10.5,"topics":["Systems & performance"],"recs":12,"years":[2021,2026],"quote":"There''s this great USENIX talk by Timothy Roscoe [1]","quote_url":"https://news.ycombinator.com/item?id=33791375","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5IUj1EZwpJY','hn',10.5,'{"vid":"5IUj1EZwpJY","title":"The Only Unbreakable Law","channel":"Molly Rocket","summary":"Casey Muratori''s lecture, originally given at the Technical University of Madrid, arguing that Conway''s Law is the only viable candidate for a true law of software architecture. He explains how software mimics the organization over time, using examples like Windows'' multiple volume controls.","why":"HN treats it as the definitive explanation of Conway''s Law and links it in almost any thread about org structure shaping software.","type":"lecture","level":"general","score":10.5,"topics":["Software design & craft"],"recs":12,"years":[2022,2026],"quote":"Casey Muratori has an excellent lecture on this same topic","quote_url":"https://news.ycombinator.com/item?id=36655210","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8SkdfdXWYaI','hn',10.5,'{"vid":"8SkdfdXWYaI","title":"Using Python to Code by Voice","channel":"Next Day Video","summary":"Tavis Rudd describes how RSI forced him to program by voice, and shows the Python and Emacs Lisp system he built with voice recognition. A live demo creates and deploys a small system without touching the keyboard.","why":"Recurs in threads about RSI, accessibility and voice coding as the go-to demo of a custom spoken command language.","type":"talk","level":"intermediate","score":10.5,"topics":["Python","Software design & craft","Languages & compilers"],"recs":12,"years":[2013,2025],"quote":"Travis Rudd''s incredible demo of voice coding [1]","quote_url":"https://news.ycombinator.com/item?id=24185875","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8X69_42Mj-g','hn',10.5,'{"vid":"8X69_42Mj-g","title":"Clasp: Common Lisp using LLVM and C++ for Molecular Metaprogramming","channel":"Google TechTalks","summary":"Christian Schafmeister''s Google Tech Talk on designing spiroligomer molecules and building Clasp, a Common Lisp on LLVM that interoperates with C++, to program molecular design. It covers the chemistry, automatic differentiation for force fields, and how the compiler is built.","why":"HN repeatedly cites it as a striking example of Common Lisp used to push the frontier of science, and as one of the most inspiring tech talks.","type":"talk","level":"intermediate","score":10.5,"topics":["Languages & compilers"],"recs":8,"years":[2015,2024],"quote":"I challenge anyone to watch this lecture from Christian Schafmeister and say they are not impressed","quote_url":"https://news.ycombinator.com/item?id=11175151","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OSGv2VnC0go','hn',10.5,'{"vid":"OSGv2VnC0go","title":"Transforming Code into Beautiful, Idiomatic Python","channel":"Next Day Video","summary":"Raymond Hettinger''s PyCon 2013 talk on transforming code into idiomatic Python through a series of before-and-after refactorings. It shows how to use iterators, dictionaries, named tuples and other language features well.","why":"HN treats it as a must-watch classic for writing Pythonic code, though somewhat dated for modern Python.","type":"talk","level":"intermediate","score":10.5,"topics":["Python","Languages & compilers"],"recs":9,"years":[2014,2022],"quote":"the excellent talk \"Transforming Code into Beautiful, Idiomatic Python\".","quote_url":"https://news.ycombinator.com/item?id=25890731","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('TH9VCN6UkyQ','hn',10.5,'{"vid":"TH9VCN6UkyQ","title":"Ideas about a new programming language for games.","channel":"Jonathan Blow","summary":"Jonathan Blow''s first talk on designing a new programming language for games, which became Jai. He explains the problems with C++ and why Go, Rust and D do not fit game development.","why":"HN programmers recommend it, and the Jai series that followed, for the game-industry view on replacing C++ and for watching a language being invented.","type":"talk","level":"intermediate","score":10.5,"topics":["Languages & compilers"],"recs":7,"years":[2014,2025],"quote":"I also found watching his process for inventing the language extremely instructive, just as a programmer.","quote_url":"https://news.ycombinator.com/item?id=17454615","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('WUvTyaaNkzM','hn',10.5,'{"vid":"WUvTyaaNkzM","title":"The essence of calculus","channel":"3Blue1Brown","summary":"The first video of 3Blue1Brown''s Essence of Calculus series, which builds toward integrals, derivatives, and the fundamental theorem of calculus from a simple geometry question. It aims to make viewers feel they could have invented calculus themselves.","why":"A staple recommendation for anyone learning math, praised for visual intuition that makes memorized formulas make sense.","type":"course","level":"intro","score":10.5,"topics":["Math for ML"],"recs":10,"years":[2017,2025],"quote":"When I discovered that video, all the formulas they tried to make me memorize started making a LOT more sense.","quote_url":"https://news.ycombinator.com/item?id=36358316","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XA2WjJbmmoM','hn',10.5,'{"vid":"XA2WjJbmmoM","title":"How to Do 90% of What Plugins Do (With Just Vim)","channel":"thoughtbot","summary":"A thoughtbot meetup talk by Max Cantor on getting most of what popular plugins provide using only built-in Vim features. It covers autocomplete, file jumping, filesystem navigation, build integration and snippets, with slides and a vimrc available.","why":"HN treats it as the canonical talk for the case that vanilla Vim goes a long way and plugin dependencies are a burden.","type":"talk","level":"intermediate","score":10.5,"topics":["Software design & craft"],"recs":10,"years":[2016,2025],"quote":"Max Cantor has a great talk about that on YouTube","quote_url":"https://news.ycombinator.com/item?id=17431062","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('h7apO7q16V0','hn',10.5,'{"vid":"h7apO7q16V0","title":"The Fast Fourier Transform (FFT): Most Ingenious Algorithm Ever?","channel":"Reducible","summary":"Reducible''s visual walkthrough of the Fast Fourier Transform, motivated by polynomial multiplication. It shows how the FFT''s key ideas can be discovered by asking the right questions.","why":"HN repeatedly calls it a fantastic explanation that made FFT click, with some rewatching it periodically.","type":"explainer","level":"intermediate","score":10.5,"topics":["DSA"],"recs":7,"years":[2021,2026],"quote":"It derives the FFT algorithm from polynomial multiplication and it’s fantastic . I rewatch it every 6 months or so.","quote_url":"https://news.ycombinator.com/item?id=40846259","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oyLBGkS5ICk','hn',10.5,'{"vid":"oyLBGkS5ICk","title":"Spec-ulation Keynote - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s keynote on software versioning, arguing that breaking changes are the real problem and that libraries should only grow by providing more and requiring less. It critiques semantic versioning and ties into Clojure spec.","why":"HN returns to it in every versioning and API stability debate as a challenging, contrarian talk worth watching.","type":"talk","level":"intermediate","score":10.5,"topics":["Software design & craft","Languages & compilers"],"recs":10,"years":[2016,2024],"quote":"Whenever an idea about API versioning springs into mind it is always worthwhile to watch Rich Hickey''s Spec-ulation talk","quote_url":"https://news.ycombinator.com/item?id=15025489","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('p33CVV29OG8','hn',10.5,'{"vid":"p33CVV29OG8","title":"Modern Dictionaries by Raymond Hettinger","channel":"SF Python","summary":"Python core developer Raymond Hettinger explains how Python''s dictionary implementation evolved into the compact, ordered dict in Python 3.6. He uses pictures and small bits of pure Python, and covers key-sharing, compaction and versioning.","why":"HN treats it as the definitive, engaging talk on hash table internals and Python dict ordering, and recommends it in tech-talk lists.","type":"talk","level":"intermediate","score":10.5,"topics":["Python","DSA","Languages & compilers"],"recs":9,"years":[2016,2025],"quote":"one of the most insightful videos I''ve seen in a long time.","quote_url":"https://news.ycombinator.com/item?id=13273961","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pgoetgxecw8','hn',10.5,'{"vid":"pgoetgxecw8","title":"Refterm Lecture Part 1 - Philosophies of Optimization","channel":"Molly Rocket","summary":"Casey Muratori''s first refterm lecture lays out philosophies of optimization, distinguishing optimization from non-pessimization, which means avoiding needless work. It uses his fast terminal renderer project to show how fast computers really are.","why":"HN returns to it constantly in software performance debates as the primer on non-pessimization and why modern software is slow.","type":"lecture","level":"intermediate","score":10.5,"topics":["Systems & performance"],"recs":10,"years":[2021,2026],"quote":"The video on Philosophies of Optimisation is a good primer on the tenets of the course.","quote_url":"https://news.ycombinator.com/item?id=42213459","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rX0ItVEVjHc','hn',10.5,'{"vid":"rX0ItVEVjHc","title":"CppCon 2014: Mike Acton \"Data-Oriented Design and C++\"","channel":"CppCon","summary":"Mike Acton of Insomniac Games argues that a program''s purpose is transforming data, and shows how common C++ approaches work against that in performance-critical game development. He covers cache behavior, data layout and the limits of compilers.","why":"It is the go-to talk HN points to for data-oriented design and hardware-aware performance thinking, despite Acton''s blunt style.","type":"talk","level":"intermediate","score":10.5,"topics":["Software design & craft","Systems & performance"],"recs":9,"years":[2015,2026],"quote":"one of the most digestible ways to start thinking about performance in high throughput systems","quote_url":"https://news.ycombinator.com/item?id=47004811","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2pWv7GOvuf0','hn',10.0,'{"vid":"2pWv7GOvuf0","title":"RL Course by David Silver - Lecture 1: Introduction to Reinforcement Learning","channel":"Google DeepMind","summary":"The first lecture of David Silver''s reinforcement learning course, introducing the field and its basic concepts. The course follows the Sutton and Barto textbook.","why":"Frequently recommended as an excellent, clear introductory RL course from the lead of AlphaGo, pairing well with Sutton and Barto.","type":"course","level":"intro","score":10.0,"topics":["AI & ML"],"recs":9,"years":[2017,2026],"quote":"Really clear explanations that went hand in hand when I was reading Sutton and Barto''s introductory book.","quote_url":"https://news.ycombinator.com/item?id=22754933","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2sjqTHE0zok','hn',10.0,'{"vid":"2sjqTHE0zok","title":"Lecture 6: Version Control (git) (2020)","channel":"Missing Semester","summary":"A lecture from MIT''s Missing Semester course covering version control with git. It builds up git from its data model rather than from commands.","why":"HN frequently calls it the best single video on git because it teaches the underlying data structures.","type":"lecture","level":"intro","score":10.0,"topics":["Software design & craft"],"recs":9,"years":[2020,2023],"quote":"I think that this video should be considered mandatory viewing if you''re a developer using Git","quote_url":"https://news.ycombinator.com/item?id=38119329","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('443UNeGrFoM','hn',10.0,'{"vid":"443UNeGrFoM","title":"How I program C","channel":"Eskil Steenberg","summary":"Eskil Steenberg''s two-hour talk on his personal approach to writing C, covering code style, structure, naming, pointers and large-project organization. He warns it contains a fair bit of programming religion.","why":"HN recommends it as the one long programming video worth watching, a provocative and influential take on C.","type":"talk","level":"intermediate","score":10.0,"topics":["Systems & performance","Software design & craft"],"recs":8,"years":[2017,2025],"quote":"the only 2 hour YouTube video I''ll ever recommend","quote_url":"https://news.ycombinator.com/item?id=34106174","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('I8LbkfSSR58','hn',10.0,'{"vid":"I8LbkfSSR58","title":"Category Theory 1.1: Motivation and Philosophy","channel":"Bartosz Milewski","summary":"The first lecture in Bartosz Milewski''s category theory series for programmers. It covers the motivation and philosophy behind category theory and why composition matters for handling complexity.","why":"HN commenters repeatedly name it as the friendliest entry point to category theory for working programmers.","type":"lecture","level":"intro","score":10.0,"topics":["Languages & compilers"],"recs":11,"years":[2016,2026],"quote":"I think they are a very nice place to start learning these things.","quote_url":"https://news.ycombinator.com/item?id=14127078","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ROor6_NGIWU','hn',10.0,'{"vid":"ROor6_NGIWU","title":"The Language of the System - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s 2013 talk applies language-design thinking to whole systems, covering names, queues, data, failure, and the interfaces between programs. It ends with a call to action for building systems holistically.","why":"HN recommends it as a key Hickey talk on system design that changes how people think about distributed state and interfaces.","type":"talk","level":"advanced","score":10.0,"topics":["Software design & craft","Languages & compilers"],"recs":10,"years":[2013,2025],"quote":"it has really changed the way I look at distributed persistent storage.","quote_url":"https://news.ycombinator.com/item?id=10445433","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('f6kdp27TYZs','hn',10.0,'{"vid":"f6kdp27TYZs","title":"Google I/O 2012 - Go Concurrency Patterns","channel":"Google for Developers","summary":"Rob Pike''s Google I/O 2012 talk shows how goroutines and channels solve tricky concurrency problems with simple Go code. It features a playful goroutine demo with gophers passing messages and a search engine example.","why":"The canonical recommendation for learning Go concurrency, praised as entertaining and clarifying when to use channels versus mutexes.","type":"talk","level":"intermediate","score":10.0,"topics":["Systems & performance","Databases & distributed"],"recs":9,"years":[2012,2025],"quote":"Great talk by Rob Pike","quote_url":"https://news.ycombinator.com/item?id=4218574","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kCc8FmEb1nY','hn',10.0,'{"vid":"kCc8FmEb1nY","title":"Let''s build GPT: from scratch, in code, spelled out.","channel":"Andrej Karpathy","summary":"Andrej Karpathy builds a GPT from scratch in code, following Attention Is All You Need and GPT-2/3, in about two hours using PyTorch. He connects it to ChatGPT and assumes familiarity with his earlier makemore videos.","why":"It is the go-to recommendation for learning how transformers and LLMs actually work, praised for its clarity and Karpathy''s teaching.","type":"tutorial","level":"intermediate","score":10.0,"topics":["Karpathy","AI & ML","LLMs"],"recs":14,"years":[2023,2025],"quote":"the best video I have seen on the topic","quote_url":"https://news.ycombinator.com/item?id=35800127","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('o9pEzgHorH0','hn',10.0,'{"vid":"o9pEzgHorH0","title":"Stop Writing Classes","channel":"Next Day Video","summary":"Jack Diederich''s PyCon 2012 talk argues that classes are overused in Python and walks through real code, refactoring away unnecessary classes, exceptions and modules. It popularized the heuristic that a class with two methods, one being __init__, should be a function.","why":"HN returns to it repeatedly as the canonical argument for simplicity and against premature abstraction, and several commenters say it changed how they write code.","type":"talk","level":"intermediate","score":10.0,"topics":["Python","Languages & compilers","Software design & craft"],"recs":8,"years":[2012,2025],"quote":"Jack Diederich has a great video called Stop Writing Classes: It''s about Python, but the observation can apply to several languages.","quote_url":"https://news.ycombinator.com/item?id=22563890","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('x7cQ3mrcKaY','hn',10.0,'{"vid":"x7cQ3mrcKaY","title":"Pete Hunt: React: Rethinking best practices -- JSConf EU","channel":"JSConf","summary":"Pete Hunt of Facebook and Instagram introduces React at JSConf EU 2013 and explains its design principles. He argues that separating templates from logic only separates technologies, not concerns, and makes the case for components.","why":"HN calls it the famous talk for understanding why React rejected separation of concerns by technology and for newcomers puzzled by JSX.","type":"talk","level":"intermediate","score":10.0,"topics":["Web","Software design & craft"],"recs":9,"years":[2014,2025],"quote":"See Pete Hunt''s famous talk","quote_url":"https://news.ycombinator.com/item?id=9556521","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZmNOAtZIgIk','hn',9.5,'{"vid":"ZmNOAtZIgIk","title":"Bay Area Vision Meeting: Unsupervised Feature Learning and Deep Learning","channel":"Google TechTalks","summary":"Andrew Ng presents unsupervised feature learning and deep learning, showing how algorithms can learn representations from unlabeled data instead of hand-designed features. He gives examples in vision and audio, including visualizations of features learned by successive layers.","why":"HN commenters recommended it for years as a simple, exciting overview of the deep learning wave.","type":"talk","level":"intermediate","score":9.5,"topics":["AI & ML"],"recs":9,"years":[2011,2013],"quote":"he explains very simply how all this works for images and some examples about the audio case.","quote_url":"https://news.ycombinator.com/item?id=4146995","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dCuZkaaou0Q','hn',9.5,'{"vid":"dCuZkaaou0Q","title":"Invited Talk - Guy Steele","channel":"ClojureTV","summary":"Guy Steele''s invited talk at Clojure/conj on the informal metanotation computer scientists use in papers to describe languages. He traces how this notation developed and why it is often unspecified and arcane.","why":"HN commenters recommend it whenever someone asks how to read type-system or CS notation in papers.","type":"talk","level":"intermediate","score":9.5,"topics":["Languages & compilers"],"recs":7,"years":[2017,2023],"quote":"Excellent talk by Guy Steele explaining the history of maths/comp notations","quote_url":"https://news.ycombinator.com/item?id=31605947","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dljNabciEGg','hn',9.5,'{"vid":"dljNabciEGg","title":"Literate Devops with Emacs","channel":"Howard Abrams","summary":"Howard Abrams demonstrates, in an EmacsConf 2015 talk, how he uses org-mode''s Babel and Tramp to configure and operate remote servers from a single document. Code blocks, their results and the explanatory text all live together.","why":"HN people point to it as the best demonstration of literate devops, showing documentation and execution woven together in Emacs.","type":"demo","level":"intermediate","score":9.5,"topics":["Software design & craft"],"recs":8,"years":[2015,2025],"quote":"His video on literate programming for DevOps via Emacs'' Org-mode was very impressive and inspiring to me. It''s my favorite.","quote_url":"https://news.ycombinator.com/item?id=36962621","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('jkrNMKz9pWU','hn',9.5,'{"vid":"jkrNMKz9pWU","title":"A Hackers'' Guide to Language Models","channel":"Jeremy Howard","summary":"Jeremy Howard''s 90-minute practical tour of language models. It covers how they work, GPT-4''s capabilities and limits, using the OpenAI API, code writing, data analysis and fine-tuning.","why":"Repeatedly named the best practical tutorial for using LLMs, with a well-liked fine-tuning section.","type":"tutorial","level":"intermediate","score":9.5,"topics":["AI & ML","LLMs"],"recs":8,"years":[2023,2024],"quote":"highly recommend \"Hackers Guide to language models\" by Jeremy Howard. 1.5h video packed with practical information","quote_url":"https://news.ycombinator.com/item?id=38412110","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kjBOesZCoqc','hn',9.5,'{"vid":"kjBOesZCoqc","title":"Essence of linear algebra preview","channel":"3Blue1Brown","summary":"A five-minute preview of 3Blue1Brown''s Essence of Linear Algebra series, which uses animation to build geometric intuition for topics from a standard linear algebra course.","why":"HN repeatedly recommends the series as the best intuition-first, visual introduction to linear algebra and a benchmark for clear math explanation.","type":"course","level":"intro","score":9.5,"topics":["Math for ML"],"recs":11,"years":[2016,2018],"quote":"3Blue1Brown''s youtube series I cannot recommend highly enough.","quote_url":"https://news.ycombinator.com/item?id=14116824","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xsSnOQynTHs','hn',9.5,'{"vid":"xsSnOQynTHs","title":"Dan Abramov - Live React: Hot Reloading with Time Travel at react-europe 2015","channel":"ReactEurope","summary":"Dan Abramov live-codes hot reloading with time-travel debugging at React Europe 2015, debuting Redux and its devtools. The slides themselves are driven by application state.","why":"Seen as the canonical Redux introduction and a model live-coding talk about better developer tools.","type":"talk","level":"intermediate","score":9.5,"topics":["Web","Software design & craft"],"recs":12,"years":[2015,2022],"quote":"One of my favourites I watched recently was Dan Abramov introducing React hot loading, Redux and Redux Dev Tools in the same 30 minute talk","quote_url":"https://news.ycombinator.com/item?id=16838949","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('1ffBJ4sVUb4','hn',9.0,'{"vid":"1ffBJ4sVUb4","title":"[Linux.conf.au 2013] - Git For Ages 4 And Up","channel":"HackersOnBoard","summary":"A Linux.conf.au 2013 talk that explains git''s internal model using a playful, toy-based approach. It presents git operations as operations on a graph of commits, aimed at people who find git confusing.","why":"HN repeatedly recommends it as the talk that finally makes git''s data model click for beginners, despite its odd title.","type":"talk","level":"intro","score":9.0,"topics":["Software design & craft"],"recs":8,"years":[2013,2023],"quote":"it''s the one video that allowed me to fully grasp everything","quote_url":"https://news.ycombinator.com/item?id=18513041","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HOuZyOKa91o','hn',9.0,'{"vid":"HOuZyOKa91o","title":"7 minutes of Pharo Smalltalk for Rubyists","channel":"Avdi Grimm","summary":"Ruby developer Avdi Grimm gives a seven-minute tour of Pharo Smalltalk''s development environment, focusing on tools like search-by-example and the integrated, live coding experience.","why":"HN recommends it as a quick, compelling look at what Smalltalk tooling feels like, especially for Ruby programmers.","type":"demo","level":"intro","score":9.0,"topics":["Languages & compilers","Software design & craft"],"recs":5,"years":[2017,2026],"quote":"As a Ruby developer this video about Pharo smalltalk made me a smalltalk believer","quote_url":"https://news.ycombinator.com/item?id=49244858","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Tb823aqgX_0','hn',9.0,'{"vid":"Tb823aqgX_0","title":"Bottom Up vs  Top Down Design in Clojure - Mark Bastian","channel":"ClojureTV","summary":"Mark Bastian contrasts top-down object-oriented design with bottom-up, data-oriented design in Clojure. He models a board game as plain data plus small composable functions and compares it with a roughly 22-class OOP version.","why":"HN repeatedly recommends it as the talk that made data-oriented, REPL-driven bottom-up design click.","type":"talk","level":"intermediate","score":9.0,"topics":["Languages & compilers","Software design & craft"],"recs":5,"years":[2016,2021],"quote":"is the talk that really made it clear to me how to design programs this way.","quote_url":"https://news.ycombinator.com/item?id=26943836","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XZ3w_jec1v8','hn',9.0,'{"vid":"XZ3w_jec1v8","title":"\"The Economics of Programming Languages\" by Evan Czaplicki (Strange Loop 2023)","channel":"Strange Loop Conference","summary":"Evan Czaplicki, creator of Elm, examines how programming languages are funded. He looks at where compiler engineers'' salaries come from, why Go has about 5 engineers while Dart has about 30, and how this limits language design.","why":"Recommended repeatedly as a funny, informative talk on the economics behind programming languages and open source.","type":"talk","level":"general","score":9.0,"topics":["Languages & compilers"],"recs":10,"years":[2023,2026],"quote":"Very highly recommend this funny, informative talk to understand aspects of creating a programming language other than the theoretical ones.","quote_url":"https://news.ycombinator.com/item?id=38594359","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dK3zRXhrFZY','hn',9.0,'{"vid":"dK3zRXhrFZY","title":"Julia: to Lisp or not to Lisp?","channel":"European Lisp Symposium","summary":"Stefan Karpinski''s European Lisp Symposium 2016 talk asks whether Julia is a Lisp. He covers the features it borrows from Lisp, such as macros and closures, and where it departs, including syntax and its type system, with generated machine code shown.","why":"HN commenters recommend it as a brilliant talk on Julia''s design and how it is or isn''t a Lisp.","type":"talk","level":"intermediate","score":9.0,"topics":["Languages & compilers"],"recs":4,"years":[2016,2022],"quote":"the recent brilliant talk about design of Julia","quote_url":"https://news.ycombinator.com/item?id=11862372","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lKXe3HUG2l4','hn',9.0,'{"vid":"lKXe3HUG2l4","title":"\"The Mess We''re In\" by Joe Armstrong","channel":"Strange Loop Conference","summary":"Joe Armstrong, co-inventor of Erlang, gives a funny and opinionated Strange Loop talk on the tangled state of software: build tools, package managers, entropy and the physical limits of computation. He argues for ideas like naming things by content hash and throwing away your first version.","why":"HN returns to it constantly as a witty, still-accurate diagnosis of why software is bloated and messy, and as a go-to recommendation in any thread on modules, package managers or software quality.","type":"talk","level":"general","score":9.0,"topics":["Software design & craft","Languages & compilers"],"recs":10,"years":[2014,2025],"quote":"one of those talks which were incredibly funny and informative at the same time","quote_url":"https://news.ycombinator.com/item?id=19707649","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pW-SOdj4Kkk','hn',9.0,'{"vid":"pW-SOdj4Kkk","title":"Jonathan Blow - Preventing the Collapse of Civilization (English only)","channel":"bus","summary":"Jonathan Blow''s DevGAMM 2019 talk argues that software knowledge is being lost between generations and that growing layers of abstraction could lead to a decline in technological civilization.","why":"A perennial HN reference for arguments that software is getting worse and that hard-won knowledge is disappearing.","type":"talk","level":"general","score":9.0,"topics":["Software design & craft","Systems & performance"],"recs":11,"years":[2019,2023],"quote":"Very much worth watching in its entirety and thinking about","quote_url":"https://news.ycombinator.com/item?id=27240081","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('yCcWpzY8dIA','hn',9.0,'{"vid":"yCcWpzY8dIA","title":"Conflict Resolution for Eventual Consistency • Martin Kleppmann • GOTO 2016","channel":"GOTO Conferences","summary":"Martin Kleppmann''s GOTO Berlin 2016 talk on how collaborative editors, offline apps, and multi-datacenter databases handle concurrent updates. It covers conflict resolution approaches including operational transformation and CRDTs, with a worked look at text CRDTs.","why":"Treated as the go-to approachable yet deep primer on CRDTs and collaborative editing, recommended repeatedly in threads on Automerge, local-first software and OT versus CRDT.","type":"talk","level":"intermediate","score":9.0,"topics":["Databases & distributed"],"recs":3,"years":[2017,2020],"quote":"Rest of the talk is also highly recommended for anyone interested in an approachable primer on CRDTs.","quote_url":"https://news.ycombinator.com/item?id=19889078","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8Ab3ArE8W3s','hn',8.5,'{"vid":"8Ab3ArE8W3s","title":"\"Stop Writing Dead Programs\" by Jack Rusher (Strange Loop 2022)","channel":"Strange Loop Conference","summary":"Jack Rusher''s Strange Loop 2022 talk argues that most programming languages are still designed around punchcard-era assumptions. He makes the case for live, interactive programming environments, drawing on Lisp, Smalltalk and REPL-driven development.","why":"HN returns to it constantly as the talk on live programming and what modern tooling is missing, though a few found it too much.","type":"talk","level":"intermediate","score":8.5,"topics":["Languages & compilers","Software design & craft"],"recs":9,"years":[2022,2025],"quote":"One of my favorite talks is","quote_url":"https://news.ycombinator.com/item?id=43774877","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YnWhqhNdYyk','hn',8.5,'{"vid":"YnWhqhNdYyk","title":"CppCon 2015: Kate Gregory “Stop Teaching C\"","channel":"CppCon","summary":"Kate Gregory argues at CppCon 2015 that C++ should be taught without starting from C: no char* strings, printf or raw arrays at first, with references before pointers.","why":"HN people cite it constantly in C versus C++ debates as the case for teaching modern C++ idioms rather than C first.","type":"talk","level":"intermediate","score":8.5,"topics":["Systems & performance"],"recs":7,"years":[2016,2025],"quote":"Not only is she a great presenter, but she makes amazing points about what is fundamentally wrong with how C++ is taught in classrooms around the globe.","quote_url":"https://news.ycombinator.com/item?id=10992494","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Z4oYSByyRak','hn',8.5,'{"vid":"Z4oYSByyRak","title":"Zig: A programming language designed for robustness, optimality, and clarity –  Andrew Kelley","channel":"Recurse Center","summary":"Andrew Kelley, creator of Zig, introduces the language at the Recurse Center''s Localhost series in 2018. He covers its goals of robustness, optimality and clarity, C interop, cross-compilation and explicit allocators.","why":"HN repeatedly recommends it as the definitive introduction to Zig straight from its author, and links to it whenever Zig''s design choices come up.","type":"talk","level":"intermediate","score":8.5,"topics":["Systems & performance","Languages & compilers"],"recs":6,"years":[2018,2024],"quote":"here''s a great talk on zig from the recurse center","quote_url":"https://news.ycombinator.com/item?id=19138658","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gCWtkvDQ2ZI','hn',8.5,'{"vid":"gCWtkvDQ2ZI","title":"\"Unison: a new distributed programming language\" by Paul Chiusano","channel":"Strange Loop Conference","summary":"Paul Chiusano''s Strange Loop 2019 talk introduces Unison, an open-source functional language for distributed, elastic systems. It covers content-addressed code identified by hashes of the syntax tree, a codebase manager, and algebraic effects called abilities.","why":"HN treats it as the best introduction to Unison, with commenters finding hash-addressed immutable code mind-blowing.","type":"talk","level":"intermediate","score":8.5,"topics":["Languages & compilers"],"recs":7,"years":[2020,2023],"quote":"this talk might be a better introduction than just skimming at the landing page.","quote_url":"https://news.ycombinator.com/item?id=34335407","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('m3svKOdZijA','hn',8.5,'{"vid":"m3svKOdZijA","title":"Hey Underscore, You''re Doing It Wrong!","channel":"InfoQ","summary":"Brian Lonsdorf explains why Underscore.js falls short as a functional programming library, then introduces currying, composition and point-free style in JavaScript. He argues for data-last argument ordering.","why":"A repeatedly recommended introduction to functional JavaScript that explains currying and why data should come last.","type":"talk","level":"intermediate","score":8.5,"topics":["Languages & compilers","Web"],"recs":9,"years":[2014,2022],"quote":"this video gives a pretty good explanation in ~30 minutes","quote_url":"https://news.ycombinator.com/item?id=12116047","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('r-A78RgMhZU','hn',8.5,'{"vid":"r-A78RgMhZU","title":"A Talk Near the Future of Python (a.k.a., Dave live-codes a WebAssembly Interpreter)","channel":"David Beazley","summary":"David Beazley''s PyCon India closing keynote, in which he live-codes a stack machine and grows it into an interpreter that runs WebAssembly, then uses it to play a Rust-written game. It requires no prior WebAssembly knowledge.","why":"Regarded as a brilliant live-coding talk that teaches WASM and interpreter writing, with several calling it among the best conference talks they have seen.","type":"talk","level":"intermediate","score":8.5,"topics":["Python","Languages & compilers"],"recs":7,"years":[2019,2025],"quote":"it''s quite possible the best conference talk I''ve ever seen.","quote_url":"https://news.ycombinator.com/item?id=25538035","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rI8tNMsozo0','hn',8.5,'{"vid":"rI8tNMsozo0","title":"Rails Conf 2012 Keynote: Simplicity Matters by Rich Hickey","channel":"Confreaks","summary":"Rich Hickey''s keynote at RailsConf 2012, a close sibling of his ''Simple Made Easy'' talk. He distinguishes simple (not intertwined) from easy (familiar), and argues that software complexity comes from complecting things, with Rails-specific examples including large gem collections.","why":"HN recommends it as an alternative or companion to ''Simple Made Easy'', and quotes its ideas about simplicity, complexity and ''hairballs'' in discussions of frameworks, JSON and data design.","type":"talk","level":"intermediate","score":8.5,"topics":["Software design & craft","Languages & compilers"],"recs":8,"years":[2015,2024],"quote":"maybe watch this version instead, since it''s almost the same talk but for a Rails Conference, with a few references","quote_url":"https://news.ycombinator.com/item?id=8857448","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wlR5gYd6um0','hn',8.5,'{"vid":"wlR5gYd6um0","title":"Mastering the Vim Language","channel":"thoughtbot","summary":"Chris Toomey of thoughtbot explains Vim as a language of commands, motions and text objects that combine into precise edits. He shows how to master the built-in pieces and extend them.","why":"Repeatedly called the best video introduction to Vim''s underlying model.","type":"talk","level":"intro","score":8.5,"topics":["Software design & craft"],"recs":5,"years":[2016,2026],"quote":"In video form, the best introduction I have seen is Chris Toomey’s","quote_url":"https://news.ycombinator.com/item?id=13044549","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wo84LFzx5nI','hn',8.5,'{"vid":"wo84LFzx5nI","title":"Casey Muratori – The Big OOPs: Anatomy of a Thirty-five-year Mistake – BSC 2025","channel":"Better Software Conference","summary":"Casey Muratori''s two-hour talk tracing the history of object-oriented programming back to the 1960s and examining how its ideas, and later entity component systems, came about. It is followed by a Q&A.","why":"HN commenters recommend it for its source-based history of OOP, though some dispute its account of Alan Kay.","type":"talk","level":"intermediate","score":8.5,"topics":["Software design & craft","Systems & performance"],"recs":11,"years":[2025,2026],"quote":"which really is hunting back and back for the cosmogenesis of objects, and covers so much terrain.","quote_url":"https://news.ycombinator.com/item?id=46042045","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7EmboKQH8lM','hn',8.0,'{"vid":"7EmboKQH8lM","title":"Clean Code - Uncle Bob / Lesson 1","channel":"UnityCoin","summary":"The first lesson of Uncle Bob (Robert C. Martin)''s \"Coding Better World Together\" series. It makes the case for clean code and for treating software craftsmanship as an ethical and professional responsibility. It runs about 109 minutes.","why":"HN commenters call it better than the Clean Code book, a must-watch for engineers that changes how they read and write code.","type":"lecture","level":"intro","score":8.0,"topics":["Software design & craft"],"recs":6,"years":[2020,2026],"quote":"Clean Code is a great book, but the presentation is so much better","quote_url":"https://news.ycombinator.com/item?id=34312430","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Ip3X9LOh2dk','hn',8.0,'{"vid":"Ip3X9LOh2dk","title":"The determinant | Chapter 6, Essence of linear algebra","channel":"3Blue1Brown","summary":"A 10-minute 3Blue1Brown chapter explaining the determinant as the factor by which a linear transformation scales area or volume. It builds the idea geometrically with animations before any formulas.","why":"HN repeatedly points people to it as the clearest visual intuition for determinants, often saying it finally made the concept click.","type":"explainer","level":"intro","score":8.0,"topics":["Math for ML"],"recs":6,"years":[2019,2024],"quote":"I have warmed up to determinants ever since I saw 3Blue1Brown give a fairly intuitive explanation for them","quote_url":"https://news.ycombinator.com/item?id=40188059","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Mfsnlbd-4xQ','hn',8.0,'{"vid":"Mfsnlbd-4xQ","title":"Functional Composition - Chris Ford","channel":"ClojureTV","summary":"Chris Ford builds up from a single sine wave through layered abstractions to a Bach canon, using Clojure and the Overtone audio environment. The talk shows music theory as a natural fit for functional programming.","why":"HN repeatedly recommends it as a delightful talk that makes music theory click and introduces Clojure and Overtone.","type":"talk","level":"intro","score":8.0,"topics":["Languages & compilers"],"recs":6,"years":[2013,2023],"quote":"Recommend this talk that made Music ''click'' for me.","quote_url":"https://news.ycombinator.com/item?id=17121473","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NdSD07U5uBs','hn',8.0,'{"vid":"NdSD07U5uBs","title":"Alan Kay, 2015: Power of Simplicity","channel":"Kenneth Friedman","summary":"Alan Kay''s 2015 talk on the power of simplicity, arguing that systems become simpler by building on more sophisticated fundamental building blocks and that big research horizons drove invention at Xerox PARC. It ranges across computing, tools and scaling software.","why":"HN repeatedly cites it as a thought-provoking talk on reducing software complexity and on the state of computing research.","type":"talk","level":"general","score":8.0,"topics":["Software design & craft"],"recs":6,"years":[2015,2025],"quote":"Easily over of the most thought provoking presentations I have seen recently.","quote_url":"https://news.ycombinator.com/item?id=11184618","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Up7LcbGZFuo','hn',8.0,'{"vid":"Up7LcbGZFuo","title":"Domain Modeling Made Functional - Scott Wlaschin","channel":"NDC Conferences","summary":"Scott Wlaschin''s NDC talk on using statically typed functional programming, F# in particular, to model a business domain. Types are used to represent the domain precisely and to encode business rules so that illegal states cannot be built, with the compiler acting as an instant unit test.","why":"HN people recommend it as an eye-opening talk whose domain-modeling ideas carry over to other languages and make a strong compiler feel like a coding partner.","type":"talk","level":"intermediate","score":8.0,"topics":["Languages & compilers","Software design & craft"],"recs":6,"years":[2018,2024],"quote":"If anyone is looking for a really eye-opening video take a look at that this.","quote_url":"https://news.ycombinator.com/item?id=21487547","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fHNmRkzxHWs','hn',8.0,'{"vid":"fHNmRkzxHWs","title":"CppCon 2014: Chandler Carruth \"Efficiency with Algorithms, Performance with Data Structures\"","channel":"CppCon","summary":"Chandler Carruth''s CppCon 2014 talk on writing fast C++, explaining why data structure choice and memory layout matter more than clever algorithms. It covers why standard containers like unordered_map perform poorly on modern CPUs.","why":"A perennial recommendation for anyone learning performance optimization, cited whenever hash tables, cache behavior or STL containers come up.","type":"talk","level":"intermediate","score":8.0,"topics":["DSA","Systems & performance"],"recs":7,"years":[2014,2024],"quote":"I''m also a big fan of \"Efficiency with Algorithms, Performance with Data Structures\" by Chandler Carruth at CppCon 2014.","quote_url":"https://news.ycombinator.com/item?id=39579432","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hxM8QmyZXtg','hn',8.0,'{"vid":"hxM8QmyZXtg","title":"[EPILEPSY WARNING] How fast should an unoptimized terminal run?","channel":"Molly Rocket","summary":"Casey Muratori shows how fast a terminal renderer can run, building a simple reference renderer that handles Unicode and colored text far quicker than Windows Terminal. He argues that common excuses for slow terminals do not hold up.","why":"It is the canonical reference for the claim that modern software wastes hardware, and the proof-of-concept behind the Windows Terminal performance debate.","type":"demo","level":"intermediate","score":8.0,"topics":["Systems & performance","Software design & craft"],"recs":6,"years":[2021,2026],"quote":"Casey spent <1 week making RefTerm, a skeleton proto-terminal with the same constraints Microsoft people had","quote_url":"https://news.ycombinator.com/item?id=44745212","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oeYBdghaIjc','hn',8.0,'{"vid":"oeYBdghaIjc","title":"01 - Course Introduction & Relational Model (CMU Databases Systems / Fall 2019)","channel":"CMU Database Group","summary":"The first lecture of Andy Pavlo''s CMU 15-445 Intro to Database Systems (Fall 2019), covering course introduction and the relational model.","why":"Frequently recommended as the best free university course on database internals, praised for depth and Pavlo''s presentation.","type":"lecture","level":"intro","score":8.0,"topics":["Databases & distributed"],"recs":6,"years":[2020,2023],"quote":"Highly recommended both for the depth and how Andy Pavlo presents the topic.","quote_url":"https://news.ycombinator.com/item?id=21962332","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('t_rzYnXEQlE','hn',8.0,'{"vid":"t_rzYnXEQlE","title":"FIXING the ENTIRE SM64 Source Code (INSANE N64 performance)","channel":"Kaze Emanuar","summary":"Kaze Emanuar explains how he rewrote and optimized the Super Mario 64 source code so it runs far faster on real N64 hardware. He covers performance bottlenecks and fixes in detail for his ROM hacks.","why":"HN loves the deep, hands-on look at N64 hardware quirks such as bus contention and the surprisingly large wins from low-hanging optimizations.","type":"explainer","level":"advanced","score":8.0,"topics":["Systems & performance"],"recs":7,"years":[2022,2025],"quote":"amazing video about refactoring Mario 64 to reach 30 FPS and render 6x faster on N64","quote_url":"https://news.ycombinator.com/item?id=38986826","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3Ea3pkTCYx4','hn',7.5,'{"vid":"3Ea3pkTCYx4","title":"Unix and Google","channel":"FOAM","summary":"A short animated simulation comparing how Multics and Unix were developed, showing why Unix''s small composable programs and pipes gave it a efficiency advantage. It frames Unix as a moonshot achievable by a small team.","why":"Cited constantly in threads on microservices, composability and the Unix philosophy as a compact explanation of why small interoperable pieces win.","type":"explainer","level":"general","score":7.5,"topics":["Systems & performance","Software design & craft"],"recs":4,"years":[2016,2023],"quote":"A guy on YT [1] simulates in 7 minutes how the two biggest operating systems were built in the sixties","quote_url":"https://news.ycombinator.com/item?id=27491650","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8xJzHq8ru0M','hn',7.5,'{"vid":"8xJzHq8ru0M","title":"Chris McCord - Keynote: Phoenix LiveView - Interactive Apps without Javascript - ElixirConf EU 2019","channel":"Code Sync","summary":"Chris McCord''s ElixirConf EU 2019 keynote introducing Phoenix LiveView, which builds interactive server-rendered apps without writing JavaScript. It explains how only changed dynamic parts are sent over a websocket.","why":"HN recommends it as the primary source for understanding LiveView''s advantages and its middle ground between multipage apps and SPAs.","type":"talk","level":"intermediate","score":7.5,"topics":["Web","Languages & compilers"],"recs":4,"years":[2019,2024],"quote":"Great talk about it from the developer here","quote_url":"https://news.ycombinator.com/item?id=27311575","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('D6h5dFyyUX0','hn',7.5,'{"vid":"D6h5dFyyUX0","title":"Emacs Rocks! Episode 14: Paredit","channel":"emacsrocks","summary":"A three-minute Emacs Rocks screencast by Magnar Sveen demonstrating paredit, which edits Lisp code structurally as a tree of s-expressions rather than characters.","why":"Repeatedly offered as the quickest, most convincing demo of structured editing and why Lisp programmers love paredit.","type":"tutorial","level":"intro","score":7.5,"topics":["Software design & craft","Languages & compilers"],"recs":8,"years":[2013,2022],"quote":"it''s well worth the 3:40.","quote_url":"https://news.ycombinator.com/item?id=6062364","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Ge3aKEmZcqY','hn',7.5,'{"vid":"Ge3aKEmZcqY","title":"Simple Code, High Performance","channel":"Molly Rocket","summary":"Casey Muratori''s University of Twente guest lecture is a case study in how straightforward code can cut thousands of lines and tens of seconds of runtime down to a few dozen lines running in under a second. It uses concrete examples to show why software is often an order of magnitude slower than it should be.","why":"HN people recommend it to anyone wanting a practical sense of what CPUs can really do and why abstraction layers cost so much performance.","type":"lecture","level":"intermediate","score":7.5,"topics":["Systems & performance"],"recs":6,"years":[2021,2025],"quote":"I highly recommend watching it.","quote_url":"https://news.ycombinator.com/item?id=30586520","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Gv2I7qTux7g','hn',7.5,'{"vid":"Gv2I7qTux7g","title":"The Road to Zig 1.0 - Andrew Kelley","channel":"ChariotSolutions","summary":"Zig creator Andrew Kelley justifies why Zig exists and tours its distinctive features, including C interoperability and comptime, along with what people had built and what 1.0 would bring. It was given at Philly ETE 2019.","why":"HN treats it as the standard introduction to Zig by its creator, with some calling it among the best talks they have seen.","type":"talk","level":"intermediate","score":7.5,"topics":["Systems & performance","Languages & compilers"],"recs":5,"years":[2019,2025],"quote":"Andrew Kelley''s intro[0] is probably the best talk I''ve ever seen","quote_url":"https://news.ycombinator.com/item?id=36577748","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZeecOKBus3Q','hn',7.5,'{"vid":"ZeecOKBus3Q","title":"Why Would AI Want to do Bad Things? Instrumental Convergence","channel":"Robert Miles AI Safety ","summary":"Robert Miles explains instrumental convergence: why an AGI with almost any goal would tend to pursue sub-goals like self-preservation and resource acquisition. It builds on Omohundro''s basic AI drives and his orthogonality thesis video.","why":"HN commenters repeatedly recommend it as the clearest introduction to why smart AI might behave badly by default.","type":"explainer","level":"intro","score":7.5,"topics":["AI & ML"],"recs":6,"years":[2019,2023],"quote":"Robert Miles'' videos are among the best presented arguments about specific points in this list","quote_url":"https://news.ycombinator.com/item?id=36124905","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cKPlPJyQrt4','hn',7.5,'{"vid":"cKPlPJyQrt4","title":"James Powell: So you want to be a Python expert? | PyData Seattle 2017","channel":"PyData","summary":"James Powell''s nearly two-hour PyData talk builds up Python''s data model, decorators, generators and context managers, coding live in Vim. It aims to take intermediate programmers toward real Python expertise.","why":"HN calls it one of the best technical talks and the clearest explanation of decorators, generators and context managers.","type":"talk","level":"intermediate","score":7.5,"topics":["Python","Languages & compilers","Software design & craft"],"recs":6,"years":[2020,2026],"quote":"It''s legitimately the best technical talk I think I''ve seen and I can''t recommend it highly enough.","quote_url":"https://news.ycombinator.com/item?id=23088282","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hx7BXih7zx8','hn',7.5,'{"vid":"hx7BXih7zx8","title":"Andrej Karpathy - AI for Full-Self Driving at Tesla","channel":"Matroid","summary":"Andrej Karpathy, then Tesla''s head of AI, presents at ScaledML 2020 on how Tesla builds full self-driving using vision-based neural nets and fleet data collection. He covers training custom detectors and neural nets gradually replacing traditional code.","why":"HN repeatedly points to it as the best public technical overview of Tesla''s FSD approach, used both to defend and to critique Tesla''s progress.","type":"talk","level":"intermediate","score":7.5,"topics":["Karpathy","AI & ML"],"recs":4,"years":[2020,2022],"quote":"I highly recommend watching head of AI at Tesla Andrej Karpathy''s talk on their self driving architecture.","quote_url":"https://news.ycombinator.com/item?id=25705486","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rHIkrotSwcc','hn',7.5,'{"vid":"rHIkrotSwcc","title":"CppCon 2019: Chandler Carruth “There Are No Zero-cost Abstractions”","channel":"CppCon","summary":"Chandler Carruth argues in a CppCon 2019 talk that C++ has no truly zero-cost abstractions. Using examples like unique_ptr, ABI constraints and compile-time costs, he shows that abstractions cost runtime, compile time or human effort.","why":"HN commenters cite it whenever zero-cost abstraction claims come up, especially for why unique_ptr is not free on some ABIs.","type":"talk","level":"advanced","score":7.5,"topics":["Systems & performance"],"recs":7,"years":[2020,2026],"quote":"Chandler presents his point clearly and goes deep enough into the subject.","quote_url":"https://news.ycombinator.com/item?id=30644518","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sPhpelUfu8Q','hn',7.5,'{"vid":"sPhpelUfu8Q","title":"CppCon 2017: Juan Pedro Bolivar Puente “Postmodern immutable data structures”","channel":"CppCon","summary":"Juan Pedro Bolivar Puente explains immutable and persistent data structures in C++ and how they support value semantics. He presents the Immer library, rrb-trees, and a prototype text editor that opens a huge file instantly.","why":"HN people point to it for rrb-trees, text editor data structures and bringing Clojure-style persistent structures to C++.","type":"talk","level":"advanced","score":7.5,"topics":["DSA","Systems & performance","Languages & compilers"],"recs":5,"years":[2017,2025],"quote":"Immer [0][1] seems like a really serious attempt at bringing high-quality persistent data structures to C++.","quote_url":"https://news.ycombinator.com/item?id=28405730","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xt1KNDmOYqA','hn',7.5,'{"vid":"xt1KNDmOYqA","title":"Casey Muratori | Smart-Pointers, RAII, ZII? Becoming an N+2 programmer","channel":"xDahl","summary":"Casey Muratori argues against smart pointers and RAII, advocating grouped-element thinking, zero-is-initialization and stubs as better ways to structure memory and handle errors.","why":"HN commenters in memory management and language design threads cite it as the best explanation of group lifetimes versus per-object ownership.","type":"talk","level":"advanced","score":7.5,"topics":["Systems & performance","Software design & craft"],"recs":6,"years":[2024,2026],"quote":"The best video on this might be from Casey Muratori","quote_url":"https://news.ycombinator.com/item?id=46457333","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zjkBMFhNj_g','hn',7.5,'{"vid":"zjkBMFhNj_g","title":"[1hr Talk] Intro to Large Language Models","channel":"Andrej Karpathy","summary":"Andrej Karpathy gives a one-hour general-audience introduction to large language models, covering what they are, how they are trained, comparisons to operating systems, and security challenges such as jailbreaks.","why":"HN recommends it as the dense, approachable starting point for understanding LLMs and often cites it for specific claims about scaling and training.","type":"talk","level":"intro","score":7.5,"topics":["Karpathy","AI & ML","LLMs"],"recs":9,"years":[2023,2026],"quote":"Start with his short intro to LLMs, only 1 hour long but is dense with valuable stuff","quote_url":"https://news.ycombinator.com/item?id=40687717","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7jiPeIFXb6U','hn',7.0,'{"vid":"7jiPeIFXb6U","title":"I don''t like notebooks.- Joel Grus (Allen Institute for Artificial Intelligence)","channel":"O''Reilly","summary":"Joel Grus''s JupyterCon talk explaining why he dislikes Jupyter notebooks. He covers hidden state, trouble with reproducibility and testing, and how notebooks frustrate teaching. He shows his preferred workflow and what Jupyter could change.","why":"It is the go-to funny, irreverent critique of notebooks, linked whenever HN debates notebooks versus testable code.","type":"talk","level":"intermediate","score":7.0,"topics":["Python","AI & ML","Languages & compilers"],"recs":6,"years":[2018,2025],"quote":"The parent article links this great talk that goes into more detail than the parent post and is much easier to understand","quote_url":"https://news.ycombinator.com/item?id=40675952","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('A8eCGOqgvH4','hn',7.0,'{"vid":"A8eCGOqgvH4","title":"C++ and Beyond 2012: Herb Sutter - atomic Weapons 1 of 2","channel":"alexsmail","summary":"Herb Sutter''s deep C++ and Beyond 2012 talk on atomics and the C++ memory model, covering why programmers chasing top performance need to understand hardware ordering. This is part one of two.","why":"HN treats it as the classic go-to for learning atomics and memory ordering, recommended over books.","type":"talk","level":"advanced","score":7.0,"topics":["Systems & performance"],"recs":4,"years":[2020,2024],"quote":"which are extremely good","quote_url":"https://news.ycombinator.com/item?id=41241187","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('FJJTYQYB1JQ','hn',7.0,'{"vid":"FJJTYQYB1JQ","title":"Sorting Algorithms: Speed Is Found In The Minds of People - Andrei Alexandrescu - CppCon 2019","channel":"CppCon","summary":"Andrei Alexandrescu''s CppCon 2019 talk revisits sorting, showing how branchless tricks, hybrid strategies and a cost metric can speed up std::sort-style algorithms on modern hardware.","why":"HN recommends it as an entertaining talk that starts simple and goes deep on practical performance optimization.","type":"talk","level":"advanced","score":7.0,"topics":["DSA","Systems & performance"],"recs":7,"years":[2019,2024],"quote":"At first he is just showing simple stuff, but stay with it, he goes deep.","quote_url":"https://news.ycombinator.com/item?id=38810283","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('G_eYTctGZw8','hn',7.0,'{"vid":"G_eYTctGZw8","title":"\"Production Prolog\" by Michael Hendricks","channel":"Strange Loop Conference","summary":"Michael Hendricks of PriceCharting shares tricks and pain points from running Prolog in production for 18 months at Strange Loop. It argues Prolog is a productive modern language beyond logic puzzles, and includes a demo of changing code mid-execution.","why":"It is the go-to answer to whether Prolog is used for real-world work, praised as a survey of its uses, advantages and drawbacks.","type":"talk","level":"intermediate","score":7.0,"topics":["Languages & compilers"],"recs":6,"years":[2015,2023],"quote":"gives an excellent high-level survey of the uses, advantages, and drawbacks of Prolog","quote_url":"https://news.ycombinator.com/item?id=9248500","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JEpsBg0AO6o','hn',7.0,'{"vid":"JEpsBg0AO6o","title":"Paxos lecture (Raft user study)","channel":"Diego Ongaro","summary":"John Ousterhout''s slides-and-voiceover lecture on Paxos, made for the Raft user study comparing how students learn Raft and Paxos. It is a full introduction to the Paxos consensus algorithm.","why":"Recommended as a clear, lucid way to learn Paxos and Multi-Paxos, ideally alongside the companion Raft video.","type":"lecture","level":"intermediate","score":7.0,"topics":["Databases & distributed"],"recs":6,"years":[2013,2024],"quote":"The 2 videos do an excellent job of explaining both the Paxos and Raft algorithms and the key differences between them.","quote_url":"https://news.ycombinator.com/item?id=8529187","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('N1CBDTgGtOU','hn',7.0,'{"vid":"N1CBDTgGtOU","title":"VisiData Lightning Demo at PyCascades 2018","channel":"Saul Pwanson","summary":"A five-minute lightning demo of VisiData, a terminal tool for exploring and manipulating data. It uses two months of NYC 311 complaint data to drill down, plot points on a virtual map and save selected rows.","why":"HN recommends it as the fastest way to understand what VisiData can do, since seeing it work is clearer than reading about it.","type":"demo","level":"intro","score":7.0,"topics":["Python","AI & ML","Software design & craft"],"recs":6,"years":[2018,2025],"quote":"visdata is pretty mind-blowing...at least, that''s how i felt when i saw the demo the first time","quote_url":"https://news.ycombinator.com/item?id=28307285","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PFDu9oVAE-g','hn',7.0,'{"vid":"PFDu9oVAE-g","title":"Eigenvectors and eigenvalues | Chapter 14, Essence of linear algebra","channel":"3Blue1Brown","summary":"3Blue1Brown''s chapter on eigenvectors and eigenvalues in the Essence of Linear Algebra series. It builds a visual intuition for what they mean, why an eigenbasis is useful, and ends with a puzzle.","why":"HN repeatedly names it the best, most intuitive explanation of eigenvalues, and a gateway to the whole linear algebra series.","type":"explainer","level":"intro","score":7.0,"topics":["Math for ML"],"recs":6,"years":[2016,2025],"quote":"By far the best explanation of eigenvalues is found on 3blue1brown","quote_url":"https://news.ycombinator.com/item?id=33527453","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('US8QG9I1XW0','hn',7.0,'{"vid":"US8QG9I1XW0","title":"Functional architecture - The pits of success - Mark Seemann","channel":"NDC Conferences","summary":"Mark Seemann argues that functional programming naturally yields many of the best practices object-oriented developers learn painfully. He shows how functional architecture leads to a pit of success, with a pure core and impure shell.","why":"Recommended as a practical demonstration of how functional thinking improves design without going off the deep end.","type":"talk","level":"intermediate","score":7.0,"topics":["Software design & craft","Languages & compilers"],"recs":5,"years":[2018,2025],"quote":"Here is a great talk demonstrating that by following a simple functional approach, your code can naturally fall into a “pit of success","quote_url":"https://news.ycombinator.com/item?id=24918556","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bSkpMdDe4g4','hn',7.0,'{"vid":"bSkpMdDe4g4","title":"CppCon 2017: Matt Godbolt “What Has My Compiler Done for Me Lately? Unbolting the Compiler''s Lid”","channel":"CppCon","summary":"Matt Godbolt''s CppCon 2017 talk shows what modern compilers do with your C++ code, using Compiler Explorer to inspect generated assembly. It covers surprising optimizations and how the tool works.","why":"HN recommends it as an entertaining, mind-blowing look at compiler cleverness from a great speaker.","type":"talk","level":"intermediate","score":7.0,"topics":["Languages & compilers","Systems & performance"],"recs":7,"years":[2018,2022],"quote":"Both are great presentations going into details on some of the crazy optimizations compilers will do.","quote_url":"https://news.ycombinator.com/item?id=20915513","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cCOL7MC4Pl0','hn',7.0,'{"vid":"cCOL7MC4Pl0","title":"Jake Archibald on the web browser event loop, setTimeout, micro tasks, requestAnimationFrame, ...","channel":"JSConf","summary":"Jake Archibald''s JSConf.Asia 2018 talk \"In the Loop\" explains the browser event loop, covering tasks, microtasks, requestAnimationFrame, and how rendering interleaves with JavaScript. It uses visual walkthroughs to show why code runs in surprising orders and why setTimeout fixes are unreliable.","why":"HN treats it as the best primer on the event loop, praising its entertaining, easy-to-grasp visual explanations.","type":"talk","level":"intermediate","score":7.0,"topics":["Web","Systems & performance"],"recs":7,"years":[2018,2023],"quote":"actually making it both entertaining and easily grokable!","quote_url":"https://news.ycombinator.com/item?id=18217867","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gcUWTa16Jc0','hn',7.0,'{"vid":"gcUWTa16Jc0","title":"Co-dfns Live Stream: Compiler Design and Architecture","channel":"Aaron Hsu (arcfide)","summary":"A two-hour live stream in which Aaron Hsu explains the architecture, design history and aesthetic of Co-dfns, his parallel APL compiler. He walks through the code and the reasoning behind its dense style.","why":"HN readers say it changed their view of APL and array languages, with a clear walkthrough of how a compiler can be written in this style.","type":"talk","level":"advanced","score":7.0,"topics":["Languages & compilers"],"recs":3,"years":[2018,2025],"quote":"Nothing has ever convinced me about the potential for array languages in practice quite like watching Aaron Hsu","quote_url":"https://news.ycombinator.com/item?id=38982944","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hEUO6pjwFOo','hn',7.0,'{"vid":"hEUO6pjwFOo","title":"Intelligence and Stupidity: The Orthogonality Thesis","channel":"Robert Miles AI Safety ","summary":"Robert Miles explains the orthogonality thesis: how an agent can be highly intelligent while pursuing goals that seem stupid or alien to humans. He separates intelligence from goals and touches on the stamp-collector example.","why":"HN people use it as the standard short explanation for why AI can understand human ethics without sharing them, and often recommend the whole channel.","type":"explainer","level":"intro","score":7.0,"topics":["AI & ML"],"recs":6,"years":[2022,2026],"quote":"this video to me states the problem in a nutshell (that whole channel is gold)","quote_url":"https://news.ycombinator.com/item?id=35318638","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hgN8pCMLI2U','hn',7.0,'{"vid":"hgN8pCMLI2U","title":"Bryan Cantrill on Jails and Solaris Zones","channel":"PapersWeLove","summary":"Bryan Cantrill''s Papers We Love talk on FreeBSD Jails and Solaris Zones, tracing how OS-level virtualization grew out of chroot and the limits of the traditional UNIX security model.","why":"Recommended repeatedly as the best account of container history and how Zones built on and went beyond Jails.","type":"talk","level":"intermediate","score":7.0,"topics":["Systems & performance"],"recs":6,"years":[2016,2025],"quote":"I highly recommend this talk, talking about Jails and Zones.","quote_url":"https://news.ycombinator.com/item?id=41055476","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lw6TaiXzHAE','hn',7.0,'{"vid":"lw6TaiXzHAE","title":"OOPSLA Conference: Growing a Language","channel":"Computer History Museum","summary":"Guy Steele''s classic 1998 OOPSLA keynote on how a programming language must grow with its user community. He delivers it in a playful style, starting with only monosyllabic words and defining new terms as he goes.","why":"Treated as a must-watch for language designers, and cited whenever extensibility and language size are debated.","type":"talk","level":"intermediate","score":7.0,"topics":["Languages & compilers"],"recs":6,"years":[2020,2026],"quote":"In case anyone hasn''t seen this most excellent talk on this topic, I highly recommend","quote_url":"https://news.ycombinator.com/item?id=30068289","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('p6K4iIMlouI','hn',7.0,'{"vid":"p6K4iIMlouI","title":"7 Habits For Effective Text Editing 2.0","channel":"GoogleTalksArchive","summary":"Vim creator Bram Moolenaar''s 2007 Google Tech Talk on habits for efficient text editing. He explains how to spot repetition and inefficiency, then use editor features to fix it.","why":"HN recommends it as a lasting philosophy for improving your editing process incrementally, and it was widely remembered after Moolenaar''s death.","type":"talk","level":"intermediate","score":7.0,"topics":["Software design & craft"],"recs":5,"years":[2013,2023],"quote":"There is a wonderful presentation called ''7 Habits For Effective Text Editing 2.0'' [1] explaining this philosophy.","quote_url":"https://news.ycombinator.com/item?id=8079942","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('qI_g07C_Q5I','hn',7.0,'{"vid":"qI_g07C_Q5I","title":"Introduction to NoSQL • Martin Fowler • GOTO 2012","channel":"GOTO Conferences","summary":"Martin Fowler''s GOTO 2012 introduction to NoSQL databases: where they came from, their data models, how consistency thinking differs, and when to use them. He argues they won''t make relational databases obsolete and introduces polyglot persistence.","why":"HN repeatedly recommends it as a balanced, beginner-friendly overview of SQL versus NoSQL, and some teachers assign it to students.","type":"talk","level":"intro","score":7.0,"topics":["Databases & distributed","Software design & craft"],"recs":6,"years":[2015,2021],"quote":"one of the rare videos I''ve required students in my database classes to watch.","quote_url":"https://news.ycombinator.com/item?id=12643863","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rFejpH_tAHM','hn',7.0,'{"vid":"rFejpH_tAHM","title":"dotGo 2015 - Rob Pike - Simplicity is Complicated","channel":"dotconferences","summary":"Rob Pike''s dotGo 2015 talk argues that Go only seems simple, and that its simplicity hides real complexity that is part of the design. He explains the thinking behind Go''s restraint in features.","why":"HN returns to it to explain why Go deliberately resists syntactic sugar and new features.","type":"talk","level":"intermediate","score":7.0,"topics":["Systems & performance","Languages & compilers"],"recs":7,"years":[2016,2023],"quote":"It''s an active choice of the language to not allow many syntactic sugars that make the code have a much higher learning curve.","quote_url":"https://news.ycombinator.com/item?id=12122666","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('tISy7EJQPzI','hn',7.0,'{"vid":"tISy7EJQPzI","title":"CppCon 2017: Titus Winters “C++ as a \"Live at Head\" Language”","channel":"CppCon","summary":"Titus Winters'' CppCon 2017 talk argues for C++ and Google''s Abseil to be maintained as a live at head language, relying on testing and automated tooling rather than never changing or promising no compatibility. It covers Hyrum''s law and the limits of semantic versioning.","why":"Recommended whenever versioning, semver, monorepos and backward compatibility are debated, for its nuanced treatment of dependencies.","type":"talk","level":"advanced","score":7.0,"topics":["Software design & craft","Systems & performance"],"recs":7,"years":[2017,2022],"quote":"a much more nuanced look at dependencies & versioning","quote_url":"https://news.ycombinator.com/item?id=24926736","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vq2nnJ4g6N0','hn',7.0,'{"vid":"vq2nnJ4g6N0","title":"Tensorflow and deep learning - without a PhD by Martin Görner","channel":"Devoxx","summary":"Martin Gorner''s Devoxx talk introduces deep learning with TensorFlow, walking through neural networks for MNIST, how to choose an architecture and how to diagnose networks that fail to train.","why":"Repeatedly called an excellent, practical introduction that covers a lot in two hours and explains issues academic textbooks skip.","type":"tutorial","level":"intro","score":7.0,"topics":["AI & ML"],"recs":6,"years":[2017,2020],"quote":"Tensorflow and deep learning - without a PhD\" is really good, and covers a lot of material in a single 2hr talk.","quote_url":"https://news.ycombinator.com/item?id=16494014","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('1-dUkyn_fZA','hn',6.5,'{"vid":"1-dUkyn_fZA","title":"Emacs + org-mode + python in reproducible research; SciPy 2013 Presentation","channel":"Enthought","summary":"John Kitchin shows how Emacs org-mode with Python lets researchers combine narrative, math, figures and executable code in one document. It exports to LaTeX, HTML and PDF, and he used it for papers and e-books.","why":"Repeatedly recommended as the canonical demo of org-mode for literate programming and reproducible research.","type":"talk","level":"intermediate","score":6.5,"topics":["Python","Software design & craft","AI & ML"],"recs":5,"years":[2014,2018],"quote":"on Emacs + org-mode + python in reproducible research is worth a watch","quote_url":"https://news.ycombinator.com/item?id=9767343","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3VQ382QG-y4','hn',6.5,'{"vid":"3VQ382QG-y4","title":"Lambda Calculus - Fundamentals of Lambda Calculus & Functional Programming in JavaScript","channel":"Fullstack Academy","summary":"Gabriel Lebec''s Fullstack Academy talk introduces lambda calculus syntax, the history of mathematical logic, and the essence of functional programming using JavaScript. It also covers combinators, currying and Church encodings.","why":"Repeatedly recommended as one of the most approachable introductions to lambda calculus and combinators.","type":"lecture","level":"intro","score":6.5,"topics":["Math & theory","Languages & compilers"],"recs":5,"years":[2019,2024],"quote":"they are the most approachable videos on the topic I have ever seen.","quote_url":"https://news.ycombinator.com/item?id=41027895","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('6mTbuzafcII','hn',6.5,'{"vid":"6mTbuzafcII","title":"\"Transducers\" by Rich Hickey","channel":"Strange Loop Conference","summary":"Rich Hickey introduces transducers in Clojure, a way to make map, filter and similar algorithms composable independent of the data source. This avoids duplicated implementations and intermediate collections across sequences, channels and streams.","why":"HN treats it as the original and definitive explanation of transducers, recommended whenever the concept comes up.","type":"talk","level":"intermediate","score":6.5,"topics":["Languages & compilers","Software design & craft"],"recs":6,"years":[2014,2025],"quote":"If you want a really good intro, watch Rich Hickey''s talk about transducers","quote_url":"https://news.ycombinator.com/item?id=45855786","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7erJ1DV_Tlo','hn',6.5,'{"vid":"7erJ1DV_Tlo","title":"Hewitt, Meijer and Szyperski: The Actor Model (everything you wanted to know...)","channel":"jasonofthel33t","summary":"A standing whiteboard conversation at Lang.NEXT 2012 among Carl Hewitt, Erik Meijer and Clemens Szyperski about the actor model. Hewitt, who originated the model, explains its foundations.","why":"HN recommends it as the best video introduction to the actor model, straight from its inventor, and revisited it after Hewitt''s death.","type":"interview","level":"intermediate","score":6.5,"topics":["Databases & distributed","Languages & compilers"],"recs":5,"years":[2015,2025],"quote":"It''s truly a masterclass.","quote_url":"https://news.ycombinator.com/item?id=34273970","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8fi7uSYlOdc','hn',6.5,'{"vid":"8fi7uSYlOdc","title":"Containers From Scratch • Liz Rice • GOTO 2018","channel":"GOTO Conferences","summary":"Liz Rice live-codes a minimal container runtime in a few lines of Go at GOTO Amsterdam 2018. She explains namespaces, control groups and what a host knows about its containers.","why":"HN considers it one of the best talks for understanding how containers work from the ground up.","type":"talk","level":"intermediate","score":6.5,"topics":["Systems & performance"],"recs":6,"years":[2018,2025],"quote":"Probably one of the most enlightening presentations I''ve seen in recent years, full-stop.","quote_url":"https://news.ycombinator.com/item?id=31250305","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9Q6sLbz37gk','hn',6.5,'{"vid":"9Q6sLbz37gk","title":"I Like Notebooks","channel":"Jeremy Howard","summary":"Jeremy Howard defends Jupyter notebooks as a serious development environment, especially when paired with nbdev. He responds directly to Joel Grus''s talk about why he dislikes notebooks, and contrasts REPL-style and notebook-style work.","why":"Whenever notebooks get criticized, HN commenters point to it as the standard rebuttal from a prominent practitioner.","type":"talk","level":"intermediate","score":6.5,"topics":["Python","Software design & craft","AI & ML"],"recs":4,"years":[2020,2025],"quote":"I strongly recommend Jeremy Howard''s (founder of fast.ai) recent talk","quote_url":"https://news.ycombinator.com/item?id=25524388","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DJtef410XaM','hn',6.5,'{"vid":"DJtef410XaM","title":"The Clean Architecture in Python","channel":"Next Day Video","summary":"Brandon Rhodes'' PyOhio 2014 talk on applying the Clean Architecture in Python. He shows how this high-level design pattern fits Python''s features and addresses maintainability problems in large applications.","why":"HN points to it as a practical way to separate business logic from I/O, which reduces mocking and underlies the functional core, imperative shell idea.","type":"talk","level":"intermediate","score":6.5,"topics":["Python","Software design & craft","Languages & compilers"],"recs":5,"years":[2017,2021],"quote":"I''d really recommend this video.","quote_url":"https://news.ycombinator.com/item?id=26567499","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DleXA5ADG78','hn',6.5,'{"vid":"DleXA5ADG78","title":"Brains, Sex, and Machine Learning","channel":"Google TechTalks","summary":"Geoffrey Hinton''s Google Tech Talk linking machine learning to biology, explaining dropout as a form of model averaging and why sexual reproduction and stochastic spiking neurons may prevent overfitting.","why":"Recommended as a simple, elegant explanation of dropout and its connection to how the brain works.","type":"talk","level":"intermediate","score":6.5,"topics":["AI & ML"],"recs":7,"years":[2012,2017],"quote":"If you want a great overview of the dropout technique, watch this tech talk by Hinton","quote_url":"https://news.ycombinator.com/item?id=5770495","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JWD1Fpdd4Pc','hn',6.5,'{"vid":"JWD1Fpdd4Pc","title":"Evil Mode: Or, How I Learned to Stop Worrying and Love Emacs","channel":"thoughtbot","summary":"Aaron Bieber, a longtime Vim user, describes his experience trying Emacs with evil mode. He covers what he found, what he missed from Vim, and what Vim could borrow from Emacs.","why":"HN recommends it to Vim users considering Emacs, and several say it persuaded them or their coworkers to switch.","type":"talk","level":"intermediate","score":6.5,"topics":["Software design & craft"],"recs":6,"years":[2015,2020],"quote":"Aaron gave a great talk about his switch here","quote_url":"https://news.ycombinator.com/item?id=12104353","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KXuZi9aeGTw','hn',6.5,'{"vid":"KXuZi9aeGTw","title":"User-level threads....... with threads. - Paul Turner - Google","channel":"Linux Plumbers Conference","summary":"Paul Turner of Google presents kernel interfaces for user-level scheduling of real threads, aiming at a uniform synchronous programming model across C++, Java, Go and Python. It introduces the switchto-style system calls behind Google''s fibers.","why":"HN cites it as the key explanation of cooperative, user-scheduled kernel threads and the prior art behind later async and coroutine debates.","type":"talk","level":"advanced","score":6.5,"topics":["Systems & performance"],"recs":6,"years":[2013,2024],"quote":"Paul Turner explained this really well at this year''s Linux Plumbers Conference. The whole talk is fantastic","quote_url":"https://news.ycombinator.com/item?id=6982790","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KZjFVdU8VLI','hn',6.5,'{"vid":"KZjFVdU8VLI","title":"Interactive programming Flappy Bird in ClojureScript","channel":"Bruce Hauman","summary":"Bruce Hauman live-codes Flappy Bird in ClojureScript in about six minutes, using figwheel to hot-reload changes into the running game. The demo shows game behavior being changed interactively without restarting.","why":"It is the canonical demo HN people cite for live interactive development and hot reloading, as proof the workflow is real and not smoke and mirrors.","type":"demo","level":"intermediate","score":6.5,"topics":["Languages & compilers"],"recs":6,"years":[2015,2020],"quote":"I still marvel at Bruce Hauman''s demo","quote_url":"https://news.ycombinator.com/item?id=12170419","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('MZvmYaFkNJI','hn',6.5,'{"vid":"MZvmYaFkNJI","title":"Build a real-time Twitter clone in 15 minutes with LiveView and Phoenix 1.5","channel":"Chris McCord","summary":"Phoenix creator Chris McCord builds a real-time Twitter-style app live with Phoenix LiveView 1.5 in about 15 minutes. It shows interactive, real-time updates without writing JavaScript.","why":"HN points people to it as the demo that shows why LiveView and Elixir are worth a look.","type":"tutorial","level":"intermediate","score":6.5,"topics":["Languages & compilers","Web"],"recs":7,"years":[2020,2025],"quote":"the demo completely blew my mind","quote_url":"https://news.ycombinator.com/item?id=25540421","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Nq2HkAYbG5o','hn',6.5,'{"vid":"Nq2HkAYbG5o","title":"2016 - On The Shoulders Of Giants - Damian Conway","channel":"The Perl and Raku Conference - Greenville, SC 2026","summary":"Damian Conway''s hour-long keynote at the Perl conference, On the Shoulders of Giants, showing off Perl 6 (Raku) features with history, algorithms and a quantum math operator built with grammars. It is delivered with comic flair.","why":"HN recommends it as an entertaining, technically masterful showcase of what Perl 6 can do.","type":"talk","level":"intermediate","score":6.5,"topics":["Languages & compilers"],"recs":4,"years":[2016,2021],"quote":"the whole thing is like watching a great movie","quote_url":"https://news.ycombinator.com/item?id=27827377","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PorfLSr3DDI','hn',6.5,'{"vid":"PorfLSr3DDI","title":"CppCon 2015: Greg Law \" Give me 15 minutes & I''ll change your view of GDB\"","channel":"CppCon","summary":"Greg Law''s 15-minute CppCon 2015 lightning talk shows what GDB can do beyond basic use, including its text user interface and reverse debugging.","why":"Recommended as a fast, brilliant introduction to GDB''s TUI mode and lesser-known features, useful for anyone who has only used IDE debuggers.","type":"talk","level":"intro","score":6.5,"topics":["Software design & craft","Systems & performance"],"recs":6,"years":[2018,2023],"quote":"this brilliant short talk (15min) about gdb''s TUI.","quote_url":"https://news.ycombinator.com/item?id=16277234","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('aSEQfqNYNAc','hn',6.5,'{"vid":"aSEQfqNYNAc","title":"Rich Hickey rants about HttpServletRequest in 1080p: Death By Specificity from Clojure Made Simple","channel":"Fred Overflow","summary":"A five-minute excerpt of Rich Hickey''s Clojure Made Simple talk, with new slides, ranting about HttpServletRequest and specificity. He argues for using generic maps instead of many specific classes and getters.","why":"Cited as the classic rant on maps versus objects in discussions of data modeling and OOP.","type":"talk","level":"intermediate","score":6.5,"topics":["Software design & craft","Languages & compilers"],"recs":5,"years":[2020,2026],"quote":"A classic rant by Rich Hickey","quote_url":"https://news.ycombinator.com/item?id=38360086","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('i6Fr65PFqfk','hn',6.5,'{"vid":"i6Fr65PFqfk","title":"DjangoCon 2008 Keynote: Cal Henderson","channel":"Google for Developers","summary":"Cal Henderson''s DjangoCon 2008 keynote, \"Why I Hate Django\", is a funny critique of Django from a Flickr architect. It touches on scaling topics such as database replication.","why":"Recommended as a brilliant, hilarious talk, though not the most educational.","type":"talk","level":"intermediate","score":6.5,"topics":["Python","Web","Languages & compilers"],"recs":6,"years":[2009,2026],"quote":"a brilliant (and hilarious) talk","quote_url":"https://news.ycombinator.com/item?id=6661706","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kTiP0zKF9bc','hn',6.5,'{"vid":"kTiP0zKF9bc","title":"Robocalypse Now: Using Deep Learning to Combat Cheating in Counter-Strike: Global Offensive","channel":"GDC Festival of Gaming","summary":"Valve''s John McDonald presents at GDC 2018 on how Valve uses deep learning (VACnet) to detect cheaters in Counter-Strike: Global Offensive. He covers training on human-reviewed replays and how model output is confirmed by manual review.","why":"The go-to link in any anti-cheat thread for a concrete, well-delivered account of machine-learning cheat detection in production.","type":"talk","level":"intermediate","score":6.5,"topics":["AI & ML"],"recs":5,"years":[2021,2025],"quote":"The presenter delivered the problem and solution approach so well I''d still like to work on something like this some time.","quote_url":"https://news.ycombinator.com/item?id=44320225","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kc9HwsxE1OY','hn',6.5,'{"vid":"kc9HwsxE1OY","title":"The Unreasonable Effectiveness of Multiple Dispatch | Stefan Karpinski | JuliaCon 2019","channel":"The Julia Programming Language","summary":"Julia co-creator Stefan Karpinski explains why multiple dispatch makes Julia code and types reusable across packages with so little friction. He covers sharing basic types and sharing generic algorithms.","why":"HN commenters recommend it as the definitive explanation, from a language designer, of why multiple dispatch makes Julia''s composability work.","type":"talk","level":"intermediate","score":6.5,"topics":["Languages & compilers","Software design & craft"],"recs":9,"years":[2019,2025],"quote":"a talk by a core developer at JuliaCon 2019 titled ''The unreasonable effectiveness of multiple dispatch''","quote_url":"https://news.ycombinator.com/item?id=24847421","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lkIicfzPBys','hn',6.5,'{"vid":"lkIicfzPBys","title":"Stevey''s Tech Talk E39 -- A guided tour of Emacs","channel":"Steve Yegge","summary":"Steve Yegge records himself working in Emacs and shows off about a dozen features in a roughly 45-minute screen capture. It is an informal, enthusiastic tour rather than a structured tutorial.","why":"HN people recommend it as an excellent, convincing overview of Emacs for newcomers and skeptics, shown by someone who clearly loves it.","type":"demo","level":"intro","score":6.5,"topics":["Software design & craft"],"recs":5,"years":[2022,2024],"quote":"Two videos by Steve Yegge should be enough to convince the most dyed-in-the-wool anti-Emacser to consider re-evaluating their position.","quote_url":"https://news.ycombinator.com/item?id=35228674","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oYk8CKH7OhE','hn',6.5,'{"vid":"oYk8CKH7OhE","title":"Evan Czaplicki - Let''s be mainstream! User focused design in Elm - Curry On","channel":"Curry On!","summary":"Evan Czaplicki, creator of Elm, talks at Curry On 2015 about user-focused language design. He explains the principles behind Elm and how to make a functional, typed language as approachable as JavaScript.","why":"Recommended as the clearest explanation of Elm''s design thinking and of making functional languages mainstream, plus a popular monad explanation clip.","type":"talk","level":"intermediate","score":6.5,"topics":["Languages & compilers"],"recs":7,"years":[2015,2023],"quote":"He makes a strong case for Elm not as a language-to-rule-them-all, but as a tool for the average programmer","quote_url":"https://news.ycombinator.com/item?id=10838283","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('w3WYdYyjek4','hn',6.5,'{"vid":"w3WYdYyjek4","title":"TigerStyle! (Or How To Design Safer Systems in Less Time) by Joran Dirk Greef","channel":"TigerBeetle","summary":"Joran Dirk Greef''s Systems Distributed ''23 talk on TigerStyle, the engineering methodology behind TigerBeetle. It covers designing safer systems in less time through up-front design, assertions, and deterministic simulation.","why":"HN commenters, including TigerBeetle people, recommend it as the explanation of a methodology for building defect-free, high-assurance software.","type":"talk","level":"intermediate","score":6.5,"topics":["Software design & craft","Databases & distributed"],"recs":2,"years":[2023,2025],"quote":"The TigerStyle video is well worth watching for anyone who wants to build defect-free software systems","quote_url":"https://news.ycombinator.com/item?id=40851012","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5uljtqyBLxI','hn',6.0,'{"vid":"5uljtqyBLxI","title":"Java on a 1000 Cores - Tales of Hardware / Software CoDesign","channel":"Google TechTalks","summary":"Cliff Click of Azul Systems gives a Google Tech Talk on running Java business applications on a machine with about a thousand cores. He covers hardware and software codesign, including garbage collection hardware and the JIT.","why":"HN treats Cliff Click''s talks as an excellent source on JVMs, garbage collection and hardware-assisted Java.","type":"talk","level":"advanced","score":6.0,"topics":["Languages & compilers"],"recs":5,"years":[2009,2025],"quote":"Anything from Cliff Click is quite good.","quote_url":"https://news.ycombinator.com/item?id=5519772","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('79fvDDPaIoY','hn',6.0,'{"vid":"79fvDDPaIoY","title":"Bryan Cantrill from Joyent on Manta: internet-facing object storage facility that features compute","channel":"AI Council","summary":"Bryan Cantrill of Joyent presents Manta, an internet-facing object store that lets you run compute directly on the data. The talk is peppered with ZFS history and Cantrill''s trademark commentary on the industry.","why":"HN recommends Cantrill talks generally for their mix of industry history, technical depth and entertaining delivery, and this one is a favorite for storage and data integrity threads.","type":"talk","level":"intermediate","score":6.0,"topics":["Databases & distributed"],"recs":4,"years":[2014,2026],"quote":"I highly recommend any talk you can find of Bryan Cantrill. A wonderful mix of industry history and great delivery.","quote_url":"https://news.ycombinator.com/item?id=15975691","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Agu6jipKfYw','hn',6.0,'{"vid":"Agu6jipKfYw","title":"\"Controlling Time and Space: understanding the many formulations of FRP\" by Evan Czaplicki","channel":"Strange Loop Conference","summary":"Evan Czaplicki''s Strange Loop 2014 talk surveys the many formulations of functional reactive programming and how they relate historically and theoretically. It then shows how Elm''s variant enables hot-swapping and its time-traveling debugger.","why":"HN people point to it as the clearest explanation of what FRP actually means and how its flavors differ.","type":"talk","level":"intermediate","score":6.0,"topics":["Languages & compilers","Web"],"recs":5,"years":[2014,2026],"quote":"I highly recommend Evan''s Strange Loop talk","quote_url":"https://news.ycombinator.com/item?id=8730127","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('C2RO34b_oPM','hn',6.0,'{"vid":"C2RO34b_oPM","title":"Taking Vector Transposes Seriously | Jiahao Chen | JuliaCon 2017","channel":"The Julia Programming Language","summary":"Jiahao Chen''s JuliaCon 2017 talk argues that vector transposes should be taken seriously in type systems and linear algebra libraries. It explains why treating vectors as matrices causes trouble in languages.","why":"Strongly recommended for anyone working with vectors for its clear take on how they should be treated in types.","type":"talk","level":"advanced","score":6.0,"topics":["Languages & compilers"],"recs":3,"years":[2018,2022],"quote":"but seriously take the time to watch this, it''s fantastic","quote_url":"https://news.ycombinator.com/item?id=24862320","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DgVS-zXgMTk','hn',6.0,'{"vid":"DgVS-zXgMTk","title":"Pete Hunt: React - Rethinking Best Practices (updated) - JSConf.Asia 2013","channel":"JSConf","summary":"Pete Hunt of Facebook and Instagram presents React at JSConf.Asia 2013, explaining its design principles and why they seemed shocking at first. He argues that React separates concerns rather than technologies, and the talk also announces the React Chrome developer tools.","why":"HN commenters credit it with persuading them to adopt React, and cite it for the argument that HTML and JS cannot truly be separated.","type":"talk","level":"intermediate","score":6.0,"topics":["Web","Software design & craft"],"recs":5,"years":[2014,2024],"quote":"Pete Hunt did a great job then, explaining how the false separation of concerns between HTML and JS really is unavoidable.","quote_url":"https://news.ycombinator.com/item?id=15057559","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DmT80OseAGs','hn',6.0,'{"vid":"DmT80OseAGs","title":"A Sudoku Solver in APL","channel":"Dyalog","summary":"A Dyalog demonstration of developing a Sudoku solver in APL, using an algorithm by Arthur Whitney with performance work by John Scholes. The narration steps through the array-oriented solution.","why":"Strongly recommended as a beautiful demonstration that APL can be read and reasoned about step by step.","type":"demo","level":"intermediate","score":6.0,"topics":["Languages & compilers","DSA"],"recs":4,"years":[2015,2022],"quote":"I''ve always liked this video, where one of the Dyalog developers effortlessly writes a Sudoku solver in APL","quote_url":"https://news.ycombinator.com/item?id=30796413","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ELeZAKCN4tY','hn',6.0,'{"vid":"ELeZAKCN4tY","title":"Can C++ be 10x Simpler & Safer?  - Herb Sutter - CppCon 2022","channel":"CppCon","summary":"Herb Sutter''s CppCon 2022 talk on whether C++ can become ten times simpler and safer. He introduces his experimental Cpp2 syntax and the cppfront transpiler, explaining the limits on incremental improvement.","why":"HN recommends it as the main introduction to Cpp2 and cppfront, and as a credible effort to evolve C++.","type":"talk","level":"advanced","score":6.0,"topics":["Systems & performance","Languages & compilers"],"recs":6,"years":[2022,2024],"quote":"One of those few talks that left me genuinely enthused about the topic.","quote_url":"https://news.ycombinator.com/item?id=39888482","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HJ-719EGIts','hn',6.0,'{"vid":"HJ-719EGIts","title":"Advanced Topics in Programming Languages: A Lock-Free Hash Table","channel":"GoogleTalksArchive","summary":"A 2007 Google Tech Talk in which Cliff Click of Azul Systems presents a lock-free concurrent hash table that scales to 768 CPUs. He explains why it is correct by reasoning in a different way than usual happens-before and memory-order arguments.","why":"HN regards it as one of the best technical talks, a deep and clear walkthrough of scalable lock-free hash tables built on compare-and-swap.","type":"talk","level":"advanced","score":6.0,"topics":["DSA","Systems & performance"],"recs":4,"years":[2013,2024],"quote":"I highly recommend this talk by Cliff Click about building highly scalable hash tables via Compare And Swap","quote_url":"https://news.ycombinator.com/item?id=41691789","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KRcecxdGxvQ','hn',6.0,'{"vid":"KRcecxdGxvQ","title":"Michael Stonebraker | Big Data is (at least) Four Different Problems","channel":"Michigan Engineering","summary":"Database pioneer Michael Stonebraker argues that ''big data'' is really at least four different problems: big volumes with small analytics, big analytics, velocity, and variety. He comments on where each market is heading.","why":"HN points to it as a thoughtful, first-principles take from a Turing award winner that cuts through NoSQL and big data hype.","type":"lecture","level":"intermediate","score":6.0,"topics":["Databases & distributed","AI & ML"],"recs":5,"years":[2015,2024],"quote":"a rather interesting talk by a very thoughtful Turing award winning engineer named Michael Stonebraker","quote_url":"https://news.ycombinator.com/item?id=15127778","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NH1Tta7purM','hn',6.0,'{"vid":"NH1Tta7purM","title":"CppCon 2017: Carl Cook “When a Microsecond Is an Eternity: High Performance Trading Systems in C++”","channel":"CppCon","summary":"Optiver''s Carl Cook explains how to build high-frequency trading systems in C++, where the critical path runs rarely but must be extremely fast. He covers techniques for low and predictable latency, including avoiding main memory and cache misses.","why":"HN repeatedly points people to it as the best overview of low-latency trading engineering.","type":"talk","level":"advanced","score":6.0,"topics":["Systems & performance"],"recs":5,"years":[2017,2025],"quote":"Here are some talks that will give you a small overview into that world","quote_url":"https://news.ycombinator.com/item?id=23191261","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('R2Aa4PivG0g','hn',6.0,'{"vid":"R2Aa4PivG0g","title":"\"I See What You Mean\" by Peter Alvaro","channel":"Strange Loop Conference","summary":"Peter Alvaro''s Strange Loop 2015 talk argues that query languages let you state what you mean, and applies that to distributed programming. It covers Datalog, Dedalus and the Bloom lineage for reasoning about distributed systems.","why":"Recommended as a fantastic introduction to declarative and Datalog-based distributed systems and failure modeling.","type":"talk","level":"intermediate","score":6.0,"topics":["Databases & distributed"],"recs":6,"years":[2016,2019],"quote":"I highly recommend watching Peter Alvaro’s Strangeloop talk about creating Dedalus","quote_url":"https://news.ycombinator.com/item?id=19509999","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('UEAMfLPZZhE','hn',6.0,'{"vid":"UEAMfLPZZhE","title":"Distributed Systems 1.1: Introduction","channel":"Martin Kleppmann","summary":"The first lecture in Martin Kleppmann''s 8-lecture distributed systems series from the University of Cambridge undergraduate course. It introduces the subject, and accompanying lecture notes are available.","why":"HN regularly recommends the series as a free, accessible, theory-oriented course on distributed computing that complements his book Designing Data-Intensive Applications.","type":"lecture","level":"intermediate","score":6.0,"topics":["Databases & distributed"],"recs":5,"years":[2021,2025],"quote":"the distributed system audio course on youtube is extremely accessible","quote_url":"https://news.ycombinator.com/item?id=29696717","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YX3iRjKj7C0','hn',6.0,'{"vid":"YX3iRjKj7C0","title":"RailsConf 09:  Robert Martin, \"What Killed Smalltalk Could K","channel":"O''Reilly","summary":"Robert Martin''s RailsConf 2009 talk looks at why Smalltalk lost out despite its technical strengths. He draws lessons about language communities and arrogance that he argues could hurt Ruby too.","why":"HN cites it in discussions of language evangelism, community dynamics and zealotry, as an accessible account of how a good language can die for non-technical reasons.","type":"talk","level":"general","score":6.0,"topics":["Languages & compilers"],"recs":5,"years":[2012,2026],"quote":"I find this talk [0] very informative and useful while interacting with other languages and communities.","quote_url":"https://news.ycombinator.com/item?id=32992695","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YX40hbAHx3s','hn',6.0,'{"vid":"YX40hbAHx3s","title":"P vs. NP and the Computational Complexity Zoo","channel":"hackerdashery","summary":"An 11-minute animated introduction to P vs. NP and the wider landscape of complexity classes, inspired by the Complexity Zoo wiki. It assumes no background in computer science.","why":"HN repeatedly recommends it as the best short, funny introduction to P vs. NP and complexity classes for people with no background.","type":"explainer","level":"intro","score":6.0,"topics":["Math & theory"],"recs":4,"years":[2015,2026],"quote":"This 10 minute video is a great introduction to the P = NP problem and computational complexity theory if you have no context.","quote_url":"https://news.ycombinator.com/item?id=12895743","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bSfe5M_zG2s','hn',6.0,'{"vid":"bSfe5M_zG2s","title":"K Lars Lohn - Keynote - PyCon 2016","channel":"PyCon 2016","summary":"K Lars Lohn''s PyCon 2016 keynote weaves together music theory, programming, biking road trips and fractals. It is a personal, wide-ranging talk rather than a Python how-to.","why":"Commenters call it a mind-blowing, beautiful talk and cite it among their favorite tech talks.","type":"talk","level":"general","score":6.0,"topics":["Python","Languages & compilers"],"recs":4,"years":[2016,2021],"quote":"It''s a beautiful talk about music, programming, biking, and life","quote_url":"https://news.ycombinator.com/item?id=11832173","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cQP8WApzIQQ','hn',6.0,'{"vid":"cQP8WApzIQQ","title":"Lecture 1: Introduction","channel":"MIT 6.824: Distributed Systems","summary":"The opening lecture of MIT 6.824 Distributed Systems (Spring 2020), introducing the course and core challenges of distributed systems. It begins a playlist that goes on to cover Raft and other consensus papers in Go.","why":"Recommended as the standard free course for learning distributed systems from real papers.","type":"lecture","level":"intermediate","score":6.0,"topics":["Databases & distributed"],"recs":5,"years":[2020,2025],"quote":"Martin Kleppmann (author of DDIA)","quote_url":"https://news.ycombinator.com/item?id=43197284","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cidchWg74Y4','hn',6.0,'{"vid":"cidchWg74Y4","title":"Simplicity Ain''t Easy - Stuart Halloway","channel":"ClojureTV","summary":"Stuart Halloway argues that simplicity is objective, with a definition and etymology useful to programmers, rather than a subjective buzzword. He shows how this view informs Clojure''s design and how to make programs simpler.","why":"HN commenters recommend it, alongside Rich Hickey''s talk, for its precise definition of simple versus easy and its implications for code design.","type":"talk","level":"intermediate","score":6.0,"topics":["Software design & craft","Languages & compilers"],"recs":5,"years":[2013,2017],"quote":"He talks about his definition of \"simple\" (by digging into what the original English definition was) and what that means for code.","quote_url":"https://news.ycombinator.com/item?id=7709206","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dGVqrGmwOAw','hn',6.0,'{"vid":"dGVqrGmwOAw","title":"Clojure Concurrency - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey''s long presentation on Clojure and concurrency covers locking and immutability, then goes in depth on refs, transactions and agents. It ends with a multithreaded ant colony simulation demo.","why":"Seen as the definitive explanation of why traditional concurrency is hard and how Clojure''s model addresses it, with some commenters crediting it with changing their careers.","type":"talk","level":"intermediate","score":6.0,"topics":["Languages & compilers","Software design & craft"],"recs":5,"years":[2013,2023],"quote":"one my favorite talks I ever went to.","quote_url":"https://news.ycombinator.com/item?id=23174139","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fE2KDzZaxvE','hn',6.0,'{"vid":"fE2KDzZaxvE","title":"Zebras All the Way Down - Bryan Cantrill, Uptime 2017","channel":"Code & Supply","summary":"Bryan Cantrill''s Uptime 2017 talk on the engineering challenges of the stateful data path, including storage, firmware and hardware bugs. It uses the ''zebras vs. horses'' diagnostic heuristic to explain why rare failures keep appearing.","why":"A perennial HN favorite whenever firmware, disks, ECC or opaque hardware come up, valued as both entertaining and sobering.","type":"talk","level":"intermediate","score":6.0,"topics":["Databases & distributed","Software design & craft"],"recs":6,"years":[2018,2025],"quote":"As with all his talks, you can expect it to be quite entertaining as well as informative","quote_url":"https://news.ycombinator.com/item?id=22165352","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('f_0QlhYlS8g','hn',6.0,'{"vid":"f_0QlhYlS8g","title":"Factor: an extensible interactive language","channel":"Google TechTalks","summary":"A 2008 Google Tech Talk in which Slava Pestov introduces Factor, a concatenative language influenced by Forth, Lisp and Smalltalk. It covers the interactive environment, metaprogramming, and the language''s modern high-level features and libraries.","why":"HN recommends it as the best introduction to Factor and concatenative programming, with commenters saying it impressed them with the engineering.","type":"talk","level":"intermediate","score":6.0,"topics":["Languages & compilers"],"recs":5,"years":[2014,2025],"quote":"It absolutely blew my mind.","quote_url":"https://news.ycombinator.com/item?id=18128634","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('jo_B4LTHi3I','hn',6.0,'{"vid":"jo_B4LTHi3I","title":"Introduction to Node.js with Ryan Dahl","channel":"InfoQ","summary":"Ryan Dahl, the creator of Node.js, introduces the event-driven I/O framework built on V8 with examples, and discusses the v0.4.0 release and its new APIs.","why":"Recommended as a short, fun talk on Node''s philosophy and the reasons it was built that remains relevant.","type":"talk","level":"intermediate","score":6.0,"topics":["Web"],"recs":5,"years":[2011,2018],"quote":"it''s not really outdated. It''s a short talk, but it talks a little about Node''s philosophy and I highly recommend watching it.","quote_url":"https://news.ycombinator.com/item?id=4157286","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lMcRBdSdO_U','hn',6.0,'{"vid":"lMcRBdSdO_U","title":"\"Shen: A Sufficiently Advanced Lisp\" by Aditya Siram","channel":"Strange Loop Conference","summary":"Aditya Siram introduces Shen, a small hosted Lisp with macros, a built-in Prolog and an optional type system. The talk demos a full web app moving between functional, logic and imperative styles, including turning JSON into a type with macros.","why":"It is the standard recommended introduction to Shen, pointed to whenever Shen or its type system comes up.","type":"talk","level":"intermediate","score":6.0,"topics":["Languages & compilers"],"recs":2,"years":[2015,2024],"quote":"@deech''s talks, though older now, are fantastic and relevant[1,2].","quote_url":"https://news.ycombinator.com/item?id=37480645","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lhYGXYeMq_E','hn',6.0,'{"vid":"lhYGXYeMq_E","title":"Why Greatness Cannot Be Planned — Kenneth Stanley","channel":"Machine Learning Street Talk","summary":"A long Machine Learning Street Talk interview with Kenneth Stanley, creator of NEAT and novelty search, about his book on why greatness cannot be planned. They discuss open-endedness, the tyranny of objectives, serendipity and the evolution of ideas.","why":"Recommended to people who find it inspiring or perspective-changing on pursuing goals, open-ended search and AI beyond optimization.","type":"interview","level":"intermediate","score":6.0,"topics":["AI & ML"],"recs":4,"years":[2021,2024],"quote":"It really changed my perspective on achieving my long term goals","quote_url":"https://news.ycombinator.com/item?id=27251958","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mbyG85GZ0PI','hn',6.0,'{"vid":"mbyG85GZ0PI","title":"Lecture 01 - The Learning Problem","channel":"caltech","summary":"The first lecture of Caltech''s CS 156 Machine Learning course by Yaser Abu-Mostafa, introducing the learning problem and supervised, unsupervised and reinforcement learning. It is one of 18 lectures in the Learning from Data course.","why":"Recommended repeatedly in ''where do I start with ML'' threads as a clear, math-aware introduction.","type":"course","level":"intro","score":6.0,"topics":["AI & ML"],"recs":5,"years":[2016,2023],"quote":"I have found the Caltech machine learning intro course to be the most elucidating of any resource so far","quote_url":"https://news.ycombinator.com/item?id=35545633","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nLApFANtkHs','hn',6.0,'{"vid":"nLApFANtkHs","title":"ElixirConf 2018 - Docker and OTP Friends or Foes - Daniel Azuma","channel":"ElixirConf","summary":"Daniel Azuma''s ElixirConf 2018 talk on whether Docker and OTP conflict. He shows they can coexist and uses Horde and DeltaCrdt, with a live tank-game demo, to keep state alive across container kills.","why":"Recommended for its practical strategy for preserving state on ephemeral containers, and for the live demo.","type":"talk","level":"advanced","score":6.0,"topics":["Languages & compilers"],"recs":4,"years":[2018,2023],"quote":"I would recommend watching Dan Azuma''s fantastic video (stick around for the live demo)","quote_url":"https://news.ycombinator.com/item?id=22416648","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oJTwQvgfgMM','hn',6.0,'{"vid":"oJTwQvgfgMM","title":"Emacs Org-mode - a system for note-taking and project planning","channel":"Google TechTalks","summary":"A 2008 Google Tech Talk by the creator of Org-mode, introducing the Emacs subsystem for plain-text note-taking and project planning. It covers outlines, TODO states, tags, dates and priorities, and later shows using Org-mode as a spreadsheet.","why":"HN regards it as the best introduction and advertisement for Org-mode, and many say it was enough to get them started with it.","type":"talk","level":"intro","score":6.0,"topics":["Software design & craft"],"recs":5,"years":[2009,2024],"quote":"The best advertisement for org-mode I''ve seen is this long Google Tech Talk","quote_url":"https://news.ycombinator.com/item?id=2424309","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oKg1hTOQXoY','hn',6.0,'{"vid":"oKg1hTOQXoY","title":"Alan Kay at OOPSLA 1997 - The computer revolution hasnt happened yet","channel":"Jeff Gonis","summary":"Alan Kay''s 1997 OOPSLA keynote, preserved on YouTube after being lost from Google Video. He discusses what object orientation was meant to be, messaging, system design, and the state of computing practice.","why":"Treated as a foundational talk, cited constantly for Kay''s views on object-oriented programming and for rethinking software practice.","type":"talk","level":"intermediate","score":6.0,"topics":["Software design & craft"],"recs":6,"years":[2013,2025],"quote":"I encourage all developers to watch that talk and do some thinking about the current state of our practice","quote_url":"https://news.ycombinator.com/item?id=7071827","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pQ0CvjAJXz4','hn',6.0,'{"vid":"pQ0CvjAJXz4","title":"GigCityElixir23 - Bryan Hunter","channel":"Groxio","summary":"Bryan Hunter''s GigCityElixir 2023 talk on HCA Healthcare''s Waterpark system, built on Elixir/Erlang. It describes how the architecture is distributed and fault-tolerant, with a multi-datacenter cluster and runtime code swapping.","why":"HN recommends it as a rare real-world look at a large fault-tolerant Erlang/Elixir system with no downtime in healthcare.","type":"talk","level":"intermediate","score":6.0,"topics":["Databases & distributed","Languages & compilers"],"recs":4,"years":[2023,2025],"quote":"an excellent presentation of design/architecture of a Real-World fault-tolerant and distributed System in Erlang/Elixir","quote_url":"https://news.ycombinator.com/item?id=38814668","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vzfy4EKwG_Y','hn',6.0,'{"vid":"vzfy4EKwG_Y","title":"\"Outperforming Imperative with Pure Functional Languages\" by Richard Feldman","channel":"Strange Loop Conference","summary":"Richard Feldman explains how pure functional languages can match or beat imperative ones on performance. Compilers can turn immutable code into in-place mutation, avoiding naive copying. The talk draws on his work on the Roc language.","why":"Recommended as the clearest explanation of why immutable data need not be slow, and as the introduction to Roc.","type":"talk","level":"intermediate","score":6.0,"topics":["Languages & compilers","Systems & performance"],"recs":6,"years":[2021,2025],"quote":"As a starting point for those nitty grittys, this talk is probably as good as any","quote_url":"https://news.ycombinator.com/item?id=31920208","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('1bNOO3xxMc0','hn',5.5,'{"vid":"1bNOO3xxMc0","title":"Zach Tellman - Everything Will Flow","channel":"ClojureTV","summary":"Zach Tellman''s Clojure West talk covers the basics of queueing theory and its practical use in systems, including backpressure, how queues break down under load, and pitfalls of naive core.async use.","why":"HN recommends it as a fascinating explanation of queues, flow control and overload that applies well beyond Clojure.","type":"talk","level":"intermediate","score":5.5,"topics":["Databases & distributed","Languages & compilers","LLMs","AI & ML"],"recs":4,"years":[2015,2022],"quote":"He talks about queues and how they break down under load.","quote_url":"https://news.ycombinator.com/item?id=14961501","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2wZ1pCpJUIM','hn',5.5,'{"vid":"2wZ1pCpJUIM","title":"Scale By The Bay 2018: Bryan Cantrill, Rust and Other Interesting Things","channel":"FunctionalTV","summary":"Bryan Cantrill argues that programming languages and platforms reflect core values, and compares languages through that lens, with Rust as a main example. He draws on his experience with Solaris, DTrace and ZFS.","why":"Cited again and again as the framework for discussing languages in terms of values, and how organizational values shape software quality.","type":"talk","level":"intermediate","score":5.5,"topics":["Languages & compilers","Systems & performance"],"recs":5,"years":[2021,2024],"quote":"Bryan Cantrill has an excellent talk on this","quote_url":"https://news.ycombinator.com/item?id=31400878","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('72y2EC5fkcE','hn',5.5,'{"vid":"72y2EC5fkcE","title":"Tomorrow Corporation Tech Demo","channel":"retrogameinternals","summary":"Allan Blomquist demonstrates the internal programming and debugging tools Tomorrow Corporation uses to make games, including live modification of a running game and time-travel debugging.","why":"Held up in debugger and tooling threads as an amazing ideal of a tight feedback loop and what debugging could be.","type":"demo","level":"intermediate","score":5.5,"topics":["Software design & craft"],"recs":5,"years":[2023,2026],"quote":"this demo has got to be the closest thing to the perfect debugger I''ve ever seen","quote_url":"https://news.ycombinator.com/item?id=35097020","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8JOD1AQGqEg','hn',5.5,'{"vid":"8JOD1AQGqEg","title":"The Web That Never Was - Dylan Beattie","channel":"NDC Conferences","summary":"Dylan Beattie''s entertaining NDC talk imagines an alternate history of the web, asking what if different decisions had been made on operating systems, browsers and standards. It blends real history with humor.","why":"HN commenters strongly recommend it as a fun alt-history of the web and bring it up whenever people muse about how the web could have been different.","type":"talk","level":"general","score":5.5,"topics":["Web"],"recs":3,"years":[2023,2026],"quote":"Edit 2: finished, it is definitely worth watching.","quote_url":"https://news.ycombinator.com/item?id=38796187","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('98LdFA-_zfA','hn',5.5,'{"vid":"98LdFA-_zfA","title":"Christopher Alexander - Patterns in Architecture","channel":"Peter Petrash","summary":"Christopher Alexander''s keynote at OOPSLA 1996 on patterns in architecture, addressed to the software community. He moves beyond patterns toward deeper ideas of wholeness and living structure.","why":"HN cites it as the primary source for the claim that Alexander deprecated patterns, and as a prescient talk for programmers.","type":"talk","level":"intermediate","score":5.5,"topics":["Software design & craft"],"recs":4,"years":[2016,2026],"quote":"Just finished watching a great 1996 lecture by Christopher Alexander","quote_url":"https://news.ycombinator.com/item?id=18648331","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('CaCcOwJPytQ','hn',5.5,'{"vid":"CaCcOwJPytQ","title":"Special Topics - The Kalman Filter (1 of 55) What is a Kalman Filter?","channel":"Michel van Biezen","summary":"The first video in a 55-part series by Michel van Biezen that introduces the Kalman filter and builds from the rationale through algebraic examples to the full matrix treatment. The videos are short, blackboard-style lectures.","why":"HN repeatedly recommends this series as a clear, step-by-step way to really understand Kalman filtering.","type":"course","level":"intro","score":5.5,"topics":["AI & ML"],"recs":5,"years":[2017,2025],"quote":"It''s really worth watching even just the first couple videos to get a deeper understanding of this very useful technique.","quote_url":"https://news.ycombinator.com/item?id=29475414","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('GqmsQeSzMdw','hn',5.5,'{"vid":"GqmsQeSzMdw","title":"Constraints Liberate, Liberties Constrain — Runar Bjarnason","channel":"Scala World","summary":"Runar Bjarnason''s Scala World talk argues that restraint and precision in components beat power and flexibility. Constraints on parts make them easier to compose into systems.","why":"HN recommends it as a talk that changes how you think about system design, and links it whenever constraints, abstraction or least power come up.","type":"talk","level":"intermediate","score":5.5,"topics":["Languages & compilers","Software design & craft"],"recs":5,"years":[2016,2025],"quote":"It had a real impact on the way I think about the design of systems.","quote_url":"https://news.ycombinator.com/item?id=16839349","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Hqw57GJSrac','hn',5.5,'{"vid":"Hqw57GJSrac","title":"Cliff Click @ VMSS16: Bits of Advice For the VM Writer","channel":"softdevteamuk","summary":"Cliff Click, author of HotSpot''s JIT compiler, shares hard-won advice for people writing virtual machines at the VMSS16 workshop. Topics include interpreters, JITs and performance lessons.","why":"HN recommends it, and Cliff Click''s talks in general, as practical wisdom from someone who built HotSpot and worked on Azul''s VMs.","type":"talk","level":"advanced","score":5.5,"topics":["Languages & compilers","Systems & performance"],"recs":2,"years":[2017,2021],"quote":"I strongly recommend following and listening to videos by Cliff Click who wrote HotSpot and worked on Azul and other VMs.","quote_url":"https://news.ycombinator.com/item?id=29315044","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KAWA1DuvCnQ','hn',5.5,'{"vid":"KAWA1DuvCnQ","title":"Dconf 2014 Day 2 Keynote: The Last Thing D Needs -- Scott Meyers","channel":"The D Language Foundation","summary":"Scott Meyers'' keynote at DConf 2014, drawing on 25 years of C++ experience to offer the D language community a plea about what it should avoid. It centers on the accumulated complexity and pitfalls of C++ as a cautionary tale.","why":"HN commenters bring it up whenever C++ complexity or the pitfalls of language design come up, as a witty and authoritative warning.","type":"talk","level":"intermediate","score":5.5,"topics":["Languages & compilers","Systems & performance"],"recs":4,"years":[2018,2025],"quote":"everyone should watch Scott Meyers''s awesome presentation at a D conference","quote_url":"https://news.ycombinator.com/item?id=27938191","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NRoUC9P1PmA','hn',5.5,'{"vid":"NRoUC9P1PmA","title":"ZFS: The Last Word in File Systems Part 1","channel":"Deirdré Straughan","summary":"Jeff Bonwick and Bill Moore, the creators of ZFS, present ''ZFS: The Last Word in File Systems'' at the 2008 SNIA Software Developers'' Conference. They explain the design, including copy-on-write, checksumming and avoiding the write hole.","why":"HN recommends it as the definitive explanation of ZFS design straight from its inventors, with war stories about data integrity.","type":"talk","level":"intermediate","score":5.5,"topics":["Databases & distributed"],"recs":4,"years":[2016,2026],"quote":"I would recommend anybody interested in filesystems to watch Jeff Bonwick (ZFS inventor) explain the design of ZFS","quote_url":"https://news.ycombinator.com/item?id=11982302","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NVl9_6J1G60','hn',5.5,'{"vid":"NVl9_6J1G60","title":"Breakout Session Presented by Dan Robinson of Heap at PGConf Silicon Valley 2015","channel":"Citus Data","summary":"Dan Robinson, then CTO of Heap, explains how Heap runs its product analytics backend on PostgreSQL and CitusDB. It covers conversion funnels, retention and cohort queries across tens of billions of events and 50 TB of data, plus Postgres and Kafka together and the indexing strategy.","why":"HN commenters point to it as a first-hand overview of Heap''s Postgres/Citus architecture and its distinctive indexing approach.","type":"talk","level":"advanced","score":5.5,"topics":["Databases & distributed"],"recs":4,"years":[2016,2020],"quote":"Dan from Heap Analytics has a great talk about how they use Postgres and Citus.","quote_url":"https://news.ycombinator.com/item?id=12396191","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('P3AyI_u66Bw','hn',5.5,'{"vid":"P3AyI_u66Bw","title":"Larry Hastings - Removing Python''s GIL: The Gilectomy - PyCon 2016","channel":"PyCon 2016","summary":"Larry Hastings explains what Python''s GIL is, what problems it solves and how it works, and presents his Gilectomy project to remove it, including the performance and C-extension obstacles.","why":"The default reference in Python performance threads for why removing the GIL is hard.","type":"talk","level":"advanced","score":5.5,"topics":["Python","Languages & compilers","Systems & performance"],"recs":5,"years":[2016,2023],"quote":"I think Larry Hasting''s first Gilectomy talk was extremely insightful","quote_url":"https://news.ycombinator.com/item?id=15010476","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PE4gwstWhmc','hn',5.5,'{"vid":"PE4gwstWhmc","title":"How We''ve Scaled Dropbox","channel":"Stanford","summary":"Dropbox engineer Kevin Modzelewski gives a Stanford colloquium on Dropbox''s history and the technical problems it faced scaling, including detailed database schema decisions.","why":"Recommended as a detailed, candid case study of scaling a real system from zero users to millions.","type":"talk","level":"intermediate","score":5.5,"topics":["Databases & distributed"],"recs":5,"years":[2014,2023],"quote":"I found the Dropbox lecture [1] at Stanford one of the most riveting things ever.","quote_url":"https://news.ycombinator.com/item?id=18070352","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ScEPu1cs4l0','hn',5.5,'{"vid":"ScEPu1cs4l0","title":"Are We There Yet - Rich Hickey","channel":"Zhang Jian","summary":"Rich Hickey''s talk on time, state, identity and values, arguing that mutable object-oriented modeling fits the world poorly. It lays out the thinking behind Clojure''s approach to data and change.","why":"Recommended as one of the best explanations of why Clojure and a functional, immutable approach to state exist.","type":"talk","level":"intermediate","score":5.5,"topics":["Languages & compilers","Software design & craft"],"recs":4,"years":[2021,2026],"quote":"One of the best \"why Clojure\" talks that I''ve seen","quote_url":"https://news.ycombinator.com/item?id=27389178","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('TgmA48fILq8','hn',5.5,'{"vid":"TgmA48fILq8","title":"Dtrace Review","channel":"GoogleTalksArchive","summary":"Bryan Cantrill''s 2007 Google Tech Talk on DTrace, showing how dynamic tracing improves debugging of both development and live production systems. It includes a vivid war story about tracking down a problem on a Sun Ray server.","why":"HN regards it as a gem of a technical talk that tackles a fundamental debugging problem and shows a new technology solving it.","type":"talk","level":"intermediate","score":5.5,"topics":["Software design & craft","Systems & performance"],"recs":4,"years":[2013,2026],"quote":"I''m partial to Bryan Cantrill''s Dtrace talk since it tackles a fundamental problem in software engineering and shows how to solve it using a new technology.","quote_url":"https://news.ycombinator.com/item?id=5512754","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('URSWYvyc42M','hn',5.5,'{"vid":"URSWYvyc42M","title":"Rails Conf 2013 The Magic Tricks of Testing by Sandi Metz","channel":"Confreaks","summary":"Sandi Metz''s RailsConf 2013 talk offers practical guidelines for deciding what to test and how, so tests stay cheap and stable. She argues for testing the public interface rather than implementation and using mocks appropriately.","why":"HN recommends it as an incredible talk whose testing principles apply beyond Ruby.","type":"talk","level":"intermediate","score":5.5,"topics":["Software design & craft"],"recs":5,"years":[2013,2019],"quote":"watch Sandi Metz'' incredible RailsConf talk","quote_url":"https://news.ycombinator.com/item?id=6450331","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('VUhlNx_-wYk','hn',5.5,'{"vid":"VUhlNx_-wYk","title":"Ruby Manor 3 - Programming with Nothing by Tom Stuart","channel":"Confreaks","summary":"Tom Stuart''s Ruby Manor 3 talk builds FizzBuzz using nothing but Ruby lambdas, working through Church encodings of numbers, booleans and data structures. It is a hands-on introduction to lambda calculus.","why":"Strongly recommended in lambda calculus and Y-combinator threads as a mind-expanding half hour that clarifies the ideas.","type":"talk","level":"intermediate","score":5.5,"topics":["Math & theory","Languages & compilers"],"recs":4,"years":[2013,2019],"quote":"An awesome video which changed my perspective towards lambda calculus and programming in general","quote_url":"https://news.ycombinator.com/item?id=9301755","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YyIQKBzIuBY','hn',5.5,'{"vid":"YyIQKBzIuBY","title":"Alan Kay - Programming and Scaling","channel":"Colin McDonnell","summary":"An Alan Kay talk on programming and scaling, covering theoretical limits of code size, engineering versus tinkering, and biological cells as inspiration for object-oriented design.","why":"HN fans call it one of Kay''s best talks and recommend it for rethinking why programming paradigms have barely changed.","type":"talk","level":"intermediate","score":5.5,"topics":["Software design & craft"],"recs":4,"years":[2016,2026],"quote":"This talk is excellent and will cue you in on how to go about thinking about the fact","quote_url":"https://news.ycombinator.com/item?id=49072484","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('iukBMY4apvI','hn',5.5,'{"vid":"iukBMY4apvI","title":"Javascript in 2015","channel":"Glen Maddern","summary":"A short screencast tour of JSPM, SystemJS and ES6 features, building a small app with the then-new JavaScript module and package tooling. It shows how JSPM works as a package manager, bundler and loader.","why":"Commenters credit it with opening their eyes to JSPM and using it to choose build systems.","type":"tutorial","level":"intermediate","score":5.5,"topics":["Web","Software design & craft"],"recs":3,"years":[2015,2017],"quote":"This video really opened my eyes to what it could do","quote_url":"https://news.ycombinator.com/item?id=11018397","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mVVNJKv9esE','hn',5.5,'{"vid":"mVVNJKv9esE","title":"Cheng Lou - On the Spectrum of Abstraction at react-europe 2016","channel":"ReactEurope","summary":"Cheng Lou''s react-europe 2016 talk lays out a mental framework for thinking about abstraction levels in JavaScript tooling, from Angular and Grunt to Webpack and React. It uses that framework to reason about the cost of abstractions and how to choose between competing solutions.","why":"HN points to it as thought-provoking material on the tradeoffs and costs of abstraction, especially in frontend tooling debates.","type":"talk","level":"intermediate","score":5.5,"topics":["Web","Software design & craft"],"recs":5,"years":[2016,2022],"quote":"This talk is incredible food for thought","quote_url":"https://news.ycombinator.com/item?id=13967225","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mZyvIHYn2zk','hn',5.5,'{"vid":"mZyvIHYn2zk","title":"The Pervert''s Guide to Computer Programming Languages - SXSW","channel":"Vulk Coop","summary":"A SXSW talk by W Watson that uses Lacanian psychoanalysis, with nods to Zizek, to critique popular programming languages. It argues that people choose and defend languages for emotional and ideological reasons rather than rational ones.","why":"HN recommends it as an entertaining and eye-opening look at the irrational psychology behind language preferences, though some note it is not scientifically precise.","type":"talk","level":"general","score":5.5,"topics":["Languages & compilers"],"recs":6,"years":[2019,2025],"quote":"one of the best and eye-opening talks I''ve ever heard","quote_url":"https://news.ycombinator.com/item?id=23080968","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nYkdrAPrdcw','hn',5.5,'{"vid":"nYkdrAPrdcw","title":"Hacker Way: Rethinking Web App Development at Facebook","channel":"Meta Developers","summary":"Facebook engineers explain why they abandoned the traditional MVC paradigm for a more functional architecture, introducing Flux and React. They use the unread-message-count bug as a case study of the problems of bidirectional data flow at scale.","why":"HN points to it as the original talk that explains the motivation behind React, Flux and Redux, and that sold some commenters on React.","type":"talk","level":"intermediate","score":5.5,"topics":["Web","Software design & craft"],"recs":5,"years":[2014,2024],"quote":"these talks, they are the ones that sold me on React","quote_url":"https://news.ycombinator.com/item?id=36147485","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pYXy-A4siMw','hn',5.5,'{"vid":"pYXy-A4siMw","title":"Intro to AI Safety, Remastered","channel":"Robert Miles AI Safety ","summary":"Robert Miles gives a remastered introduction to AI safety, adapted from a talk in London. It lays out why advanced AI could go wrong and answers common objections.","why":"The default link for newcomers wanting an approachable, entertaining introduction to AI risk and alignment.","type":"talk","level":"intro","score":5.5,"topics":["AI & ML"],"recs":6,"years":[2022,2023],"quote":"It''s quite an approachable intro, often entertaining","quote_url":"https://news.ycombinator.com/item?id=34374754","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pkCLMl0e_0k','hn',5.5,'{"vid":"pkCLMl0e_0k","title":"David Beazley - Lambda Calculus from the Ground Up - PyCon 2019","channel":"PyCon 2019","summary":"David Beazley''s PyCon 2019 tutorial derives the lambda calculus from the ground up in Python, using only single-argument functions. He builds booleans, numerals and more with no other language features.","why":"HN calls it a brilliant, mind-bending introduction to lambda calculus for programmers.","type":"tutorial","level":"intermediate","score":5.5,"topics":["Python","Math & theory","Languages & compilers"],"recs":4,"years":[2019,2021],"quote":"David Beazley gives a brilliant introduction to lambda calculus here","quote_url":"https://news.ycombinator.com/item?id=27661600","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('qbIk7-JPB2c','hn',5.5,'{"vid":"qbIk7-JPB2c","title":"Sparks of AGI: early experiments with GPT-4","channel":"Sebastien Bubeck","summary":"Sebastien Bubeck presents the Sparks of AGI paper at MIT, showing early experiments with GPT-4 across many domains and asking whether artificial intelligence has arrived. It includes the TikZ unicorn example.","why":"HN recommends it as a thought-provoking talk from a researcher with early GPT-4 access, especially for the unicorn degrading under safety tuning.","type":"lecture","level":"intermediate","score":5.5,"topics":["AI & ML","LLMs"],"recs":7,"years":[2023,2026],"quote":"Highly highly highly recommend listen to this lecture by Sebastien Bubeck","quote_url":"https://news.ycombinator.com/item?id=36001923","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('re96UgMk6GQ','hn',5.5,'{"vid":"re96UgMk6GQ","title":"Simon Peyton-Jones: Escape from the ivory tower: the Haskell journey","channel":"Churchill College, University of Cambridge","summary":"Simon Peyton Jones gives Churchill College''s annual computer science lecture on Haskell''s birth and evolution. He covers the most influential ideas, from laziness to monads and type system evolution, plus current developments and guesses about the future.","why":"Recommended as a funny, accessible history of Haskell that is valuable even for people interested in language design in general.","type":"lecture","level":"general","score":5.5,"topics":["Languages & compilers"],"recs":5,"years":[2017,2024],"quote":"It''s a funny talk and it''s worth watching in full","quote_url":"https://news.ycombinator.com/item?id=21172415","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('uL2D3qzHtqY','hn',5.5,'{"vid":"uL2D3qzHtqY","title":"A JVM Does That?","channel":"Google TechTalks","summary":"Cliff Click of Azul Systems asks what a JVM is supposed to do, in a Google Tech Talk from 2011. He covers the services a JVM provides, such as garbage collection and compilation, and the messy reality beneath the abstractions.","why":"A repeated recommendation for anyone interested in VMs, with Click''s talks regarded as unusually informative on JVMs, JITs and the user/kernel boundary.","type":"talk","level":"advanced","score":5.5,"topics":["Languages & compilers"],"recs":4,"years":[2011,2017],"quote":"It''s well worth watching if you are interested in vms at all.","quote_url":"https://news.ycombinator.com/item?id=12639145","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('uk3A41U0iO4','hn',5.5,'{"vid":"uk3A41U0iO4","title":"clojure.core/typing - Matt Adereth","channel":"ClojureTV","summary":"Matt Adereth''s Clojure/conj talk covers the history of keyboards and how he used Clojure generating OpenSCAD to design and build his custom Dactyl ergonomic keyboard, including 3D printing and laser-cut parts.","why":"Recommended as a fantastic talk on code-driven CAD and custom keyboard design, linked in threads on OpenSCAD and keyboards.","type":"talk","level":"intermediate","score":5.5,"topics":["Languages & compilers"],"recs":4,"years":[2016,2023],"quote":"it is a fantastic talk but the part related to this starts at 17:35","quote_url":"https://news.ycombinator.com/item?id=28909206","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zduSFxRajkE','hn',5.5,'{"vid":"zduSFxRajkE","title":"Let''s build the GPT Tokenizer","channel":"Andrej Karpathy","summary":"Andrej Karpathy builds the GPT tokenizer from scratch, implementing byte pair encoding along with encode and decode. He shows how many odd LLM behaviors trace back to tokenization, and covers Unicode byte encodings along the way.","why":"Recommended as the best deep dive on tokenizers, worth the two hours for anyone working with LLMs.","type":"lecture","level":"intermediate","score":5.5,"topics":["Karpathy","AI & ML","LLMs"],"recs":5,"years":[2024,2025],"quote":"Worth spending 2h for the deeper understanding if you deal with LLMs.","quote_url":"https://news.ycombinator.com/item?id=41932357","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('1uflg7LDmzI','hn',5.0,'{"vid":"1uflg7LDmzI","title":"Building a Better Web Browser - James Mickens - Harvard CS Colloquium 2015","channel":"Paul Irish","summary":"James Mickens''s 2015 Harvard colloquium argues that browsers are bloated and insecure because feature races trump clean interface design. He presents a cleaner, more secure browser architecture (Atlantis) with a much smaller API surface.","why":"HN cites it whenever people discuss rebuilding the web platform or what a better browser architecture could look like.","type":"talk","level":"advanced","score":5.0,"topics":["Web","Software design & craft"],"recs":4,"years":[2017,2023],"quote":"which I definitely think this still the most forward-looking browser architecture out there","quote_url":"https://news.ycombinator.com/item?id=18421935","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('43XaZEn2aLc','hn',5.0,'{"vid":"43XaZEn2aLc","title":"On the Expressive Power of Programming Languages by Shriram Krishnamurthi [PWLConf 2019]","channel":"PapersWeLove","summary":"Shriram Krishnamurthi''s PWLConf 2019 talk on the formal notion of expressive power of programming languages, based on Felleisen''s paper. It explains how to tell when a feature adds power by whether emulating it requires global rewriting.","why":"Recommended as the approachable way into a precise definition of language expressiveness for language-design arguments.","type":"talk","level":"advanced","score":5.0,"topics":["Languages & compilers"],"recs":5,"years":[2020,2026],"quote":"Shriram Krishnamurthi''s talk from two years ago on this paper might be more approachable.","quote_url":"https://news.ycombinator.com/item?id=28308675","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9zinZmE3Ogk','hn',5.0,'{"vid":"9zinZmE3Ogk","title":"Raymond Hettinger, Keynote on Concurrency, PyBay 2017","channel":"SF Python","summary":"Raymond Hettinger''s PyBay 2017 keynote on concurrency in Python. It covers threads, processes, asyncio, locks and the GIL, with live shell-based examples.","why":"Recommended as a clear, charismatic starting point for understanding Python concurrency and the GIL.","type":"talk","level":"intermediate","score":5.0,"topics":["Python","Languages & compilers","Software design & craft"],"recs":4,"years":[2018,2023],"quote":"the best learning material for me on this was this lecture","quote_url":"https://news.ycombinator.com/item?id=36917555","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Bv_5Zv5c-Ts','hn',5.0,'{"vid":"Bv_5Zv5c-Ts","title":"JavaScript: Understanding the Weird Parts - The First 3.5 Hours","channel":"Tony Alicea","summary":"The first 3.5 hours of Tony Alicea''s Udemy course on JavaScript''s inner workings, covering topics such as first-class functions, closures, prototypal inheritance and how the language behaves under the hood.","why":"HN commenters call it one of the best JavaScript courses: rigorous and deep but not boring, and freely available.","type":"course","level":"intermediate","score":5.0,"topics":["Languages & compilers","Web"],"recs":3,"years":[2016,2019],"quote":"they are the holy grails of online education for me. Rigorous -- but not boring or too long.","quote_url":"https://news.ycombinator.com/item?id=12593810","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('FtieBc3KptU','hn',5.0,'{"vid":"FtieBc3KptU","title":"Emacs For Writers","channel":"thoughtbot","summary":"Science writer Jay Dixit explains how he uses Emacs as a non-programmer to write, edit and research more productively. He shows his plain-text writing workflow and what led him from tools like Scrivener to Emacs.","why":"Recommended as a favorite talk showing Emacs as a writing environment rather than just a programmer''s editor.","type":"talk","level":"intro","score":5.0,"topics":["Software design & craft"],"recs":3,"years":[2016,2024],"quote":"My favourite talk on this topic is \"Emacs for writers","quote_url":"https://news.ycombinator.com/item?id=25849316","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HB5TrK7A4pI','hn',5.0,'{"vid":"HB5TrK7A4pI","title":"\"We Really Don''t Know How to Compute!\" - Gerald Sussman (2011)","channel":"Strange Loop Conference","summary":"Gerald Sussman''s 2011 Strange Loop keynote argues we still do not know how to compute, comparing biological systems with how we program machines. It touches on propagators, constraint programming and robustness.","why":"HN commenters recommend it as a mind-expanding talk on rethinking programming, and cite it in threads on propagators, constraints and brittleness.","type":"talk","level":"advanced","score":5.0,"topics":["Languages & compilers"],"recs":5,"years":[2022,2026],"quote":"it made me question my views on what I think programming is","quote_url":"https://news.ycombinator.com/item?id=37582217","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HPuvDm8IC-4','hn',5.0,'{"vid":"HPuvDm8IC-4","title":"Golang UK Conf. 2016 - Liz Rice - What is a container, really? Let''s write one in Go from scratch","channel":"GopherCon UK","summary":"Liz Rice builds a container from scratch in about 100 lines of Go, showing that a container is not a lightweight VM but a set of Linux kernel features and flags.","why":"HN recommends it as an accessible way to remove the magic from Docker and understand how containers work.","type":"talk","level":"intermediate","score":5.0,"topics":["Systems & performance"],"recs":3,"years":[2016,2019],"quote":"have given talks on how to make containers from scratch that are very illuminating","quote_url":"https://news.ycombinator.com/item?id=20060765","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('I7IdS-PbEgI','hn',5.0,'{"vid":"I7IdS-PbEgI","title":"React.js Conf 2015 - Immutable Data and React","channel":"Meta Developers","summary":"Lee Byron of Facebook explains how persistent immutable data structures work and how to use them in React apps with Immutable.js. He covers memoization benefits and avoiding coupling through shared mutable state.","why":"HN points to it as a clear explanation of immutable data structures such as tries, and of the case for immutability with React and Flux.","type":"talk","level":"intermediate","score":5.0,"topics":["DSA","Web","Languages & compilers"],"recs":5,"years":[2015,2022],"quote":"there''s a great conference talk on this topic by Lee Byron from Facebook","quote_url":"https://news.ycombinator.com/item?id=14276001","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IroPQ150F6c','hn',5.0,'{"vid":"IroPQ150F6c","title":"Andrew Kelley: A Practical Guide to Applying Data Oriented Design (DoD)","channel":"ChimiChanga","summary":"Andrew Kelley, creator of Zig, presents practical data-oriented design techniques for shrinking memory footprint and making programs cache friendly. He ends with a case study of how these ideas sped up the Zig compiler.","why":"HN cites it as one of the best talks on data-oriented design, applying struct-of-arrays and compact data layouts to a real compiler.","type":"talk","level":"intermediate","score":5.0,"topics":["Systems & performance","Software design & craft"],"recs":4,"years":[2024,2026],"quote":"A good introduction to SoA (for anyone curious) are the two most famous Data-Oriented Design talks","quote_url":"https://news.ycombinator.com/item?id=49012929","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JHGkaShoyNs','hn',5.0,'{"vid":"JHGkaShoyNs","title":"Greg Young - CQRS and Event Sourcing - Code on the Beach 2014","channel":"Code on the Beach","summary":"Greg Young''s Code on the Beach 2014 talk on CQRS and event sourcing. He argues mature domains are built on facts that occurred rather than current state, and covers the business and technical benefits.","why":"HN developers recommend it as the talk that changed how they model systems, and as a clear intro to event sourcing''s motivations.","type":"talk","level":"intermediate","score":5.0,"topics":["Software design & craft","Databases & distributed"],"recs":4,"years":[2016,2022],"quote":"forever changed how I think about modeling systems, preserving history","quote_url":"https://news.ycombinator.com/item?id=31783857","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Jib2AmRb_rk','hn',5.0,'{"vid":"Jib2AmRb_rk","title":"SQLite: The Database at the Edge of the Network with Dr. Richard Hipp","channel":"Method","summary":"SQLite creator Richard Hipp gives a history of SQLite and explains where it shines as a database at the edge of the network with no DBA. He covers long-term support, testing and how it is used in products.","why":"HN recommends it as an enthusiastic, funny talk straight from the creator, and cites it for facts like the name''s pronunciation and Airbus support.","type":"talk","level":"intermediate","score":5.0,"topics":["Databases & distributed"],"recs":4,"years":[2017,2024],"quote":"I highly recommend to watch it, if only to get a sense of the smart and funny energy that Dr Richard Hipp puts off!","quote_url":"https://news.ycombinator.com/item?id=28076075","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('L5pUA3LsEaw','hn',5.0,'{"vid":"L5pUA3LsEaw","title":"Why Not Just: Think of AGI Like a Corporation?","channel":"Robert Miles AI Safety ","summary":"Robert Miles asks whether corporations can be thought of as artificial general superintelligences and how far the analogy holds. He argues the differences, such as being limited by employees'' capabilities, matter for AI safety.","why":"HN points to it as an accessible rebuttal to the claim that AI risk is just corporate risk.","type":"explainer","level":"general","score":5.0,"topics":["AI & ML"],"recs":5,"years":[2020,2023],"quote":"He presents the material in a very interesting and accessible way.","quote_url":"https://news.ycombinator.com/item?id=23663365","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('LEZv-kQUSi4','hn',5.0,'{"vid":"LEZv-kQUSi4","title":"Stuart Halloway - Narcissistic Design","channel":"Reaktor","summary":"Stuart Halloway''s satirical talk describes how to protect yourself from industry change by spreading complexity through systems while following idiomatic practice. It uses this inversion to catalog software design anti-patterns.","why":"HN commenters love it as a witty and insightful tour of design anti-patterns, applicable to DSLs, OOP and API design.","type":"talk","level":"intermediate","score":5.0,"topics":["Software design & craft","Languages & compilers"],"recs":4,"years":[2018,2021],"quote":"a great talk by Stuart Halloway called Narcissistic Design.","quote_url":"https://news.ycombinator.com/item?id=18528303","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NWSZ4c9yqW8','hn',5.0,'{"vid":"NWSZ4c9yqW8","title":"Simon Peyton Jones: Data Parallel Haskell","channel":"nuACM","summary":"Simon Peyton Jones explains nested data parallelism and Data Parallel Haskell, an approach to exploiting multicore and distributed hardware while keeping a simple single-control-flow programming model.","why":"Recommended as a fascinating look at easy parallelism abstractions, though other commenters note the approach never beat sequential C by much.","type":"talk","level":"advanced","score":5.0,"topics":["Languages & compilers"],"recs":5,"years":[2010,2017],"quote":"a promising language abstraction to do hard things with parallelism relatively easily","quote_url":"https://news.ycombinator.com/item?id=2477051","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QZy4Yml3LTY','hn',5.0,'{"vid":"QZy4Yml3LTY","title":"John Wiegley: Putting Lenses to Work","channel":"Bay Area Haskell","summary":"John Wiegley''s BayHac 2017 talk walks through Haskell lenses by example, showing many practical uses beyond simple record access. It is aimed at people who want to become productive with the lens library.","why":"HN recommends it as the fastest way to learn lenses by example, with far-out examples later on.","type":"talk","level":"intermediate","score":5.0,"topics":["Languages & compilers"],"recs":4,"years":[2020,2024],"quote":"you can learn enough lens to be productive in 1 hours with this talk without reading docs at all","quote_url":"https://news.ycombinator.com/item?id=23624492","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XRYN2xt11Ek','hn',5.0,'{"vid":"XRYN2xt11Ek","title":"Netflix JavaScript Talks - Async JavaScript with Reactive Extensions","channel":"Matt Marenghi","summary":"A Netflix JavaScript talk on using Reactive Extensions (Rx) for asynchronous UI code. It covers Observables, composing events such as drag and drop, and sequencing Ajax requests.","why":"Recommended as a clear, mind-changing introduction to observables and async programming from engineers using Rx in production.","type":"talk","level":"intermediate","score":5.0,"topics":["Web","Languages & compilers"],"recs":5,"years":[2014,2016],"quote":"have a look at this presentation about Observables at Netflix as it''s quite mind changing","quote_url":"https://news.ycombinator.com/item?id=11824114","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XpDsk374LDE','hn',5.0,'{"vid":"XpDsk374LDE","title":"Elm Europe 2017 - Evan Czaplicki - The life of a file","channel":"Elm Europe","summary":"Elm creator Evan Czaplicki''s talk on how a file grows and when to split code up. He argues for keeping code in one file until it hurts and warns against premature extraction.","why":"Recommended as the argument for code colocation and delaying abstraction.","type":"talk","level":"intermediate","score":5.0,"topics":["Software design & craft","Languages & compilers"],"recs":4,"years":[2019,2025],"quote":"Just stick everything in the same file until it actually hurts. This presentation[0] gets it right.","quote_url":"https://news.ycombinator.com/item?id=30194512","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Z1qyvQsjK5Y','hn',5.0,'{"vid":"Z1qyvQsjK5Y","title":"Immediate-Mode Graphical User Interfaces - 2005","channel":"Casey Muratori","summary":"Casey Muratori''s 2005 video introducing immediate-mode GUIs as an alternative to retained widget toolkits. He explains the motivation and shows minimal-state button logic.","why":"Seen as the origin of the IMGUI idea that inspired Dear ImGui, recommended to anyone curious about immediate-mode UI design.","type":"lecture","level":"intermediate","score":5.0,"topics":["Software design & craft"],"recs":5,"years":[2017,2024],"quote":"Check out this lecture/demo from nearly 20 years ago","quote_url":"https://news.ycombinator.com/item?id=39008047","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cKxRvEZd3Mw','hn',5.0,'{"vid":"cKxRvEZd3Mw","title":"Hello World - Machine Learning Recipes #1","channel":"Google for Developers","summary":"The first episode of Google''s Machine Learning Recipes series. It introduces machine learning and builds a first supervised-learning classifier in about six lines of Python using scikit-learn.","why":"HN commenters recommend it as an approachable first step into machine learning for programmers, with an apples-vs-oranges classifier.","type":"tutorial","level":"intro","score":5.0,"topics":["Python","AI & ML","Languages & compilers"],"recs":6,"years":[2016,2017],"quote":"Very approachable! The first lesson is a classifier to separate apples and oranges.","quote_url":"https://news.ycombinator.com/item?id=12714957","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('eMlx5fFNoYc','hn',5.0,'{"vid":"eMlx5fFNoYc","title":"Attention in transformers, step-by-step | Deep Learning Chapter 6","channel":"3Blue1Brown","summary":"3Blue1Brown''s visual walkthrough of the attention mechanism inside transformers, covering self-attention, multiple heads and cross-attention. It is chapter 6 of his deep learning series.","why":"HN treats it as the go-to visual explanation of attention, recommended to people who find text-based transformer explainers hard to follow.","type":"explainer","level":"intro","score":5.0,"topics":["AI & ML","LLMs"],"recs":5,"years":[2024,2026],"quote":"what bade me finally understand the transformer architecture [0] and attention [1], are 3Blue1Brown''s videos.","quote_url":"https://news.ycombinator.com/item?id=40873442","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hEx5DNLWGgA','hn',5.0,'{"vid":"hEx5DNLWGgA","title":"CppCon 2015: Herb Sutter \"Writing Good C++14... By Default\"","channel":"CppCon","summary":"Herb Sutter''s CppCon 2015 plenary on writing safe, modern C++ by default using the C++ Core Guidelines. It includes a demo of lifetime-checking static analysis tooling.","why":"HN cites it in C++ versus Rust safety debates for its lifetime profile demo, and recommends it as a modern C++ talk.","type":"talk","level":"intermediate","score":5.0,"topics":["Systems & performance","Languages & compilers"],"recs":4,"years":[2015,2018],"quote":"Take a look at Herb Sutter''s CppCon talk this year","quote_url":"https://news.ycombinator.com/item?id=10289585","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('r9eQth4Q5jg','hn',5.0,'{"vid":"r9eQth4Q5jg","title":"Twenty Minutes of Reasons to Use the RemedyBG Debugger","channel":"Molly Rocket","summary":"Casey Muratori gives a fast tour of the RemedyBG debugger for Windows, which he uses daily. He shows its speed and features, especially the watch window.","why":"HN points to it as a demonstration of what fast, well-built developer tooling looks like and of why a debugger beats print statements.","type":"demo","level":"intermediate","score":5.0,"topics":["Software design & craft"],"recs":4,"years":[2022,2024],"quote":"Here''s Casey Muratori demonstrating all the way in which RemedyBG rocks.","quote_url":"https://news.ycombinator.com/item?id=31467882","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rzQEIRRJ2T0','hn',5.0,'{"vid":"rzQEIRRJ2T0","title":"Emacs Rocks! Episode 17: Magit","channel":"emacsrocks","summary":"A three-minute Emacs Rocks screencast demonstrating Magit, the Git interface inside Emacs, including staging and other everyday operations.","why":"HN users share it as the quick demo that shows what Magit can do, for people unfamiliar with it.","type":"demo","level":"intro","score":5.0,"topics":["Software design & craft"],"recs":4,"years":[2017,2020],"quote":"I always share this demo with people to show off just a tiny portion of what it''s capable of doing","quote_url":"https://news.ycombinator.com/item?id=23107920","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('v7Mt0GYHU9A','hn',5.0,'{"vid":"v7Mt0GYHU9A","title":"Design Patterns vs  Anti pattern in APL by Aaron W Hsu at FnConf17","channel":"ConfEngine","summary":"Aaron Hsu discusses design patterns and anti-patterns in APL and why the language is productive despite its write-only reputation. He argues that idioms matter more than libraries in array languages.","why":"HN recommends it as a terrific talk on APL readability and on the idea of idioms over libraries.","type":"talk","level":"intermediate","score":5.0,"topics":["Languages & compilers","Software design & craft"],"recs":4,"years":[2018,2022],"quote":"On the readability of APL (terrific video)","quote_url":"https://news.ycombinator.com/item?id=19610929","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2JB1_e5wZmU','hn',4.5,'{"vid":"2JB1_e5wZmU","title":"Domain Modeling Made Functional - Scott Wlaschin - KanDDDinsky 2019","channel":"KanDDDinsky","summary":"Scott Wlaschin shows how statically typed functional languages, using F# examples, can model a business domain so that invalid states cannot be represented. The type system acts almost like an instant unit test at compile time.","why":"HN treats it as the canonical, approachable example of domain-driven design with types and ''make invalid states unrepresentable''.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2020,2026],"quote":"this talk opened my eyes to the power of f# philosophy and type system","quote_url":"https://news.ycombinator.com/item?id=24285701","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4bZvq3nodf4','hn',4.5,'{"vid":"4bZvq3nodf4","title":"Progressive Performance (Chrome Dev Summit 2016)","channel":"Chrome for Developers","summary":"Alex Russell''s Chrome Dev Summit 2016 talk on building web experiences that work on slow, flaky networks and low-power devices. It argues developers should focus on the performance of real-world mobile hardware rather than desktop machines.","why":"HN commenters cite it as the clearest case for why mobile devices are slow and why code-splitting and progressive web apps are needed.","type":"talk","level":"intermediate","score":4.5,"topics":["Web","Systems & performance"],"recs":4,"years":[2016,2018],"quote":"Take a look at this talk on why mobile devices are so much slower than desktop devices","quote_url":"https://news.ycombinator.com/item?id=13248379","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5AqbCQuK0gM','hn',4.5,'{"vid":"5AqbCQuK0gM","title":"Anders Hejlsberg and Lars Bak: TypeScript, JavaScript, and Dart","channel":"DartlangTV","summary":"A Channel 9 conversation recorded at GOTO 2012 between Anders Hejlsberg (TypeScript) and Lars Bak (Dart). They discuss the two languages and different approaches to making JavaScript development safer, including runtime type checking.","why":"HN points to it as a rare side-by-side of the TypeScript and Dart designers, often to show how the two approaches to improving JavaScript differed.","type":"interview","level":"intermediate","score":4.5,"topics":["Languages & compilers","Web"],"recs":4,"years":[2014,2024],"quote":"Debate (almost 10 years ago) TypeScript vs. Dart about the best way to improve JavaScript","quote_url":"https://news.ycombinator.com/item?id=33049759","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5fG_lyNuEAw','hn',4.5,'{"vid":"5fG_lyNuEAw","title":"Jordan Walke - React to the Future","channel":"ReasonConf","summary":"Jordan Walke, creator of React, talks at ReasonConf 2019 about the ideas behind ReasonML and how it extends React''s programming model with OCaml. He also discusses why familiar syntax matters.","why":"HN recommends it as the best introduction to Reason''s motivations, straight from React''s creator.","type":"talk","level":"intermediate","score":4.5,"topics":["Web","Languages & compilers"],"recs":4,"years":[2019,2022],"quote":"I''d highly recommend Jordan Walke''s (creator of React) talk on the ideas behind ReasonML","quote_url":"https://news.ycombinator.com/item?id=23629083","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7g1Acy5eGbE','hn',4.5,'{"vid":"7g1Acy5eGbE","title":"\"Performance (Really) Matters\" with Emery Berger","channel":"Association for Computing Machinery (ACM)","summary":"Emery Berger argues that performance is hard to measure and deliver on modern systems, showing how code layout and link order can swamp optimization effects. He presents tools that evaluate performance more reliably.","why":"HN points to it whenever benchmarking pitfalls and layout effects come up, as an eye-opening talk on how unreliable naive measurements are.","type":"talk","level":"advanced","score":4.5,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2022,2026],"quote":"I highly recommend it. It''s mind blowing, but also terrifying","quote_url":"https://news.ycombinator.com/item?id=39011884","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('B5NULPSiOGw','hn',4.5,'{"vid":"B5NULPSiOGw","title":"CRDTs and the Quest for Distributed Consistency","channel":"InfoQ","summary":"Martin Kleppmann''s QCon London 2018 talk on keeping data consistent in distributed systems without a central leader. It surveys CRDT algorithms for syncing devices and collaborative editing over peer-to-peer networks.","why":"Strongly recommended as a clear, accessible survey of the CRDT landscape.","type":"talk","level":"intermediate","score":4.5,"topics":["Databases & distributed","DSA"],"recs":3,"years":[2018,2020],"quote":"I also highly recommend the talk","quote_url":"https://news.ycombinator.com/item?id=20183847","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Cym4TZwTCNU','hn',4.5,'{"vid":"Cym4TZwTCNU","title":"Rich Hickey: Deconstructing the Database","channel":"InfoQ","summary":"Rich Hickey, creator of Clojure and designer of Datomic, gives a JaxConf 2012 talk that takes apart traditional database architecture. He presents a different way to think about databases and explains the reasoning behind Datomic''s fact-based design.","why":"HN points people to it as the clearest account of why Datomic is designed the way it is and of the problems with conventional database architecture.","type":"talk","level":"intermediate","score":4.5,"topics":["Databases & distributed","Languages & compilers"],"recs":4,"years":[2012,2020],"quote":"Rich Hickey''s talk on the design of Datomic is also something every programmer should see at least once","quote_url":"https://news.ycombinator.com/item?id=22807290","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DEcwa68f-jY','hn',4.5,'{"vid":"DEcwa68f-jY","title":"dotJS 2019 - James Long - CRDTs for Mortals","channel":"dotconferences","summary":"James Long''s dotJS 2019 talk on how CRDTs enable local-first apps and how simple they can be to implement. He shows how to use them to build robust offline-capable frontends.","why":"Recommended as an approachable introduction to CRDTs and the local-first idea behind apps like Actual.","type":"talk","level":"intermediate","score":4.5,"topics":["Web","Databases & distributed"],"recs":3,"years":[2020,2023],"quote":"the same one who made a great talk on using CRDTs called CRDTs for Mortals","quote_url":"https://news.ycombinator.com/item?id=38055185","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DRq2NgeFcO0','hn',4.5,'{"vid":"DRq2NgeFcO0","title":"Edwin Brady - Idris 2 - Type-driven Development of Idris","channel":"Curry On!","summary":"Edwin Brady, creator of Idris, presents Idris 2 and demonstrates type-driven development, where the compiler assists by filling holes and suggesting implementations from types.","why":"Recommended as the best demo of interactive, compiler-assisted dependently typed programming in action.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers"],"recs":4,"years":[2019,2023],"quote":"Watch Edwin Brady''s demo of Idris 2 [2] to see this form of interactive development in action.","quote_url":"https://news.ycombinator.com/item?id=20714998","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DsZdfnlh_d0','hn',4.5,'{"vid":"DsZdfnlh_d0","title":"Depth-first search in APL","channel":"Dyalog","summary":"John Scholes builds a depth-first tree-search operator step by step in a Dyalog APL session. It covers higher-order functions and runs the search on the N-Queens problem.","why":"HN commenters call it a beautiful, brilliant demonstration of APL''s expressiveness and a model of clear narration.","type":"tutorial","level":"intermediate","score":4.5,"topics":["Languages & compilers","DSA"],"recs":2,"years":[2019,2021],"quote":null,"quote_url":null,"source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('F3ntGDm6hOs','hn',4.5,'{"vid":"F3ntGDm6hOs","title":"Intro to C on Windows - Day 1","channel":"Molly Rocket","summary":"Day 1 of Handmade Hero''s introduction to C on Windows, covering setting up Visual Studio, creating a Win32 project, the WinMain entry point and writing a first function. It is the starting point for Casey Muratori''s from-scratch game series.","why":"HN recommends it as an approachable way into C and low-level programming that gets to something visible quickly.","type":"tutorial","level":"intro","score":4.5,"topics":["Systems & performance"],"recs":4,"years":[2014,2022],"quote":"I think Handmade Hero''s[0] intro to C is good","quote_url":"https://news.ycombinator.com/item?id=22027182","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('FihU5JxmnBg','hn',4.5,'{"vid":"FihU5JxmnBg","title":"Debugging with the Scientific Method - Stuart Halloway","channel":"ClojureTV","summary":"Stuart Halloway of Cognitect argues for debugging with the scientific method: form hypotheses, try to falsify them, and write everything down. The talk is given to the Clojure community but applies to any language.","why":"HN recommends it as a talk that changed how people debug, worth rewatching periodically.","type":"talk","level":"intermediate","score":4.5,"topics":["Software design & craft","Languages & compilers"],"recs":4,"years":[2015,2023],"quote":"changed how I debug problems. I try to watch it once every year or two.","quote_url":"https://news.ycombinator.com/item?id=32737058","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Jes3bD6P0To','hn',4.5,'{"vid":"Jes3bD6P0To","title":"\"Tree-sitter - a new parsing system for programming tools\" by Max Brunsfeld","channel":"Strange Loop Conference","summary":"Max Brunsfeld introduces Tree-sitter, a parsing system for developer tools that offers incremental parsing and robust error recovery through a uniform C API. The talk explains the design, based on LR extended to GLR parsing.","why":"HN points to it as the best explanation of tree-sitter''s design choices and as an accessible introduction to parser generators.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers","Software design & craft"],"recs":4,"years":[2018,2024],"quote":"Highly recommend Max Brunsfield''s strange loop talk if you want to learn more about the design choices behind tree-sitter","quote_url":"https://news.ycombinator.com/item?id=39780995","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JfmTagWcqoE','hn',4.5,'{"vid":"JfmTagWcqoE","title":"CppCon 2016: Herb Sutter “Leak-Freedom in C++... By Default.”","channel":"CppCon","summary":"Herb Sutter''s CppCon 2016 talk on lifetime safety in C++, aiming for code free of leaks and dangling pointers by default. It covers smart pointers, ownership, reference counting pitfalls and deferred reclamation resembling garbage collection.","why":"HN cites it in memory management debates for its treatment of reference counting problems, destructor stack overflows and deferred pointers.","type":"talk","level":"advanced","score":4.5,"topics":["Systems & performance"],"recs":2,"years":[2016,2025],"quote":"Check all of Herb Sutter''s CppCon videos from 2015-2016, especially this one","quote_url":"https://news.ycombinator.com/item?id=12594821","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KTHOwgpMIiU','hn',4.5,'{"vid":"KTHOwgpMIiU","title":"Liberating Distributed Consensus - Heidi Howard","channel":"Reactive Summit","summary":"Heidi Howard''s Reactive Summit 2018 talk on generalizing Paxos by weakening its original requirements. She shows Paxos is one point on a broad spectrum of consensus approaches.","why":"HN recommends it as an illuminating, approachable explanation of distributed consensus.","type":"talk","level":"advanced","score":4.5,"topics":["Databases & distributed"],"recs":4,"years":[2019,2020],"quote":"Heidi Howard is incredible and her work on distributed consensus is illuminating.","quote_url":"https://news.ycombinator.com/item?id=22999677","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KTJs-0EInW8','hn',4.5,'{"vid":"KTJs-0EInW8","title":"Stanford Seminar - Google''s Steve Yegge on GROK","channel":"Stanford Online","summary":"Steve Yegge''s Stanford seminar on GROK, Google''s internal large-scale, cross-language source code analysis system. It covers how the system helps with code search and understanding across Google''s huge codebase.","why":"HN refers to it as the main public description of Google''s internal code analysis tooling, and as a precursor of ideas like LSP.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2013,2024],"quote":"this talk by Steve Yegge was both entertaining and informative","quote_url":"https://news.ycombinator.com/item?id=5512202","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('M3BM9TB-8yA','hn',4.5,'{"vid":"M3BM9TB-8yA","title":"10 Things I Regret About Node.js - Ryan Dahl - JSConf EU","channel":"JSConf","summary":"Node.js creator Ryan Dahl discusses ten design mistakes he made in Node, including package.json, npm, and module resolution. The talk sets out the motivations behind his later project, Deno.","why":"HN treats it as the classic talk on why Deno exists and on lessons from design mistakes in a widely used platform.","type":"talk","level":"intermediate","score":4.5,"topics":["Web","Software design & craft"],"recs":6,"years":[2018,2025],"quote":"Ryan Dahl''s great talk on design mistakes he made with node.js is something I think about all the time","quote_url":"https://news.ycombinator.com/item?id=34468836","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('MdmQUlD7P40','hn',4.5,'{"vid":"MdmQUlD7P40","title":"Matt Might - Winning the War on Error Solving the Halting Problem and Curing Cancer","channel":"Curry On!","summary":"Matt Might''s Curry On talk on ending errors in code, both software and the human genome. He covers conservative approximation of the halting problem via static analysis and a computational approach to precision medicine.","why":"Recommended as a jaw-dropping, must-see talk that gives an amazing intro to static analysis alongside Might''s personal story.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers","Math & theory"],"recs":3,"years":[2017,2019],"quote":"If you haven''t seen it, Might''s talk \"Winning the War on Error: Solving the Halting Problem and Curing Cancer\" is amazing, a must-see.","quote_url":"https://news.ycombinator.com/item?id=19277708","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Nrp_LZ-XGsY','hn',4.5,'{"vid":"Nrp_LZ-XGsY","title":"The Functional Programmer''s Toolkit - Scott Wlaschin","channel":"NDC Conferences","summary":"Scott Wlaschin demystifies functional programming terms like monads, monoids, functors and catamorphisms by showing how they fit into a small toolkit. He applies them to problems such as missing data, list handling, and functional dependency injection.","why":"HN recommends it as the best beginner-friendly introduction to monoids, monads and other FP vocabulary.","type":"talk","level":"intro","score":4.5,"topics":["Languages & compilers","Software design & craft"],"recs":4,"years":[2019,2021],"quote":"This was by far the best introduction to monoid, monads and few other functional programming terms.","quote_url":"https://news.ycombinator.com/item?id=25610624","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ObhK8lUfIlc','hn',4.5,'{"vid":"ObhK8lUfIlc","title":"GDC 2018: John McDonald (Valve) - Using Deep Learning to Combat Cheating in CSGO","channel":"max4warn","summary":"A GDC 2018 talk by Valve''s John McDonald on VACNet, a deep learning system that analyzes CS:GO gameplay to detect cheaters. It covers how the model is trained on human-reviewed Overwatch cases and how its output feeds human moderation.","why":"HN points to it as the definitive example of server-side, behavioral, non-invasive anti-cheat using machine learning, often as a counterpoint to kernel-level anti-cheat.","type":"talk","level":"intermediate","score":4.5,"topics":["AI & ML"],"recs":5,"years":[2018,2026],"quote":"The actual presentation is worth listening to if you have the time.","quote_url":"https://news.ycombinator.com/item?id=21950646","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Obt-vMVdM8s','hn',4.5,'{"vid":"Obt-vMVdM8s","title":"Understanding the Python GIL","channel":"David Beazley","summary":"David Beazley''s PyCon 2010 talk explains how the Python Global Interpreter Lock works and shows experiments where multithreaded code runs slower, even on more cores, due to lock contention and context-switching overhead.","why":"The canonical recommendation for understanding the GIL, praised both for its clarity and for how well it explains a deep technical topic.","type":"talk","level":"intermediate","score":4.5,"topics":["Python","Languages & compilers","Systems & performance"],"recs":4,"years":[2013,2023],"quote":"My favorite example is Beazley''s GIL talk","quote_url":"https://news.ycombinator.com/item?id=7092622","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('S27pHKBEp30','hn',4.5,'{"vid":"S27pHKBEp30","title":"LSTM is dead. Long Live Transformers!","channel":"Seattle Applied Deep Learning","summary":"Leo Dirac explains how transformer models have replaced LSTMs in NLP. He gives background from bag of words through RNNs and LSTMs, then a technical deep dive into multi-headed self-attention and positional encoding, with sample code.","why":"Recommended as a clear explanation of why RNNs fall short and how transformers solve it.","type":"lecture","level":"intermediate","score":4.5,"topics":["AI & ML","LLMs"],"recs":4,"years":[2020,2023],"quote":"has gotten tons of compliments and keeps people watching year after year","quote_url":"https://news.ycombinator.com/item?id=35982590","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('X8jsijhllIA','hn',4.5,'{"vid":"X8jsijhllIA","title":"But what are Hamming codes? The origin of error correction","channel":"3Blue1Brown","summary":"3Blue1Brown''s discovery-oriented introduction to error correction codes, building up Hamming codes from the puzzle of locating a flipped bit. It explains the parity-check idea and why it is so efficient.","why":"HN recommends it as an invaluable, intuitive explanation of Hamming codes that pairs well with hardware-oriented treatments.","type":"explainer","level":"intro","score":4.5,"topics":["Software design & craft"],"recs":4,"years":[2020,2023],"quote":"I would strongly recommend anyone interested in the topic to check out any of these videos","quote_url":"https://news.ycombinator.com/item?id=33494568","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YbZ3zDzDnrw','hn',4.5,'{"vid":"YbZ3zDzDnrw","title":"Raft lecture (Raft user study)","channel":"Diego Ongaro","summary":"John Ousterhout lectures on the Raft consensus algorithm, made for the Raft user study comparing how students learn Raft and Paxos. It covers leader election and log repair.","why":"HN commenters recommend it as a clearer introduction to Raft than the paper and as part of a well-designed understandability study.","type":"lecture","level":"intermediate","score":4.5,"topics":["Databases & distributed"],"recs":4,"years":[2013,2025],"quote":"The 2 videos do an excellent job of explaining both the Paxos and Raft algorithms and the key differences between them.","quote_url":"https://news.ycombinator.com/item?id=8529187","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Z2DU0qLfPIY','hn',4.5,'{"vid":"Z2DU0qLfPIY","title":"ElixirConf 2018 - Keynote - Chris McCord","channel":"ElixirConf","summary":"Chris McCord''s ElixirConf 2018 keynote introduces Phoenix LiveView, which renders HTML on the server and updates the page over websockets. It includes a demo showing that latency is not the bottleneck one might expect.","why":"HN recommends it as the original LiveView announcement and demo, a compelling argument for server-side rendering as an alternative to JavaScript front ends.","type":"talk","level":"intermediate","score":4.5,"topics":["Languages & compilers","Web"],"recs":6,"years":[2018,2019],"quote":"you can''t ignore it, the coolest thing happening right now about server-side rendering","quote_url":"https://news.ycombinator.com/item?id=19466580","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bY2FlayomlE','hn',4.5,'{"vid":"bY2FlayomlE","title":"C++ Exceptions for Smaller Firmware - Khalil Estell - CppCon 2024","channel":"CppCon","summary":"Khalil Estell''s CppCon 2024 talk argues C++ exceptions can reduce binary size in firmware. He digs into how exceptions work and how to shrink their code footprint on embedded platforms.","why":"Pointed to as the in-depth talk on exception mechanics and code size for embedded C++.","type":"talk","level":"advanced","score":4.5,"topics":["Systems & performance"],"recs":5,"years":[2025,2026],"quote":"In particular, his 2019 presentation [2] describes different error handling techniques","quote_url":"https://news.ycombinator.com/item?id=45094428","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bx3KuE7UjGA','hn',4.5,'{"vid":"bx3KuE7UjGA","title":"MINIX 3: a Modular, Self-Healing POSIX-compatible Operating System","channel":"FOSDEM","summary":"Andrew Tanenbaum''s FOSDEM 2010 talk on MINIX 3, a microkernel OS built for high reliability and security. It shows how the system detects and recovers from device driver crashes, and addresses microkernel performance concerns.","why":"HN points to it as an accessible explanation of microkernel isolation and fault-tolerant design, and as Tanenbaum''s answer to performance objections.","type":"talk","level":"intermediate","score":4.5,"topics":["Systems & performance","Databases & distributed"],"recs":4,"years":[2013,2023],"quote":"it''s a very interesting but accessible talk for those interested in lower-level systems and fault-tolerant architectures.","quote_url":"https://news.ycombinator.com/item?id=5513993","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dpw9EHDh2bM','hn',4.5,'{"vid":"dpw9EHDh2bM","title":"React Today and Tomorrow and  90% Cleaner React With Hooks","channel":"React Conf","summary":"The first three talks from React Conf 2018, by Sophie Alpert, Dan Abramov and Ryan Florence. They introduce React Hooks and explain the problems with classes that hooks solve.","why":"It is the canonical introduction to hooks, given by the people who built them, and HN uses it to answer questions about why hooks exist.","type":"talk","level":"intermediate","score":4.5,"topics":["Web"],"recs":4,"years":[2019,2025],"quote":"It''s absolutely worth the watch, even if you''re somewhat familiar with hooks.","quote_url":"https://news.ycombinator.com/item?id=20929537","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ftcIcn8AmSY','hn',4.5,'{"vid":"ftcIcn8AmSY","title":"Four Solutions to a Trivial Problem - Guy Steele Jr.","channel":"Google TechTalks","summary":"Guy Steele presents a small geometric problem and compares four computational approaches: a classic sequential solution and three parallel-friendly ones. Each is illustrated pictorially and with working code, weighing total work against time to solution.","why":"HN points to it as a clear lesson that algebraic properties like associativity unlock parallelism, applicable in any language.","type":"talk","level":"intermediate","score":4.5,"topics":["DSA","Languages & compilers"],"recs":4,"years":[2017,2023],"quote":"watch Guy Steele''s talks [1][2][3] if you are interested in data parallelism!","quote_url":"https://news.ycombinator.com/item?id=24702053","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('iDulhoQ2pro','hn',4.5,'{"vid":"iDulhoQ2pro","title":"Attention Is All You Need","channel":"Yannic Kilcher","summary":"Yannic Kilcher walks through the Attention Is All You Need paper, which introduced the Transformer, a sequence model based solely on attention without recurrence or convolutions. He reviews the architecture and the paper''s translation results.","why":"HN recommends it as an accessible, clear walkthrough of the transformer paper for people with some AI background.","type":"explainer","level":"intermediate","score":4.5,"topics":["AI & ML","LLMs"],"recs":4,"years":[2020,2025],"quote":"The Yannic kilcher review is quite good.","quote_url":"https://news.ycombinator.com/item?id=35978097","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lG4VkPoG3ko','hn',4.5,'{"vid":"lG4VkPoG3ko","title":"The medical test paradox, and redesigning Bayes'' rule","channel":"3Blue1Brown","summary":"3Blue1Brown explains why positive results on accurate medical tests are often false positives, and reframes Bayes'' rule using likelihood ratios (Bayes factors) to update odds. It uses visual examples to make the reasoning intuitive.","why":"HN''s go-to link whenever Bayesian reasoning, base rates or imperfect tests come up.","type":"explainer","level":"intro","score":4.5,"topics":["Math for ML"],"recs":4,"years":[2020,2025],"quote":"is a brilliant introduction to the concept","quote_url":"https://news.ycombinator.com/item?id=25758943","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lJ3NC-R3gSI','hn',4.5,'{"vid":"lJ3NC-R3gSI","title":"Rust''s Journey to Async/Await","channel":"InfoQ","summary":"Steve Klabnik walks through the history of Rust and how its design evolved toward async/await, including the alternatives tried and dropped. He also discusses the difficulty of adding a major feature to a language.","why":"HN points to it to show how deliberately the Rust team arrived at async/await and why it was chosen over alternatives like green threads.","type":"talk","level":"intermediate","score":4.5,"topics":["Systems & performance","Languages & compilers"],"recs":5,"years":[2020,2026],"quote":"It will show you how meticulous the core team is and how long it took to arrive at this incredible, best in class design.","quote_url":"https://news.ycombinator.com/item?id=22843808","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lkgszkPnV8g','hn',4.5,'{"vid":"lkgszkPnV8g","title":"CppCon 2017: Louis Brandy “Curiously Recurring C++ Bugs at Facebook”","channel":"CppCon","summary":"Louis Brandy presents the most common and infamous recurring C++ bugs seen in Facebook''s huge codebase, including shared_ptr data races and operator[] pitfalls. He explains the surprising complexity behind seemingly simple code.","why":"HN recommends it as a must-watch catalogue of C++ footguns, often cited in debates about Rust and C++ safety.","type":"talk","level":"intermediate","score":4.5,"topics":["Systems & performance"],"recs":4,"years":[2020,2025],"quote":"is a great video that covers a lot of good stuff in particular this usability bug. It''s worth watching in its entirety.","quote_url":"https://news.ycombinator.com/item?id=22183456","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('modXC5IWTJI','hn',4.5,'{"vid":"modXC5IWTJI","title":"Building Software Systems At Google and Lessons Learned","channel":"Stanford","summary":"Jeff Dean of Google describes his experiences building Google''s systems and how its infrastructure evolved over time. The Stanford talk covers search, scaling tipping points and lessons from building large-scale software.","why":"HN recommends it as a classic look at systems engineering at Google, whose fundamentals have held up well despite its 2010 date.","type":"lecture","level":"intermediate","score":4.5,"topics":["Databases & distributed"],"recs":4,"years":[2012,2022],"quote":"It''s from 2010, but the fundamentals probably haven''t changed.","quote_url":"https://news.ycombinator.com/item?id=24482470","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oV9rvDllKEg','hn',4.5,'{"vid":"oV9rvDllKEg","title":"Concurrency is not Parallelism by Rob Pike","channel":"gnbitcom","summary":"Rob Pike''s Go talk distinguishing concurrency, the structuring of independent processes, from parallelism, their simultaneous execution. It uses Go channels and goroutines to illustrate.","why":"The standard link for explaining the concurrency versus parallelism distinction and the motivations behind Go''s concurrency model.","type":"talk","level":"intermediate","score":4.5,"topics":["Systems & performance","Software design & craft"],"recs":4,"years":[2021,2025],"quote":"here''s an excellent talk on the same subject by Rob Pike that I link all the time to people","quote_url":"https://news.ycombinator.com/item?id=41528051","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pqeJFYwnkjE','hn',4.5,'{"vid":"pqeJFYwnkjE","title":"Debt Metaphor","channel":"Ward Cunningham","summary":"Ward Cunningham explains the history and intent of the debt metaphor, which he coined while refactoring the WyCash product. He says debt means code reflecting an incomplete understanding of the problem, not sloppy programming.","why":"HN links it as the authoritative correction to common misuse of the term technical debt, straight from its originator.","type":"explainer","level":"general","score":4.5,"topics":["Software design & craft"],"recs":3,"years":[2009,2023],"quote":"For the best description of technical debt, you can''t do better than listen to the man who first coined the term.","quote_url":"https://news.ycombinator.com/item?id=10894626","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('skos4B5x7qE','hn',4.5,'{"vid":"skos4B5x7qE","title":"RustLatam 2019 - Without Boats: Zero-Cost Async IO","channel":"Rust Programming Language","summary":"Without Boats, a Rust language team member, explains the design of Rust''s async/await at RustLatam 2019. He covers the history and constraints behind zero-cost, allocation-free async state machines.","why":"Recommended during the await syntax debates for explaining the constraints that shaped Rust''s async design.","type":"talk","level":"intermediate","score":4.5,"topics":["Systems & performance","Languages & compilers"],"recs":5,"years":[2019,2020],"quote":"I really loved this talk by Without Boats","quote_url":"https://news.ycombinator.com/item?id=20031909","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zi0rHwfiX1Q','hn',4.5,'{"vid":"zi0rHwfiX1Q","title":"John Hughes - Testing the Hard Stuff and Staying Sane","channel":"ClojureTV","summary":"John Hughes, co-creator of QuickCheck, talks about property-based testing of hard systems. He shows production examples where it found very low-level bugs, including issues in the CAN bus standard.","why":"Recommended as the best introduction to property-based testing and cited for its examples of bugs found in the CAN standard.","type":"talk","level":"intermediate","score":4.5,"topics":["Software design & craft","Languages & compilers"],"recs":4,"years":[2016,2026],"quote":"John Hughes (not the filmmaker) gives a great talk about it","quote_url":"https://news.ycombinator.com/item?id=33325681","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-Ln-8QM8KhQ','hn',4.0,'{"vid":"-Ln-8QM8KhQ","title":"How is this Website so fast!?","channel":"Wes Bos","summary":"Wes Bos breaks down the techniques behind the McMaster-Carr website''s speed: server-rendered HTML, prefetching, CDN and service worker caching, preloading, critical CSS and fixed-size images. He also notes its old-school jQuery and YUI JavaScript.","why":"HN points to it as the clearest frontend explanation of why McMaster-Carr feels so snappy, often contrasted with slow modern UIs.","type":"explainer","level":"intermediate","score":4.0,"topics":["Web","Systems & performance"],"recs":4,"years":[2024,2025],"quote":"Here is Wes Bos taking a deeper dive into the intricacies of technologies used to accomplish this","quote_url":"https://news.ycombinator.com/item?id=43926439","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3GObi93tjZI','hn',4.0,'{"vid":"3GObi93tjZI","title":"DjangoCon 2022 | From React to htmx on a real-world SaaS product: we did it, and it''s awesome!","channel":"DjangoCon Europe","summary":"David Guillot describes how his team replaced a two-year-old React UI of their SaaS product with Django templates and htmx in a couple of months. The talk gives concrete indicators on code size, performance and team impact.","why":"HN commenters point to it as a real-world case study of moving from React to htmx, especially in threads on boring web development and HTML over the wire.","type":"talk","level":"intermediate","score":4.0,"topics":["Python","Web","Languages & compilers"],"recs":4,"years":[2022,2026],"quote":"This recent talk from Djangocon \"React to htmx on a real-world SaaS product\" might be of interest","quote_url":"https://news.ycombinator.com/item?id=33571508","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3ka4KY7TMTU','hn',4.0,'{"vid":"3ka4KY7TMTU","title":"Self and Self: Whys and Wherefores","channel":"Stanford","summary":"David Ungar of IBM Research reflects at Stanford on the Self language project and argues the real legacy of ideas is the people. He covers its history, philosophy, successes and failures.","why":"HN points to it as the best account of what Self made possible and what its team went on to do.","type":"talk","level":"intermediate","score":4.0,"topics":["Languages & compilers"],"recs":3,"years":[2010,2025],"quote":"explains the history, philosophy, successes, and failures of the Self project","quote_url":"https://news.ycombinator.com/item?id=31555457","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3uiEyEKji0M','hn',4.0,'{"vid":"3uiEyEKji0M","title":"Halide Talk","channel":"Andrew Adams","summary":"Andrew Adams, a Halide developer, presents the Halide language for image processing and tensor computation. The talk explains the separation of algorithm from schedule with illustrated examples of parallelism, locality and redundancy tradeoffs.","why":"Recommended as the clearest explanation of Halide''s ideas and of scheduling for performance.","type":"talk","level":"intermediate","score":4.0,"topics":["Languages & compilers","Systems & performance"],"recs":5,"years":[2014,2021],"quote":"The best way to understand it is probably to watch the video, which is relatively long but explains things clearly","quote_url":"https://news.ycombinator.com/item?id=7543596","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('449j7oKQVkc','hn',4.0,'{"vid":"449j7oKQVkc","title":"Ron Pressler - Pull Push: Please stop polluting our imperative languages with pure concepts-Curry On","channel":"Curry On!","summary":"Ron Pressler''s Curry On 2015 talk arguing that imperative languages should not be polluted with pure functional concepts like monads. He favors simple blocking code over non-blocking styles.","why":"Recommended as the case for blocking code and virtual threads over monads and async/await.","type":"talk","level":"advanced","score":4.0,"topics":["Languages & compilers"],"recs":3,"years":[2015,2024],"quote":"one of my recent favorite videos generally on this topic has been from Curry On conference","quote_url":"https://news.ycombinator.com/item?id=10541575","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4RSht_aV7AU','hn',4.0,'{"vid":"4RSht_aV7AU","title":"Keynote: Begin...End?","channel":"David Beazley","summary":"David Beazley''s PyData Global 2021 keynote, an oral history of early scientific Python. He tells how Python ended up running on a Connection Machine supercomputer at Los Alamos.","why":"Cited in threads about Python''s rise as a first-hand, entertaining account of why it won in scientific computing.","type":"talk","level":"general","score":4.0,"topics":["Python","Languages & compilers"],"recs":3,"years":[2021,2024],"quote":"I recommend one of the recent videos by Dave Beazly","quote_url":"https://news.ycombinator.com/item?id=30814167","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('6AeWu1fZ7bY','hn',4.0,'{"vid":"6AeWu1fZ7bY","title":"Benno Rice: The Tragedy of systemd -- BSDCan 2018","channel":"BSDCan","summary":"Benno Rice''s BSDCan 2018 talk on why systemd exists and what it got right and wrong. It traces the history of Unix init and why Linux distributions adopted it, while asking what the BSDs should learn.","why":"HN recommends it as a balanced, eloquent take on the systemd debate that even skeptics find persuasive.","type":"talk","level":"intermediate","score":4.0,"topics":["Systems & performance"],"recs":4,"years":[2018,2024],"quote":"One of the better videos on this subject","quote_url":"https://news.ycombinator.com/item?id=19960363","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7HKbjYqqPPQ','hn',4.0,'{"vid":"7HKbjYqqPPQ","title":"2017 ACM PPoPP Keynote: It''s Time for a New Old Language","channel":"Guy Steele","summary":"Guy Steele''s PPoPP 2017 keynote surveying the history of computer science metanotation, including BNF, inference rules, and overline notation. He argues the field''s notations are inconsistent and fragmented.","why":"HN recommends it as an excellent talk on notation problems, useful when reading papers or designing a new metalanguage.","type":"talk","level":"intermediate","score":4.0,"topics":["Languages & compilers"],"recs":3,"years":[2018,2023],"quote":"an excellent talk by Guy Steele that goes over issue of notation and balkanization","quote_url":"https://news.ycombinator.com/item?id=24650353","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9-IWMbJXoLM','hn',4.0,'{"vid":"9-IWMbJXoLM","title":"\"What UNIX Cost Us\" - Benno Rice (LCA 2020)","channel":"linux.conf.au","summary":"Benno Rice''s linux.conf.au 2020 talk asks whether UNIX was the best design we could have had. He looks at what alternatives existed, what was gained and lost, and what could be re-learned, including the limits of treating everything as a file.","why":"Recommended as an insightful and entertaining critique of UNIX design choices such as file descriptors and ''everything is a file''.","type":"talk","level":"intermediate","score":4.0,"topics":["Systems & performance"],"recs":3,"years":[2022,2025],"quote":"Benno Rice is an insightful, energetic, witty, and just plain enjoyable tech speaker.","quote_url":"https://news.ycombinator.com/item?id=41175677","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('90NsjKvz9Ns','hn',4.0,'{"vid":"90NsjKvz9Ns","title":"Mark DiMarco: User Interface Algorithms [JSConf2014]","channel":"JSConf","summary":"A JSConf 2014 talk visually breaking down algorithms behind everyday UI patterns, such as dropdown menus that vanish when the mouse drifts and picking the nearest target to the cursor. It shows how these are implemented in JavaScript.","why":"HN links it whenever menu hover problems or nearest-to-pointer selection come up, and as proof algorithms matter in front-end work.","type":"talk","level":"intermediate","score":4.0,"topics":["DSA","Web"],"recs":4,"years":[2014,2018],"quote":"Algorithms do play an important role as you can see in this great presentation","quote_url":"https://news.ycombinator.com/item?id=9945491","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ARYP83yNAWk','hn',4.0,'{"vid":"ARYP83yNAWk","title":"De-fragmenting C++: Making Exceptions and RTTI More Affordable and Usable - Herb Sutter  CppCon 2019","channel":"CppCon","summary":"Herb Sutter''s CppCon 2019 talk on the split in the C++ community over exceptions and RTTI. He proposes making exceptions cheaper and more usable, including a zero-overhead, Result-like design.","why":"Pointed to whenever C++ exception overhead, bans on exceptions or error-handling alternatives come up.","type":"talk","level":"advanced","score":4.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2020,2025],"quote":"I can really recommend this talk","quote_url":"https://news.ycombinator.com/item?id=22304181","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ByNs9TG30E8','hn',4.0,'{"vid":"ByNs9TG30E8","title":"Om Next - David Nolen","channel":"ClojureTV","summary":"David Nolen presents Om Next, the redesign of the ClojureScript Om library, drawing on Relay, Netflix''s JSONGraph and Datomic. He covers the tradeoffs in handling the client-server boundary over immutable data.","why":"HN commenters recommend it as the lead ClojureScript developer''s own account of Om''s evolution, one-way data flow and single-state design.","type":"talk","level":"advanced","score":4.0,"topics":["Languages & compilers","Web"],"recs":3,"years":[2015,2015],"quote":"David Nolen does a great job talking about the trade offs and the evolution of everything in this talk","quote_url":"https://news.ycombinator.com/item?id=9996300","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Ilg3gGewQ5U','hn',4.0,'{"vid":"Ilg3gGewQ5U","title":"Backpropagation, intuitively | Deep Learning Chapter 3","channel":"3Blue1Brown","summary":"3Blue1Brown''s third deep learning chapter gives a visual, intuitive account of backpropagation and what happens to a neural network as it learns. A follow-up video covers the underlying calculus.","why":"Recommended as the most accessible introduction to backprop for people who struggle with the pure math.","type":"explainer","level":"intro","score":4.0,"topics":["AI & ML"],"recs":4,"years":[2017,2024],"quote":"I found the explainations by 3Brown1Blue to be very intuitive when it comes to neural networks","quote_url":"https://news.ycombinator.com/item?id=17409429","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('JRuNA2eK7w0','hn',4.0,'{"vid":"JRuNA2eK7w0","title":"Is AI Safety a Pascal''s Mugging?","channel":"Robert Miles AI Safety ","summary":"Robert Miles examines whether the case for AI safety is a Pascal''s mugging, a tiny probability of an enormous payoff. He argues it is not, because AI risk does not depend on vanishingly small probabilities.","why":"HN points to it as a reasoned rebuttal to the claim that AI risk is just Pascal''s wager.","type":"explainer","level":"intro","score":4.0,"topics":["AI & ML"],"recs":3,"years":[2019,2026],"quote":"the main point of the video is that kind of situation happens when the probability involved is vanishingly small","quote_url":"https://news.ycombinator.com/item?id=47068113","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Mz3JeYfBTcY','hn',4.0,'{"vid":"Mz3JeYfBTcY","title":"Emily Shea - \"Perl Out Loud\"","channel":"The Perl and Raku Conference - Greenville, SC 2026","summary":"Emily Shea, a Fastly engineer with repetitive strain injury, describes using voice dictation as her main way of programming. She covers homophones, custom vocabulary and building her own voice commands to write Perl.","why":"HN treats it as a phenomenal demonstration that voice-driven development is viable and as an eye-opener on accessibility-unfriendly coding habits.","type":"talk","level":"general","score":4.0,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2019,2022],"quote":"This video from the article is a phenomenal demonstration of dictation coding","quote_url":"https://news.ycombinator.com/item?id=20665235","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OMPfEXIlTVE','hn',4.0,'{"vid":"OMPfEXIlTVE","title":"RailsConf 2015 - Nothing is Something","channel":"Confreaks","summary":"Sandi Metz argues that hidden assumptions in code are missing concepts, and shows how to name and expose them so code is easier to understand and change. It covers null objects and messages in Ruby.","why":"HN recommends it as a funny, smart and well-constructed talk on abstraction, duplication and object-oriented design.","type":"talk","level":"intermediate","score":4.0,"topics":["Software design & craft","Languages & compilers"],"recs":3,"years":[2016,2024],"quote":"as a talk it is fantastic - funny, smart, well put together.","quote_url":"https://news.ycombinator.com/item?id=42191154","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OQ5jsbhAv_M','hn',4.0,'{"vid":"OQ5jsbhAv_M","title":"Lecture 19: Dynamic Programming I: Fibonacci, Shortest Paths","channel":"MIT OpenCourseWare","summary":"Erik Demaine''s MIT 6.006 lecture introducing dynamic programming through Fibonacci numbers and shortest paths. It covers memoization, subproblems and optimal substructure.","why":"Recommended as a clear introduction to dynamic programming from a well-regarded instructor.","type":"lecture","level":"intro","score":4.0,"topics":["DSA"],"recs":4,"years":[2016,2021],"quote":"Please watch this MIT intro","quote_url":"https://news.ycombinator.com/item?id=26934252","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PYylPRX6z4Q','hn',4.0,'{"vid":"PYylPRX6z4Q","title":"Training AI Without Writing A Reward Function, with Reward Modelling","channel":"Robert Miles AI Safety ","summary":"Robert Miles explains reward modelling, in which an AI learns what humans want from their preference comparisons instead of a hand-written reward function. He walks through the 2017 paper on deep reinforcement learning from human preferences.","why":"Seen as the clearest introduction to the idea behind RLHF, and also borrowed by commenters as a metaphor for human motivation.","type":"explainer","level":"intermediate","score":4.0,"topics":["AI & ML"],"recs":3,"years":[2019,2023],"quote":"I find this video by Rob Miles still the best presentation of the ingenious original 2017(!) paper","quote_url":"https://news.ycombinator.com/item?id=36862414","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Qi1Yry33TQE','hn',4.0,'{"vid":"Qi1Yry33TQE","title":"Ali Rahimi''s talk at NIPS(NIPS 2017 Test-of-time award presentation)","channel":"ObservantVids","summary":"Ali Rahimi''s NIPS 2017 Test-of-Time award talk, in which he argues that modern machine learning has become alchemy, working without being rigorously understood. He calls for more rigor and understanding in the field.","why":"HN points to it as the sharpest, most-quoted critique of deep learning practice, and cites it whenever ML reliability or understanding is debated.","type":"talk","level":"intermediate","score":4.0,"topics":["AI & ML"],"recs":3,"years":[2018,2025],"quote":"For a more cutting and insightful critique, watch Ali Rahimi''s short talk at NIPS 2017","quote_url":"https://news.ycombinator.com/item?id=16348678","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('R3xX37RGJKE','hn',4.0,'{"vid":"R3xX37RGJKE","title":"\"Data Driven UIs, Incrementally\" by Yaron Minsky","channel":"Strange Loop Conference","summary":"Yaron Minsky of Jane Street shows how the OCaml Incremental library lets trading UIs express data transformations that are easy to read and efficient on streaming data. It includes a live table demo.","why":"Recommended in incremental computation and reactive UI threads as the best conceptual overview of Incremental and incr_dom.","type":"talk","level":"advanced","score":4.0,"topics":["Languages & compilers","Software design & craft"],"recs":4,"years":[2018,2022],"quote":"Any discussion about incremental UI should include Yaron Minsky''s talk about Jane Street''s OCaml framework, incr_dom from 2016","quote_url":"https://news.ycombinator.com/item?id=21683385","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('VDfX44fZoMc','hn',4.0,'{"vid":"VDfX44fZoMc","title":"J B  Rainsberger   Integrated Tests Are A Scam HD","channel":"Christopher Cabanne","summary":"J. B. Rainsberger argues that large integrated tests are a scam: they are slow, fail opaquely, and give a false sense of coverage. He advocates focused collaboration and contract tests at boundaries instead.","why":"HN recommends it in testing-strategy debates as the classic case for fewer integration tests and more small, well-contracted unit tests.","type":"talk","level":"intermediate","score":4.0,"topics":["Software design & craft"],"recs":4,"years":[2017,2023],"quote":"JBRainsberger has an nice talk on them [1].","quote_url":"https://news.ycombinator.com/item?id=32733443","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('VeAdryYZ7ak','hn',4.0,'{"vid":"VeAdryYZ7ak","title":"Practical Common Lisp","channel":"Google TechTalks","summary":"Peter Seibel''s 2006 Google TechTalk on Practical Common Lisp, framed by the Sapir-Whorf hypothesis and Paul Graham''s Blub paradox. It shows Lisp features such as condition restarts and its generic-function object system.","why":"HN remembers it as the memorable explanation of restarts and multiple dispatch, referenced whenever those features come up.","type":"talk","level":"intermediate","score":4.0,"topics":["Languages & compilers"],"recs":3,"years":[2011,2025],"quote":"I will forever think of this talk by Peter Siebel","quote_url":"https://news.ycombinator.com/item?id=44149321","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZCuYPiUIONs','hn',4.0,'{"vid":"ZCuYPiUIONs","title":"Lin Clark - A Cartoon Intro to Fiber - React Conf 2017","channel":"Meta Developers","summary":"Lin Clark gives an illustrated, cartoon-style walkthrough of React Fiber, the rewrite of React''s reconciler, explaining its incremental rendering and scheduling at React Conf 2017.","why":"HN commenters recommend it as the clearest explanation of how Fiber and React 16 work.","type":"talk","level":"intermediate","score":4.0,"topics":["Web"],"recs":3,"years":[2017,2018],"quote":"ReactConf 2017 is excellent","quote_url":"https://news.ycombinator.com/item?id=14142336","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZDR433b0HJY','hn',4.0,'{"vid":"ZDR433b0HJY","title":"Introduction to Git with Scott Chacon of GitHub","channel":"InfoQ","summary":"Scott Chacon introduces Git by showing what happens under the hood for basic commands: staging, committing, data storage, branching, merging and pushing. He contrasts it with Subversion and shows history viewing with log.","why":"HN commenters keep recommending it as the best video for newcomers who want to understand how Git works technically.","type":"talk","level":"intro","score":4.0,"topics":["Software design & craft"],"recs":3,"years":[2012,2016],"quote":"This is the video that I keep recommending to new people who want to know how it works on a technical level.","quote_url":"https://news.ycombinator.com/item?id=13229253","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cn7kTPbW6QQ','hn',4.0,'{"vid":"cn7kTPbW6QQ","title":"Building Your Own Dynamic Language","channel":"Stanford","summary":"Ian Piumarta''s 2007 Stanford EE380 lecture on building a dynamic programming environment from the ground up, from the Viewpoints Research Institute''s work. It covers the design of a language and system with a recursive design, parsing through code generation, and the COLA architecture.","why":"HN commenters recommend it as a way to understand what the VPRI group considers core, such as supporting any syntax on one JIT compiler and removing boundaries between application and interpreter.","type":"lecture","level":"advanced","score":4.0,"topics":["Languages & compilers"],"recs":3,"years":[2009,2014],"quote":"There''s a talk by Ian Piumarta that tries to get to the core of what the VPRI guys feel is important.","quote_url":"https://news.ycombinator.com/item?id=8484504","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fNpsgTIpODA','hn',4.0,'{"vid":"fNpsgTIpODA","title":"Gabriella Gonzalez – How to market Haskell to a mainstream programmer","channel":"Konfy","summary":"Gabriella Gonzalez argues that developers misunderstand marketing as deception or hype, and applies the technology-adoption ideas of Crossing the Chasm to Haskell. She looks at what keeps Haskell from reaching mainstream programmers and what a community can do about it.","why":"Commenters point to it as a clear take on why functional languages stall outside niches, and its lessons are seen as applying to any technology trying to go mainstream.","type":"talk","level":"general","score":4.0,"topics":["Languages & compilers"],"recs":2,"years":[2020,2023],"quote":"although aimed at haskell programmers, is really about any technology looking to grow into the mainstream","quote_url":"https://news.ycombinator.com/item?id=28521098","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hOE6nVVr14c','hn',4.0,'{"vid":"hOE6nVVr14c","title":"Keynote - JSON Graph: Reactive REST at Netflix","channel":"Association for Computing Machinery (ACM)","summary":"Jafar Husain''s ACM keynote presents Netflix''s JSON Graph and Falcor, which let web developers treat all cloud data as one virtual JSON model. It combines reactive programming with REST principles.","why":"HN commenters point to it as an alternative take on the data-fetching problem GraphQL addresses, and as a clear argument for when RPC or graph models beat plain REST.","type":"talk","level":"intermediate","score":4.0,"topics":["Web","Software design & craft"],"recs":4,"years":[2015,2023],"quote":"gives a very nice summary of when and how you might prefer RPC to REST","quote_url":"https://news.ycombinator.com/item?id=24947835","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kPR8h4-qZdk','hn',4.0,'{"vid":"kPR8h4-qZdk","title":"CppCon 2016: Nicholas Ormrod “The strange details of std::string at Facebook\"","channel":"CppCon","summary":"Nicholas Ormrod''s CppCon 2016 talk on how Facebook optimizes std::string with its open-source replacement fbstring. It covers storage layout tradeoffs, small string optimization and memory allocation behavior.","why":"HN returns to it as the go-to talk on string internals, small string packing and why small percentage optimizations matter at scale.","type":"talk","level":"advanced","score":4.0,"topics":["Systems & performance"],"recs":4,"years":[2018,2026],"quote":"it''s still definitely worth a watch","quote_url":"https://news.ycombinator.com/item?id=22198573","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('knUitQQnpJo','hn',4.0,'{"vid":"knUitQQnpJo","title":"Christophe Pettus - PostgreSQL Proficiency for Python People - PyCon 2016","channel":"PyCon 2016","summary":"A three-hour PyCon 2016 tutorial by Christophe Pettus that orients Python developers to PostgreSQL. It covers installation, administration, and use, including vacuuming, MVCC, replication and backups.","why":"HN readers recommend it as a thorough, practical introduction to Postgres fundamentals and optimization for application developers.","type":"tutorial","level":"intro","score":4.0,"topics":["Python","Databases & distributed","Languages & compilers"],"recs":3,"years":[2016,2016],"quote":"I found this to be great introductory that touches on all the major points to keep in mind with Postgres.","quote_url":"https://news.ycombinator.com/item?id=12470200","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('l6XQUciI-Sc','hn',4.0,'{"vid":"l6XQUciI-Sc","title":"Ubuntu Slaughters Kittens | BSD Now 103","channel":"Jupiter Broadcasting","summary":"A BSD Now episode featuring a long interview with Joyent CTO Bryan Cantrill on dtrace, ZFS, pkgsrc, containers and more. It includes his rant on why Linux epoll is flawed and stories from Sun.","why":"HN links it for Cantrill''s entertaining epoll versus kqueue rant and his stories, such as bricking a machine with rm -rf.","type":"interview","level":"advanced","score":4.0,"topics":["Systems & performance"],"recs":4,"years":[2015,2024],"quote":"There''s a good (and wildly entertaining) discussion/rant about it in this BSD Now episode","quote_url":"https://news.ycombinator.com/item?id=12344552","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('m64SWl9bfvk','hn',4.0,'{"vid":"m64SWl9bfvk","title":"\"Stop Rate Limiting! Capacity Management Done Right\" by Jon Moore","channel":"Strange Loop Conference","summary":"Jon Moore''s Strange Loop 2017 talk argues that rate limiting is the wrong tool for protecting services from noisy clients. He proposes concurrency-based capacity management and quotas instead.","why":"HN engineers recommend it for its core insight that limiting concurrency naturally yields request-rate limits, and for its link to queueing theory.","type":"talk","level":"intermediate","score":4.0,"topics":["Databases & distributed"],"recs":4,"years":[2017,2024],"quote":"The basic premise is not do do req/s limiting but rather concurrency limiting which results in req/s limiting by itself.","quote_url":"https://news.ycombinator.com/item?id=15963632","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mOtKD7ml0NU','hn',4.0,'{"vid":"mOtKD7ml0NU","title":"Edwin Brady - Idris 2: Type-driven development of Idris | Code Mesh LDN 18","channel":"Code Sync","summary":"Edwin Brady presents Idris 2, a rewrite of the Idris dependently typed language, and shows type-driven development in practice. The demos show the compiler filling in whole functions from their types.","why":"HN points to it as a good introduction to Idris 2 and a striking demonstration of what dependent types enable.","type":"talk","level":"intermediate","score":4.0,"topics":["Languages & compilers"],"recs":5,"years":[2018,2024],"quote":"this looks like a good introduction","quote_url":"https://news.ycombinator.com/item?id=20391990","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mwrA5IRGpfU','hn',4.0,'{"vid":"mwrA5IRGpfU","title":"Writing a Wayland Compositor in Zig - Isaac Freund","channel":"Zig SHOWTIME","summary":"Isaac Freund, author of the River Wayland compositor, talks about writing a Wayland compositor in Zig. He covers why he chose Zig over C and Rust and how Zig can wrap a hairy C library.","why":"HN recommends it as a phenomenal talk on Zig''s C interop and on choosing between C, Rust and Zig for systems work.","type":"talk","level":"intermediate","score":4.0,"topics":["Systems & performance"],"recs":4,"years":[2021,2021],"quote":"I loved his Zig+Wayland screencast [1], where he explained very engagingly how Zig is able to embrace and extend a pretty hairy C library","quote_url":"https://news.ycombinator.com/item?id=29632269","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sK5i-N34im8','hn',4.0,'{"vid":"sK5i-N34im8","title":"Cgroups, namespaces, and beyond: what are containers made from?","channel":"Docker","summary":"Jérôme Petazzoni explains how Linux containers are built from kernel features like cgroups, namespaces and SELinux. He demonstrates putting the pieces together by hand to make a container and compares runtimes and approaches like jails and zones.","why":"HN recommends it as a talk that makes containers click, showing that containerization is not virtualization and demystifying what Docker does.","type":"talk","level":"intermediate","score":4.0,"topics":["Systems & performance"],"recs":4,"years":[2017,2023],"quote":"I watched this talk couple of years ago that made docker/containers finally click for me.","quote_url":"https://news.ycombinator.com/item?id=16008786","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sWgDk-o-6ZE','hn',4.0,'{"vid":"sWgDk-o-6ZE","title":"CppCon 2015: Sean Parent \"Better Code: Data Structures\"","channel":"CppCon","summary":"Sean Parent''s CppCon 2015 talk on better use of standard containers and the goal of having no incidental data structures. It argues that proper containers can greatly simplify code.","why":"Commenters say it changes how you think about types and the STL, and makes a case for simple modern C++.","type":"talk","level":"intermediate","score":4.0,"topics":["DSA","Systems & performance","Software design & craft"],"recs":3,"years":[2016,2021],"quote":"this one really made me aware of what just might be the best way to think about it.","quote_url":"https://news.ycombinator.com/item?id=29037482","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wASCH_gPnDw','hn',4.0,'{"vid":"wASCH_gPnDw","title":"Expert to Expert: Rich Hickey and Brian Beckman - Inside Clojure","channel":"jasonofthel33t","summary":"A Channel 9 Going Deep interview in which Brian Beckman talks with Rich Hickey, creator of Clojure, about the language''s design. It covers Clojure''s persistent data structures, reference types and its approach to concurrency on the JVM.","why":"HN commenters call it a fantastic introduction to Clojure and the thinking behind its design.","type":"interview","level":"intermediate","score":4.0,"topics":["DSA","Languages & compilers"],"recs":3,"years":[2014,2025],"quote":"It''s probably the best technical video I''ve ever watched on YouTube.","quote_url":"https://news.ycombinator.com/item?id=7699478","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wSdV1M7n4gQ','hn',4.0,'{"vid":"wSdV1M7n4gQ","title":"Anders Hejlsberg on Modern Compiler Construction","channel":"Kasper","summary":"Anders Hejlsberg whiteboards how compilers are taught versus how modern ones are actually built. He explains the shift to compilers as services with incremental, error-tolerant, IDE-oriented design, as in Roslyn and TypeScript.","why":"It is the standard reference for why modern compilers and language servers differ from textbook designs, cited in rust-analyzer and parsing threads.","type":"lecture","level":"intermediate","score":4.0,"topics":["Languages & compilers"],"recs":4,"years":[2018,2023],"quote":"I really recommend this video from Anders Hejlsberg (creator of C# and TypeScript)","quote_url":"https://news.ycombinator.com/item?id=18700021","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xnez6tloNSQ','hn',4.0,'{"vid":"xnez6tloNSQ","title":"Lower Latency Graph Queries in Cypher with Redis GraphRoi Lipman, Redis LabsTim Davis, Texas A&M U","channel":"Redis","summary":"Redis Labs and Tim Davis present RedisGraph, which uses GraphBLAS to treat graph queries in Cypher as sparse linear algebra for lower latency.","why":"Recommended in graph database threads as a mind-blowing case for expressing graph analysis as linear algebra.","type":"talk","level":"advanced","score":4.0,"topics":["Databases & distributed","DSA"],"recs":3,"years":[2018,2023],"quote":"I think you''ll find this presentation on GraphBLAS positively mind-blowing","quote_url":"https://news.ycombinator.com/item?id=34519670","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('yG1OZ69H_-o','hn',4.0,'{"vid":"yG1OZ69H_-o","title":"CppCon 2016: Chandler Carruth “Garbage In, Garbage Out: Arguing about Undefined Behavior...\"","channel":"CppCon","summary":"Chandler Carruth''s CppCon 2016 talk tries to defuse the heated debate over undefined behavior in C and C++. He explains from the compiler writer''s perspective why UB exists and how it enables optimization.","why":"HN points to it whenever undefined behavior comes up, as the best explanation of the reasoning behind UB, though some dispute its framing.","type":"talk","level":"advanced","score":4.0,"topics":["Systems & performance","Languages & compilers"],"recs":4,"years":[2016,2026],"quote":"Chandler Carruth''s talk on the subject was really useful for my own understanding of the reasoning behind UB","quote_url":"https://news.ycombinator.com/item?id=17191250","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('z_hm5oX7ZlE','hn',4.0,'{"vid":"z_hm5oX7ZlE","title":"KEYNOTE / Robert Erdmann","channel":"PyCon US","summary":"Robert Erdmann, a materials scientist at the Rijksmuseum, gives a PyCon keynote on the ultra-high-resolution imaging of Rembrandt''s Night Watch. He covers the automated gantry camera system, the Python software that drives it, and the large volumes of image data involved.","why":"HN commenters recommend it as a technically jaw-dropping talk, and it is the standard reference whenever the Night Watch gigapixel images come up.","type":"talk","level":"general","score":4.0,"topics":["Python","Languages & compilers"],"recs":4,"years":[2021,2024],"quote":"This was the first talk I immediately felt the urge to share with multiple co-workers & friends.","quote_url":"https://news.ycombinator.com/item?id=29654848","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zt0OQb1DBko','hn',4.0,'{"vid":"zt0OQb1DBko","title":"\"A (Not So Gentle) Introduction To Systems Programming In ATS\" by Aditya Siram","channel":"Strange Loop Conference","summary":"Aditya Siram introduces ATS, a statically typed ML-like language that compiles to C and offers type-safe pointer arithmetic and a full proof language. The Strange Loop talk shows off C interop, concurrency and verification features with non-trivial examples.","why":"Cited in Rust and systems-language threads as the best introduction to ATS, a language claimed to go beyond Rust''s safety guarantees.","type":"talk","level":"advanced","score":4.0,"topics":["Languages & compilers"],"recs":4,"years":[2017,2022],"quote":"I recommend watching this presentation for a good idea of what ATS programming is like","quote_url":"https://news.ycombinator.com/item?id=24336252","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-cEn_83zRFw','hn',3.5,'{"vid":"-cEn_83zRFw","title":"Rails World 2024 Opening Keynote - David Heinemeier Hansson","channel":"Ruby on Rails","summary":"DHH''s opening keynote at Rails World 2024 in Toronto, where Rails 8 beta shipped. It covers built-in authentication, Propshaft, Solid Cache, Solid Queue, Solid Cable, Kamal 2 and Thruster, pitching the One Person Framework that needs no PaaS.","why":"HN commenters point to it as a primer on modern Rails and as a rebuttal to cloud ''learned helplessness'', worth watching even by non-Ruby developers.","type":"talk","level":"general","score":3.5,"topics":["Languages & compilers","Web"],"recs":6,"years":[2024,2025],"quote":"I highly recommend you watch the first half hour of DHH Rails World talk on Rails 8 even if you aren’t a Ruby dev","quote_url":"https://news.ycombinator.com/item?id=41766878","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('17KCHwOwgms','hn',3.5,'{"vid":"17KCHwOwgms","title":"Dan Abramov   The wet codebase","channel":"eswarnichtsmehrfrei","summary":"Dan Abramov''s talk on the wet codebase, using visualizations to show how removing all duplication too early produces wrong abstractions that are hard to unwind.","why":"Recommended in DRY versus duplication debates for its visuals and its case that copy/paste can beat a wrong abstraction.","type":"talk","level":"intermediate","score":3.5,"topics":["Software design & craft"],"recs":3,"years":[2023,2024],"quote":"Seeing what a premature, wrong abstraction looks like visually was eye opening.","quote_url":"https://news.ycombinator.com/item?id=40527309","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2EWejmkKlxs','hn',3.5,'{"vid":"2EWejmkKlxs","title":"CppCon 2017: Chandler Carruth “Going Nowhere Faster”","channel":"CppCon","summary":"Chandler Carruth shows how to squeeze more performance out of already-optimized C++ code, covering how the CPU executes it. The talk goes into pipelining, branch prediction and speculative execution using benchmarks.","why":"Recommended as the best presentation on how modern CPUs run code, and why speculative execution matters for performance.","type":"talk","level":"advanced","score":3.5,"topics":["Systems & performance"],"recs":2,"years":[2017,2026],"quote":"The best presentation I''ve seen about CPU performance related to pipelining, branch prediction, and speculative execution","quote_url":"https://news.ycombinator.com/item?id=47757051","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('2SuvO4Gi7uY','hn',3.5,'{"vid":"2SuvO4Gi7uY","title":"Superpositions, Sudoku, the Wave Function Collapse algorithm.","channel":"Martin Donald","summary":"Martin Donald explains the Wave Function Collapse algorithm using Sudoku-like constraint solving and shows how he implemented it with Blender and Godot. It links demos and reference articles.","why":"Commenters recommend it as the clearest way to understand WFC, especially in threads about Townscaper and tiled content generation.","type":"explainer","level":"intro","score":3.5,"topics":["DSA"],"recs":3,"years":[2021,2022],"quote":"I found them hard to understand until I found this video by Martin Donald","quote_url":"https://news.ycombinator.com/item?id=31801227","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('37wFVVVZlVU','hn',3.5,'{"vid":"37wFVVVZlVU","title":"Let''s #TalkConcurrency Panel Discussion with Sir Tony Hoare, Joe Armstrong, and Carl Hewitt","channel":"Erlang Solutions","summary":"A panel with Tony Hoare, Joe Armstrong and Carl Hewitt, hosted by Francesco Cesarini, on the history and future of concurrency. The three creators of CSP, Erlang and the actor model discuss their differing approaches.","why":"HN recommends it for getting the inventors of major concurrency models together, disagreements included.","type":"talk","level":"intermediate","score":3.5,"topics":["Databases & distributed","Languages & compilers"],"recs":3,"years":[2019,2026],"quote":"It was interesting hearing them discuss their different thoughts and approaches","quote_url":"https://news.ycombinator.com/item?id=47330576","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3TX3kV3TICU','hn',3.5,'{"vid":"3TX3kV3TICU","title":"Let Vim Do the Typing","channel":"thoughtbot","summary":"George Brocklehurst of thoughtbot demonstrates Vim''s built-in completion mechanisms, from word, line and block completion to ctags. The aim is to type less and make fewer typos.","why":"HN users say it made Vim''s completion system click for them.","type":"tutorial","level":"intermediate","score":3.5,"topics":["Software design & craft"],"recs":3,"years":[2017,2021],"quote":"it \"clicked\" for me after watching this video","quote_url":"https://news.ycombinator.com/item?id=15507810","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4P_kbF0EbZM','hn',3.5,'{"vid":"4P_kbF0EbZM","title":"Stephan T. Lavavej “Floating-Point ＜charconv＞: Making Your Code 10x Faster With C++17''s Final Boss”","channel":"CppCon","summary":"Stephan T. Lavavej''s CppCon 2019 talk on implementing floating-point to_chars and from_chars in Microsoft''s C++ STL. It covers the history of float-string conversion and the algorithms that make it much faster.","why":"HN calls it a surprisingly fun, approachable talk on a hard problem and cites it in floating-point threads.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2020,2022],"quote":"Stephan T Lavavej also had a surprisingly fun and approachable talk on that problem","quote_url":"https://news.ycombinator.com/item?id=24939484","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5Dnw46eC-0o','hn',3.5,'{"vid":"5Dnw46eC-0o","title":"John Rauser keynote: \"Statistics Without the Agonizing Pain\" -- Strata + Hadoop 2014","channel":"O''Reilly","summary":"John Rauser''s Strata 2014 keynote argues that programmers can learn statistics quickly by simulating random processes and shuffling data. He explains p-values through resampling rather than formulas.","why":"HN recommends it as an excellent programmer-friendly explanation of p-values and statistical thinking.","type":"talk","level":"intro","score":3.5,"topics":["AI & ML"],"recs":3,"years":[2015,2025],"quote":"This is an excellent talk I attended a while ago that explains it very well from a programmer''s perspective","quote_url":"https://news.ycombinator.com/item?id=10628320","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5MdSE-N0bxs','hn',3.5,'{"vid":"5MdSE-N0bxs","title":"Connections between physics and deep learning","channel":"MITCBMM","summary":"Max Tegmark''s MIT CBMM talk on why deep learning works so well. He argues that the laws of physics and the symmetries in physical data make it compressible into small neural networks, tying physics to network structure.","why":"HN recommends it as a clear argument for why deep and cheap learning succeeds, often alongside the associated paper.","type":"talk","level":"intermediate","score":3.5,"topics":["AI & ML"],"recs":3,"years":[2016,2026],"quote":"physical data tends to have symmetries, and these symmetries make descriptions of the data very compressible into relatively small neural circuits","quote_url":"https://news.ycombinator.com/item?id=17050814","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('6OPsH8PK7xM','hn',3.5,'{"vid":"6OPsH8PK7xM","title":"What P vs NP is actually about","channel":"Polylog","summary":"Polylog explains how algorithms can be turned into circuits and encoded as satisfiability problems, which lets you effectively run them backwards. It uses this to motivate breaking RSA, general reductions to SAT, and what P vs NP is really asking.","why":"Recommended as an intuitive, animated explanation of P vs NP framed around reversing computation.","type":"explainer","level":"intro","score":3.5,"topics":["Math & theory","DSA"],"recs":4,"years":[2024,2026],"quote":"I would highly recommend giving it a watch","quote_url":"https://news.ycombinator.com/item?id=41751072","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('74zOY-vgkyw','hn',3.5,'{"vid":"74zOY-vgkyw","title":"Emacs From Scratch #1 - Getting Started with a Basic Usable Configuration","channel":"System Crafters","summary":"The first stream in the Emacs From Scratch series, building a custom Emacs configuration from zero while teaching basics. It covers a usable baseline setup and the packages for completion, themes and productivity.","why":"Recommended as a thoughtful, step-by-step way to build your own Emacs config rather than starting from Doom or Spacemacs.","type":"tutorial","level":"intro","score":3.5,"topics":["Software design & craft","Languages & compilers"],"recs":3,"years":[2021,2024],"quote":"System Crafters'' ''Emacs from Sratch'' series [0], which is incredibly well thought-out","quote_url":"https://news.ycombinator.com/item?id=37431152","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7JUs4c99-mo','hn',3.5,'{"vid":"7JUs4c99-mo","title":"CheerpX: a WebAssembly-based x86 virtual machine in the browser, Yuri Iozzelli","channel":"WebAssembly NA","summary":"A talk by Yuri Iozzelli at a WebAssembly meetup on CheerpX, an x86 virtual machine running in the browser. It uses a JIT compiler that emits WebAssembly at runtime to run real native applications. It covers the architecture and demos such as porting a multiplayer C++ game.","why":"HN points to it as an impressive look at how far WebAssembly can go, and as the explanation of the architecture behind CheerpX and its Flash support.","type":"talk","level":"advanced","score":3.5,"topics":["Web","Systems & performance"],"recs":2,"years":[2020,2025],"quote":"This is honestly one of the coolest things I''ve seen","quote_url":"https://news.ycombinator.com/item?id=23532747","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9QveBbn7t_c','hn',3.5,'{"vid":"9QveBbn7t_c","title":"Monad - FunFunFunction #21","channel":"Fun Fun Function","summary":"An episode of FunFunFunction explaining monads in JavaScript as functors that also implement flatMap. It builds on the preceding functor episode and works through code examples.","why":"Recommended to people confused by monads as a friendly, practical explanation for JavaScript developers, with one commenter saying it finally made it click.","type":"tutorial","level":"intermediate","score":3.5,"topics":["Languages & compilers","Web"],"recs":3,"years":[2016,2021],"quote":"I saw a video by MPJ/Funfunfunction [0] and it finally made sense.","quote_url":"https://news.ycombinator.com/item?id=28943256","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('BrK7X_XlGB8','hn',3.5,'{"vid":"BrK7X_XlGB8","title":"A visual guide to Bayesian thinking","channel":"Julia Galef","summary":"Julia Galef uses pictures to explain Bayes'' rule, then tells three personal stories showing how she applies it to improve her thinking.","why":"HN recommends it as a short, accessible intro to Bayesian reasoning and priors.","type":"talk","level":"intro","score":3.5,"topics":["Math for ML"],"recs":3,"years":[2017,2021],"quote":"The most important mathematical video you will ever see in your life.","quote_url":"https://news.ycombinator.com/item?id=14966883","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('C-kF25fWTO8','hn',3.5,'{"vid":"C-kF25fWTO8","title":"Clojure in a nutshell by James Trunk","channel":"Func Prog Sweden","summary":"James Trunk introduces Clojure syntax and thinking, covering its core data structures, immutability, the thread-last macro and live data analysis in the REPL.","why":"HN commenters recommend it as a clear, enjoyable introduction to Clojure and a good example of REPL-driven development.","type":"tutorial","level":"intro","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2021,2023],"quote":"gave one of the most clear and enjoyable technical introductions to Clojure I''ve seen. Recommended!","quote_url":"https://news.ycombinator.com/item?id=37314881","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('D5xh0ZIEUOE','hn',3.5,'{"vid":"D5xh0ZIEUOE","title":"James Mickens on JavaScript","channel":"tablet reader","summary":"James Mickens delivers his comedic rant about JavaScript and web programming, in his usual dry, hyperbolic style. It includes his account of learning the language from the O''Reilly Definitive Guide.","why":"HN recommends it as a hilarious talk by a beloved speaker, and also uses it to jab at JavaScript''s quirks.","type":"talk","level":"general","score":3.5,"topics":["Web"],"recs":3,"years":[2018,2025],"quote":"James Mickens is a national treasure. Go watch his talks on YouTube and read everything he writes.","quote_url":"https://news.ycombinator.com/item?id=34524868","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('D7Sd8A6_fYU','hn',3.5,'{"vid":"D7Sd8A6_fYU","title":"CppCon 2016: Dan Saks “extern c: Talking to C Programmers about C++”","channel":"CppCon","summary":"Dan Saks''s CppCon 2016 talk on why C programmers resist C++ and how to talk to them about it. He argues that persuasion rarely works by arguing and examines the culture gap between the two communities.","why":"Recommended in C versus C++ and embedded threads as the expert view on adoption and persuasion.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance"],"recs":2,"years":[2017,2025],"quote":"The mentioned cppcon presentation by Dan Saks is awesome. Highly recommend watching even if you are not interested in C or C++","quote_url":"https://news.ycombinator.com/item?id=23205586","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DJFKl_5JTnA','hn',3.5,'{"vid":"DJFKl_5JTnA","title":"Donald B. Gillies Lecture: Dr. Michael Stonebraker","channel":"Siebel School of Computing and Data Science","summary":"Turing Award winner Michael Stonebraker gives the 2018 Donald B. Gillies Memorial Lecture at Illinois. He discusses the gap between academic research and industry problems, publishing incentives, and the influence of large industry users on research.","why":"Cited in many threads about academic incentives, paper counts and why academia struggles to produce working software.","type":"lecture","level":"intermediate","score":3.5,"topics":["Databases & distributed"],"recs":2,"years":[2018,2024],"quote":"There''s a lot more, I highly recommend the talk!","quote_url":"https://news.ycombinator.com/item?id=40032031","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('DkMwYxfSYNQ','hn',3.5,'{"vid":"DkMwYxfSYNQ","title":"The Why, What, and How of Pinning in Rust","channel":"Jon Gjengset","summary":"Jon Gjengset''s long live-coding stream explains Rust''s Pin and Unpin types: why they exist, how they work, and how they connect to futures and async/await. It also covers moving from pre-pinning code to the new model.","why":"HN treats it as the definitive resource for understanding Pin semantics and lists it among async Rust learning materials.","type":"tutorial","level":"advanced","score":3.5,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2021,2026],"quote":"Jon Gjengset''s stream on pin/unpin is invaluable for understanding Pin semantics","quote_url":"https://news.ycombinator.com/item?id=35362394","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IHZwWFHWa-w','hn',3.5,'{"vid":"IHZwWFHWa-w","title":"Gradient descent, how neural networks learn | Deep Learning Chapter 2","channel":"3Blue1Brown","summary":"3Blue1Brown''s second neural network chapter explains cost functions and gradient descent, showing how a network learns by minimizing error during training.","why":"HN recommends the series as a very accessible way to understand the math behind machine learning and LLMs.","type":"explainer","level":"intro","score":3.5,"topics":["AI & ML"],"recs":4,"years":[2017,2024],"quote":"3Blue1Brown which explains math in very accessible way","quote_url":"https://news.ycombinator.com/item?id=15689936","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IeSu_odkI5I','hn',3.5,'{"vid":"IeSu_odkI5I","title":"Armin Ronacher - A Python for Future Generations","channel":"EuroPython Conference","summary":"Armin Ronacher''s EuroPython 2017 keynote examining how the CPython interpreter''s leaky abstractions affect language design and how Python could evolve, drawing on JavaScript and Rust experience.","why":"Recommended for explaining why Python is hard to optimize and the limits of making it fast.","type":"talk","level":"advanced","score":3.5,"topics":["Python","Languages & compilers","Systems & performance"],"recs":4,"years":[2017,2020],"quote":"I highly recommend the two videos posted here","quote_url":"https://news.ycombinator.com/item?id=24850511","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IkdziSLYzHw','hn',3.5,'{"vid":"IkdziSLYzHw","title":"Will AI outsmart human intelligence? - with ''Godfather of AI'' Geoffrey Hinton","channel":"The Royal Institution","summary":"Geoffrey Hinton''s 2025 Royal Institution Discourse on what AI has learned from biological intelligence and how it might surpass it. He explains neural networks and argues that human language use resembles what backpropagation-trained networks do.","why":"HN readers recommend it as an intuitive explanation of neural networks that shifts how people think about AI and language.","type":"lecture","level":"general","score":3.5,"topics":["AI & ML","LLMs"],"recs":3,"years":[2025,2025],"quote":"Richard Sutton takes a different view in an interview with Dwarkesh Patel[2]","quote_url":"https://news.ycombinator.com/item?id=45805599","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KbB0FjPg0mw','hn',3.5,'{"vid":"KbB0FjPg0mw","title":"Lecture 1: Probability and Counting | Statistics 110","channel":"Harvard University","summary":"Lecture 1 of Harvard''s Statistics 110 with Joe Blitzstein, introducing sample spaces, the naive definition of probability, counting, binomial coefficients and the sampling table.","why":"Recommended on Ask HN threads as a high-quality free probability course for relearning math or building an ML foundation.","type":"lecture","level":"intro","score":3.5,"topics":["Math for ML"],"recs":3,"years":[2017,2018],"quote":"I have used and can vouch for the high quality of all of them","quote_url":"https://news.ycombinator.com/item?id=14360161","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('MYucYon2-lk','hn',3.5,'{"vid":"MYucYon2-lk","title":"Hillel Wayne - Beyond Unit Tests: Taking Your Testing to the Next Level - PyCon 2018","channel":"PyCon 2018","summary":"Hillel Wayne''s PyCon 2018 talk on testing beyond pytest and mypy. It introduces property-based testing with the Hypothesis library and design-by-contract with dpcontracts, and shows how to combine them with an existing test suite.","why":"HN commenters point to it as a concise, convincing case for better testing practice short of full formal methods.","type":"talk","level":"intermediate","score":3.5,"topics":["Python","Software design & craft","Languages & compilers"],"recs":3,"years":[2018,2023],"quote":"I found this talk (by the same person being interviewed) to be concise and convincing on how to do better than typical practice","quote_url":"https://news.ycombinator.com/item?id=19672414","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OQQ-W_63UgQ','hn',3.5,'{"vid":"OQQ-W_63UgQ","title":"Lecture 1 | Natural Language Processing with Deep Learning","channel":"Stanford University School of Engineering","summary":"The first lecture of Stanford''s Natural Language Processing with Deep Learning course, taught by Chris Manning and Richard Socher. It introduces NLP and word vectors, including SVD, skip-gram, CBOW, negative sampling and word2vec.","why":"Recommended as one of the best free courses for learning modern deep learning for NLP.","type":"lecture","level":"intermediate","score":3.5,"topics":["AI & ML"],"recs":3,"years":[2017,2018],"quote":"I will suggest two brilliant courses from Stanford","quote_url":"https://news.ycombinator.com/item?id=16168374","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OxhTQdcieQE','hn',3.5,'{"vid":"OxhTQdcieQE","title":"RailsConf 2016 - Rails to Phoenix by Brian Cardarella","channel":"Confreaks","summary":"Brian Cardarella''s RailsConf 2016 talk on why and how teams can move from Rails to Elixir and Phoenix. It covers performance gains without losing productivity and how to introduce Phoenix in an organization.","why":"HN points Rails developers to it as a real-world case for migrating to Phoenix, backed by numbers.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers"],"recs":4,"years":[2016,2016],"quote":"A really great presentation, including numbers and real world backup data, plus conceptual overviews.","quote_url":"https://news.ycombinator.com/item?id=12018523","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PFUZlNQIndo','hn',3.5,'{"vid":"PFUZlNQIndo","title":"DuckDB – The SQLite for Analytics (Mark Raasveldt, CWI)","channel":"CMU Database Group","summary":"Mark Raasveldt of CWI presents DuckDB, an embeddable analytical database described as the SQLite for analytics, in a CMU Database Group talk. He explains why it was built, what it is for, and how it works.","why":"HN recommends it as the definitive talk from the implementer on DuckDB''s motivation and design.","type":"talk","level":"intermediate","score":3.5,"topics":["Databases & distributed","AI & ML"],"recs":2,"years":[2020,2026],"quote":"one of the implementers giving a talk to CMU students about what DuckDB is, why they made it, and how it works","quote_url":"https://news.ycombinator.com/item?id=23287914","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PSGEjv3Tqo0','hn',3.5,'{"vid":"PSGEjv3Tqo0","title":"Nordic.js 2014 • Douglas Crockford - The Better Parts","channel":"Nordic.js","summary":"Douglas Crockford''s Nordic.js 2014 talk on ''the better parts'' of JavaScript and programming in general. He argues against `this`, `new` and ES6 classes, and for classless, composition-based object patterns, with some broader remarks on building better structures for the future.","why":"HN commenters cite it whenever JavaScript classes, `this` or inheritance come up, as the clearest case for classless OOP from Crockford.","type":"talk","level":"intermediate","score":3.5,"topics":["Web","Languages & compilers"],"recs":3,"years":[2014,2023],"quote":"It''s possible to write javascript without `this`, a style preferred e.g. by Douglas Crockford, explained in the video below.","quote_url":"https://news.ycombinator.com/item?id=14917153","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('T5RmMNDR5XI','hn',3.5,'{"vid":"T5RmMNDR5XI","title":"What is in a Lucene index? Adrien Grand, Software Engineer, Elasticsearch","channel":"LuceneSolrRevolution","summary":"Elasticsearch engineer and Lucene committer Adrien Grand explains the design decisions inside a Lucene index and what problems it can and cannot solve. The talk goes into how Lucene stores data for fast search and analytics.","why":"HN recommends it as an instructive, easy-to-follow look at Lucene internals from a core committer.","type":"talk","level":"intermediate","score":3.5,"topics":["Databases & distributed","DSA"],"recs":3,"years":[2019,2020],"quote":"I can super highly recommend talks by Adrien Grand on Lucene and Elasticsearch.","quote_url":"https://news.ycombinator.com/item?id=21989365","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('UANN2Eu6ZnM','hn',3.5,'{"vid":"UANN2Eu6ZnM","title":"The Mental Game of Python - Raymond Hettinger","channel":"SF Python","summary":"Raymond Hettinger''s PyBay 2019 talk on the mental habits behind effective programming, drawn from coaching, teaching and StackOverflow. He covers problem decomposition, chunking, managing working memory and getting unstuck.","why":"HN recommends it as a Python talk with lessons that apply to any programming, especially chunking to manage complexity.","type":"talk","level":"general","score":3.5,"topics":["Python","Languages & compilers"],"recs":3,"years":[2019,2023],"quote":"Here''s a good recent one by Raymond Hettinger on making things easier for yourself when programming","quote_url":"https://news.ycombinator.com/item?id=24377018","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('WDIkqP4JbkE','hn',3.5,'{"vid":"WDIkqP4JbkE","title":"code::dive conference 2014 - Scott Meyers: Cpu Caches and Why You Care","channel":"NOKIA Technology Center Wrocław","summary":"Scott Meyers explains how CPU caches work and why they matter for performance, covering cache levels, access speeds, associativity, and effects in multithreaded code. The focus is C++ and cache-aware, data-oriented programming.","why":"HN points to it as the go-to explanation of why memory layout beats pointer-chasing structures on real hardware.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2018,2023],"quote":"Scott Meyers had a very good talk which contained this information","quote_url":"https://news.ycombinator.com/item?id=35738297","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Y4Gt3Xjd7G8','hn',3.5,'{"vid":"Y4Gt3Xjd7G8","title":"Build Your Own Async","channel":"David Beazley","summary":"David Beazley''s workshop screencast builds asynchronous programming in Python from scratch, starting from callbacks and continuations and replacing threads to show how concurrency works underneath.","why":"HN people recommend it as the best way to understand what async machinery actually does under the covers.","type":"tutorial","level":"advanced","score":3.5,"topics":["Python","Languages & compilers"],"recs":4,"years":[2020,2023],"quote":"an amazing resource to understand async at a deep level","quote_url":"https://news.ycombinator.com/item?id=23296660","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZQFzMfHIxng','hn',3.5,'{"vid":"ZQFzMfHIxng","title":"CppCon 2017: Fedor Pikus “C++ atomics, from basic to advanced.  What do they really do?”","channel":"CppCon","summary":"Fedor Pikus''s CppCon 2017 talk on C++ atomics, looking at what they let the programmer express and what the hardware actually does. It covers memory ordering and lock-free programming from basic to advanced.","why":"HN recommends it as an enlightening explanation of atomics, caches and memory ordering from a strong presenter.","type":"talk","level":"advanced","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2017,2025],"quote":"Watching this was enlightening to say the least (and the presenter is very good)","quote_url":"https://news.ycombinator.com/item?id=15770071","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('_IgqJr8jG8M','hn',3.5,'{"vid":"_IgqJr8jG8M","title":"Stanford Seminar - Concatenative Programming: From Ivory to Metal","channel":"Stanford Online","summary":"Jon Purdy''s Stanford EE380 seminar giving an overview of concatenative programming, from function composition theory and history down to low-level implementation and correctness benefits.","why":"HN recommends it as the best talk on concatenative languages and their mathematical properties.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers"],"recs":2,"years":[2020,2022],"quote":"Jon Purdy has a great talk about this too","quote_url":"https://news.ycombinator.com/item?id=32127078","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('an5abNFba4Q','hn',3.5,'{"vid":"an5abNFba4Q","title":"Servo Architecture: Safety and Performance","channel":"linux conf au 2017 - Hobart, Australia","summary":"Jack Moffitt presents the architecture of Servo, Mozilla''s experimental browser engine written in Rust, focusing on parallelism across cores, GPUs and SIMD and the safety properties gained from Rust.","why":"HN recommends it as an exciting look at how a browser can be rebuilt for performance and safety, including the WebRender ideas that fed into Firefox Quantum.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance","Web"],"recs":3,"years":[2017,2017],"quote":"This video is one of the most exciting I have seen with regards to web browser performance, and it''s Mozilla","quote_url":"https://news.ycombinator.com/item?id=13504773","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bZQun8Y4L2A','hn',3.5,'{"vid":"bZQun8Y4L2A","title":"State of GPT | BRK216HFS","channel":"Microsoft Developer","summary":"Andrej Karpathy walks through how GPT assistants are trained, from tokenization and pretraining to supervised finetuning and RLHF, and gives practical prompting strategies and a view of the tooling ecosystem.","why":"Recommended as the clearest overview of how LLM assistants are built and how to use them well.","type":"talk","level":"intro","score":3.5,"topics":["Karpathy","AI & ML","LLMs"],"recs":6,"years":[2023,2025],"quote":"It changed the way I use GPT-4.","quote_url":"https://news.ycombinator.com/item?id=36207905","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('baxtyeFVn3w','hn',3.5,'{"vid":"baxtyeFVn3w","title":"Lambda World 2018 - What FP can learn from Smalltalk by Aditya Siram","channel":"Lambda World","summary":"Aditya Siram argues that functional programming has much to learn from Smalltalk''s interactivity, using Pharo and Squeak to show live, visual, explorable programming environments.","why":"HN recommends it as an accessible demonstration of what Smalltalk environments offer and a reference for advanced IDE ideas.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2020,2023],"quote":"I think it is the most accessible explanation of the marvel of Smalltalk","quote_url":"https://news.ycombinator.com/item?id=23509075","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bxe2T-V8XRs','hn',3.5,'{"vid":"bxe2T-V8XRs","title":"Neural Networks Demystified [Part 1: Data and Architecture]","channel":"Welch Labs","summary":"The first of a short series by Welch Labs on building a complete neural network in Python. It introduces the data and the architecture of a simple network before later parts cover forward propagation, gradient descent, and backpropagation.","why":"HN commenters point beginners to this series as one of the clearest short walkthroughs of how neural networks and backpropagation work.","type":"tutorial","level":"intro","score":3.5,"topics":["Python","AI & ML"],"recs":3,"years":[2015,2018],"quote":"One of the clearest walkthroughs I''ve seen online is a short series of very short videos by Stephen C Welch [2] [3].","quote_url":"https://news.ycombinator.com/item?id=9124289","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cdiD-9MMpb0','hn',3.5,'{"vid":"cdiD-9MMpb0","title":"Andrej Karpathy: Tesla AI, Self-Driving, Optimus, Aliens, and AGI | Lex Fridman Podcast #333","channel":"Lex Fridman","summary":"Lex Fridman''s long conversation with Andrej Karpathy on Tesla''s self-driving approach, Optimus, neural networks, transformers, AGI and more. It also touches on his OpenAI work and working with Elon Musk.","why":"Cited for Karpathy''s first-hand explanations of camera-only self-driving, transformers and ML trends.","type":"podcast","level":"intermediate","score":3.5,"topics":["Karpathy","AI & ML","LLMs"],"recs":3,"years":[2022,2025],"quote":"Anyone seriously interested in this question should listen to the Lex Friedman interview of Andrej Karpathy","quote_url":"https://news.ycombinator.com/item?id=34453756","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cefnmjtAolY','hn',3.5,'{"vid":"cefnmjtAolY","title":"Lenses, Folds, and Traversals","channel":"Edward Kmett","summary":"Edward Kmett''s talk to the NY Haskell User Group on the lens library, building from fmap and function composition up to lenses, folds and traversals. It shows how these composable combinators access and modify parts of data structures.","why":"HN calls it dense but mind-blowing, the go-to way to understand lenses through algebraic derivation.","type":"talk","level":"advanced","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2013,2014],"quote":"I found this talk by edward kmett incredibly helpful[0].","quote_url":"https://news.ycombinator.com/item?id=8621948","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('coFIEH3vXPw','hn',3.5,'{"vid":"coFIEH3vXPw","title":"Run containers on bare metal already!","channel":"Bryan Cantrill","summary":"Bryan Cantrill''s Velocity NYC 2015 talk argues for running containers directly on bare metal rather than layering them on virtual machines. He covers the history of containers and how SmartOS runs Linux workloads via syscall emulation.","why":"HN commenters recommend it as an engaging and informative explanation of why containers on VMs waste resources and hurt performance.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2015,2025],"quote":"he''s an extremely engaging speaker, so not only are you likely to watch all of that 40 minute talk","quote_url":"https://news.ycombinator.com/item?id=15611533","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dKJEpOtVgXc','hn',3.5,'{"vid":"dKJEpOtVgXc","title":"Do we need Attention? - Linear RNNs and State Space Models (SSMs) for NLP","channel":"Sasha Rush","summary":"Sasha Rush surveys linear RNNs and state space models as replacements for attention in transformer-style models, in a talk for MLSys. It covers the foundational preliminaries and predates Mamba.","why":"HN commenters recommend it for building intuition about state space models and the tradeoffs between transformer and SSM layers.","type":"lecture","level":"advanced","score":3.5,"topics":["AI & ML","LLMs"],"recs":3,"years":[2024,2024],"quote":"I highly recommend Sasha Rush''s video on it","quote_url":"https://news.ycombinator.com/item?id=39855435","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ds77e3aO9nA','hn',3.5,'{"vid":"ds77e3aO9nA","title":"A Narrative History of BSD, Dr. Kirk McKusick","channel":"bsdconferences","summary":"Kirk McKusick gives a narrative history of BSD from its start at UC Berkeley in the late 1970s through the 1980s releases and the lawsuit that led to 4.4BSD-Lite in 1992. It is full of anecdotes from a key developer.","why":"Recommended as an engaging, non-technical history of Unix and BSD from someone who was there, and cited for specific stories like the TCP/IP stack.","type":"talk","level":"general","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2013,2017],"quote":"but the whole thing is excellent.","quote_url":"https://news.ycombinator.com/item?id=6563326","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('e08kOj2kISU','hn',3.5,'{"vid":"e08kOj2kISU","title":"How to Speed up a Python Program 114,000 times.","channel":"InfoQ","summary":"David Schachter describes how he made a data-collection Python program run 114,000 times faster, drawing on decades of experience. The talk covers pipelining, cache effects and other optimization lessons.","why":"A favorite tech talk on HN for showing that hardware knowledge and generalist skills beat simply adding machines.","type":"talk","level":"intermediate","score":3.5,"topics":["Python","Systems & performance","Languages & compilers"],"recs":3,"years":[2015,2022],"quote":"Humour, serious technical insight and a good reminder of why being a generalist is an advantage.","quote_url":"https://news.ycombinator.com/item?id=12638364","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('eGaKZBr0ga4','hn',3.5,'{"vid":"eGaKZBr0ga4","title":"MountainWest RubyConf 2014 - But Really, You Should Learn Smalltalk","channel":"Confreaks","summary":"Noel Rappin''s MountainWest RubyConf talk introduces Smalltalk to Ruby programmers. He compares the two languages'' object models, blocks, 1-based arrays, simple syntax and live programming environment, and walks through sample code.","why":"HN commenters point Rubyists and the Smalltalk-curious to it as an approachable introduction that shows the Smalltalk system browser and Pharo environment in action.","type":"talk","level":"intro","score":3.5,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2016,2024],"quote":"if you enjoy Ruby, watch this","quote_url":"https://news.ycombinator.com/item?id=37314602","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('g6bOwQdCJrc','hn',3.5,'{"vid":"g6bOwQdCJrc","title":"[CVPR''21 WAD] Keynote - Andrej Karpathy, Tesla","channel":"WAD at CVPR","summary":"Andrej Karpathy, then Tesla''s head of AI, gives a CVPR 2021 workshop keynote on how Autopilot''s neural networks work. A large part covers the move to a vision-only stack, including why radar was dropped and how vision produces depth estimates.","why":"HN commenters cite it in Tesla threads as the primary-source explanation of why Tesla removed radar and how its vision depth estimation works.","type":"talk","level":"advanced","score":3.5,"topics":["Karpathy","AI & ML"],"recs":4,"years":[2021,2023],"quote":"This talk was worth watching (any Karpathy or Carmack talk is imo)","quote_url":"https://news.ycombinator.com/item?id=35843032","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gFEE3w7F0ww','hn',3.5,'{"vid":"gFEE3w7F0ww","title":"Travis Oliphant: NumPy, SciPy, Anaconda, Python & Scientific Programming | Lex Fridman Podcast #224","channel":"Lex Fridman","summary":"Lex Fridman interviews Travis Oliphant, creator of NumPy, SciPy and Anaconda, about scientific Python and its history. It runs about three hours.","why":"Recommended as a firsthand history of how Python became the language of scientific computing and ML.","type":"podcast","level":"intermediate","score":3.5,"topics":["Python","Languages & compilers","AI & ML"],"recs":2,"years":[2021,2024],"quote":"I highly recommend this bit of history from NumPy creator Travis Oliphant","quote_url":"https://news.ycombinator.com/item?id=39932517","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gSKTfG1GXYQ','hn',3.5,'{"vid":"gSKTfG1GXYQ","title":"Charlie Marsh: uv: An Extremely Fast Python Package Manager","channel":"Jane Street","summary":"Charlie Marsh of Astral explains how uv, a Rust Python package manager, got so fast. He covers allocators, concurrency, zero-copy tricks and the challenges of Python packaging.","why":"Recommended as a fascinating technical account of the optimizations behind uv''s speed.","type":"talk","level":"intermediate","score":3.5,"topics":["Python","Languages & compilers","Systems & performance"],"recs":3,"years":[2024,2025],"quote":"I recently watched a talk by the author of uv that was surprisingly fascinating","quote_url":"https://news.ycombinator.com/item?id=42191388","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('giYbq4HmfGA','hn',3.5,'{"vid":"giYbq4HmfGA","title":"ElixirConf 2023 - José Valim - The foundations of the Elixir type system","channel":"ElixirConf","summary":"José Valim''s ElixirConf US 2023 closing keynote on the foundations of the Elixir type system, covering set-theoretic types and gradual typing with strong arrows.","why":"HN recommends it as the best detailed explanation from the language''s creator of how Elixir''s new type system works and why.","type":"talk","level":"advanced","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2023,2026],"quote":"If you''re into watching talks, this will be well worth your time.","quote_url":"https://news.ycombinator.com/item?id=40657484","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gsffg5xxFQI','hn',3.5,'{"vid":"gsffg5xxFQI","title":"ClojureScript for Skeptics - Derek Slager","channel":"ClojureTV","summary":"Derek Slager''s Clojure/conj talk argues that ClojureScript is a pragmatic choice for web development. He addresses common objections, recent improvements, tooling and use cases where it shines.","why":"Recommended to JavaScript skeptics as a persuasive case for ClojureScript, covering Closure Compiler optimizations and code-splitting.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers","Web"],"recs":4,"years":[2015,2017],"quote":"completely sold me on trying it out","quote_url":"https://news.ycombinator.com/item?id=14421628","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hs3piaN4b5I','hn',3.5,'{"vid":"hs3piaN4b5I","title":"Flexbox vs. CSS Grid — Which is Better?","channel":"Layout Land","summary":"Jen Simmons explains the difference between CSS Flexbox and CSS Grid, and when to use each. She makes the case that Grid does not replace Flexbox and most sites use both.","why":"Recommended as a short, clear rundown of one-dimensional versus two-dimensional layout.","type":"explainer","level":"intro","score":3.5,"topics":["Web"],"recs":3,"years":[2018,2020],"quote":"Here''s a great explanation from Jen Simmons that really helped me understand the differences","quote_url":"https://news.ycombinator.com/item?id=17619608","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('j-kj2qwJa_E','hn',3.5,'{"vid":"j-kj2qwJa_E","title":"Bruce Hauman - Developing ClojureScript With Figwheel","channel":"ClojureTV","summary":"Bruce Hauman presents Figwheel, a ClojureScript tool for live, interactive development with hot code reloading. He explains the main ideas, demonstrates how it works, and shares tricks for getting the most out of it.","why":"HN people point to it as a very visual demonstration of what hot-reloading and interactive development can offer, and as an example of a great dev tool pitch.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2017,2022],"quote":"it''s a very visual demonstration of what hot-reloading code and interactive development can bring","quote_url":"https://news.ycombinator.com/item?id=15038558","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('m7PVZixO35c','hn',3.5,'{"vid":"m7PVZixO35c","title":"New computers don''t speed up old code","channel":"Matthias random stuff","summary":"Matthias Wandel tests old and new code on a range of PCs, including a new mini PC, to measure how much faster modern hardware really is. He also shows optimization techniques such as branchless code, with benchmark programs on GitHub.","why":"Used as evidence that CPU speed for branchy, dependent code has improved only modestly in 15-20 years, so software optimization matters.","type":"explainer","level":"intermediate","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2025,2025],"quote":"This great video [0] demonstrates how CPU performance has only increased 1.5-2x over the past 15(!) years when executing extremely branchy code.","quote_url":"https://news.ycombinator.com/item?id=45406403","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nAbCKa0FzjQ','hn',3.5,'{"vid":"nAbCKa0FzjQ","title":"C++Now 2018: Matt Godbolt “What Else Has My Compiler Done For Me Lately?”","channel":"CppNow","summary":"Matt Godbolt, creator of Compiler Explorer, tours surprising optimizations modern compilers perform, such as turning loops into closed-form sums and using popcount instructions. He explores what the compiler does behind the scenes.","why":"HN recommends it as a detailed, entertaining look at the crazy optimizations compilers do.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers","Systems & performance"],"recs":3,"years":[2018,2020],"quote":"Both are great presentations going into details on some of the crazy optimizations compilers will do.","quote_url":"https://news.ycombinator.com/item?id=20915513","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nLF0n9SACd4','hn',3.5,'{"vid":"nLF0n9SACd4","title":"Dan Abramov: Beyond React 16 | JSConf Iceland","channel":"JSConf","summary":"Dan Abramov''s JSConf Iceland talk on what came after React 16, with live-coded prototypes of async rendering and time slicing. It previews the ideas that became concurrent mode and suspense.","why":"Recommended as the clearest demo of what concurrent rendering solves, including the memorable clock animation.","type":"talk","level":"intermediate","score":3.5,"topics":["Web"],"recs":3,"years":[2018,2022],"quote":"That clock animation is pure genius","quote_url":"https://news.ycombinator.com/item?id=21348235","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nU8DcBF-qo4','hn',3.5,'{"vid":"nU8DcBF-qo4","title":"Google Developers Day US - Theorizing from Data","channel":"GoogleDeveloperDay","summary":"Peter Norvig''s 2007 Google talk on theorizing from data, covering what huge datasets can do for language understanding, translation, information extraction and inference. It argues that more data often beats cleverer models.","why":"HN recommends it as the clear explanation of why Google''s statistical, data-first approach works.","type":"talk","level":"intermediate","score":3.5,"topics":["AI & ML"],"recs":3,"years":[2007,2009],"quote":"You should definitely watch it if you haven''t seen it before.","quote_url":"https://news.ycombinator.com/item?id=150849","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('nXaxk27zwlk','hn',3.5,'{"vid":"nXaxk27zwlk","title":"CppCon 2015: Chandler Carruth \"Tuning C++: Benchmarks, and CPUs, and Compilers! Oh My!\"","channel":"CppCon","summary":"Chandler Carruth walks through tuning C++ performance, from writing benchmarks to analyzing results on real CPUs and compilers. It focuses on small-scale problems such as loop kernels, data structures and algorithms, and on keeping compilers from optimizing benchmarks away.","why":"HN recommends it as an eye-opening primer on benchmarking and performance analysis, especially for people who have not benchmarked on Linux.","type":"talk","level":"advanced","score":3.5,"topics":["Systems & performance"],"recs":3,"years":[2015,2020],"quote":"Optimizing the Emergent Structures of C++","quote_url":"https://news.ycombinator.com/item?id=11721276","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('otAcmD6XEEE','hn',3.5,'{"vid":"otAcmD6XEEE","title":"Procedural Programming: It Never Went Away — Kevlin Henney | Build Stuff","channel":"Build Stuff - #1 Software Dev Conf","summary":"Kevlin Henney argues that procedural programming never went away despite later paradigms such as OO and functional. He traces the history of structured programming and shows where procedural thinking still lives in modern code and why it matters for readability.","why":"HN people recommend it as a fascinating history lesson showing that the field keeps rediscovering ideas from the 1960s.","type":"talk","level":"intermediate","score":3.5,"topics":["Software design & craft","Languages & compilers"],"recs":2,"years":[2018,2021],"quote":"tour of how all the best discoveries of the past decade or two really date back to the 1960s","quote_url":"https://news.ycombinator.com/item?id=16891353","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('p8u_k2LIZyo','hn',3.5,'{"vid":"p8u_k2LIZyo","title":"Fast Inverse Square Root — A Quake III Algorithm","channel":"Nemean","summary":"A walkthrough of the Quake III fast inverse square root, explaining where the constant 0x5f3759df comes from. It covers IEEE 754 floats, the bit hack that approximates a logarithm, and a Newton''s method refinement.","why":"HN recommends it as an approachable explanation that makes the famous algorithm finally make sense.","type":"explainer","level":"intermediate","score":3.5,"topics":["DSA","Systems & performance"],"recs":3,"years":[2021,2022],"quote":"This video is approachable and explains it pretty well","quote_url":"https://news.ycombinator.com/item?id=28452935","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pO4_Wlq8JeI','hn',3.5,'{"vid":"pO4_Wlq8JeI","title":"Solid Ground // Saša Jurić","channel":"EMPEX Conference","summary":"Sasa Juric''s EMPEX talk demonstrates Elixir and Erlang''s process model and what makes the BEAM runtime distinctive, such as fault-tolerant parallelism by design.","why":"Recommended as the best short overview of why the BEAM and Elixir stand apart from other runtimes.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers","Databases & distributed"],"recs":3,"years":[2017,2023],"quote":"It perfectly articulates what sets Erlang/BEAM/Elixir apart from other runtimes/languages.","quote_url":"https://news.ycombinator.com/item?id=37419112","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rCMh7srOqvw','hn',3.5,'{"vid":"rCMh7srOqvw","title":"Emacs Doom Episode 1 - Getting Started","channel":"Zaiste Programming","summary":"A short first episode in Zaiste''s Doom Emacs series, showing how to get started with Doom, an Emacs configuration aimed at Vim users. It presents Doom as a polished, fast, batteries-included distribution.","why":"HN users recommend the series to newcomers learning Emacs, Doom, org-mode, projectile and magit.","type":"tutorial","level":"intro","score":3.5,"topics":["Software design & craft"],"recs":3,"years":[2019,2020],"quote":"To get started I highly recommend this series by Zaiste","quote_url":"https://news.ycombinator.com/item?id=22885570","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sBzRwzY7G-k','hn',3.5,'{"vid":"sBzRwzY7G-k","title":"2016/2017 MUST-KNOW WEB DEVELOPMENT TECH - Watch this if you want to be a web developer","channel":"LearnCode.academy","summary":"LearnCode.academy presents a roadmap of web development technologies to learn in 2016 and 2017, spanning front-end, back-end and DevOps tools.","why":"Recommended to beginners asking how to start in web development as a compact survey of the toolscape of its time.","type":"explainer","level":"intro","score":3.5,"topics":["Web"],"recs":3,"years":[2016,2017],"quote":"Watch this brilliant video, I think the author nailed it","quote_url":"https://news.ycombinator.com/item?id=12759270","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('tKTZoB2Vjuk','hn',3.5,'{"vid":"tKTZoB2Vjuk","title":"Google Python Class Day 1 Part 1","channel":"Google for Developers","summary":"The first part of Google''s Python Class, taught by Nick Parlante, introducing the language and its strings. It is aimed at people with some programming familiarity and comes with exercises.","why":"HN recommends it as a fast, accessible way to start learning Python.","type":"course","level":"intro","score":3.5,"topics":["Python","Languages & compilers"],"recs":3,"years":[2011,2018],"quote":"recommend it to anybody that thinks they need to learn programming","quote_url":"https://news.ycombinator.com/item?id=16531423","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('uZgbKrDEzAs','hn',3.5,'{"vid":"uZgbKrDEzAs","title":"#Gamelab2018 - Jon Blow''s Design decisions on creating Jai a new language for game programmers","channel":"Gamelab Conference","summary":"Jonathan Blow talks at Gamelab 2018 about the design decisions behind Jai, the programming language he is building for game programmers. He covers low-friction development, quality of life and the effects of compile times.","why":"Recommended for a substantive look at language design priorities and a critique of why modern programming feels broken.","type":"talk","level":"advanced","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2018,2023],"quote":"I recently watched this talk by Johnathan Blow[0] where he talks about quality of life in programming languages and spends a fair amount of time talking about compile times and their effects.","quote_url":"https://news.ycombinator.com/item?id=23595791","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('x7drE24geUw','hn',3.5,'{"vid":"x7drE24geUw","title":"CRDTs: The Hard Parts","channel":"Martin Kleppmann","summary":"Martin Kleppmann surveys current research on CRDTs, the algorithms for merging concurrent edits across offline replicas. He covers the hard parts such as rich text, moves and merge results that are technically correct but poor.","why":"Recommended as an excellent first education on CRDTs and their limits.","type":"talk","level":"intermediate","score":3.5,"topics":["Databases & distributed","DSA"],"recs":3,"years":[2020,2024],"quote":"I found this video from him to be an excellent first education on CRDTs","quote_url":"https://news.ycombinator.com/item?id=25776341","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xNzoerDljjo','hn',3.5,'{"vid":"xNzoerDljjo","title":"Saša Jurić - Parsing from first principles - WebCamp Zagreb 2019","channel":"WebCamp Zagreb","summary":"Sasa Juric explains how to parse a language from first principles without regexes, live-coding a simple parser combinator library in Elixir. It was given at WebCamp Zagreb 2019.","why":"HN commenters recommend it as a clear, dense hour on parsers and parser combinators that holds the audience.","type":"talk","level":"intermediate","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2019,2021],"quote":"Saša Jurić is fantastic at condensing lots of information in a 1 hour talk without losing the audience","quote_url":"https://news.ycombinator.com/item?id=21862856","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xi1Lq79mLeE','hn',3.5,'{"vid":"xi1Lq79mLeE","title":"The Mind Behind Windows: Dave Cutler","channel":"Dave''s Garage","summary":"Dave Plummer interviews Dave Cutler, architect of VMS and Windows NT, in a roughly three-hour conversation about his career and the history of Windows.","why":"Recommended as a long, excellent first-hand interview with a legendary OS designer, though some note it is light on technical detail.","type":"interview","level":"general","score":3.5,"topics":["Systems & performance"],"recs":4,"years":[2023,2026],"quote":"there is an excellent 3 hour long interview with Dave Cutler on that channel.","quote_url":"https://news.ycombinator.com/item?id=38450108","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('yvDCzhbjYWs','hn',3.5,'{"vid":"yvDCzhbjYWs","title":"Peter Norvig - The Unreasonable Effectiveness of Data","channel":"UBC Computer Science","summary":"Peter Norvig''s UBC distinguished lecture on how massive amounts of simple data, such as for language modeling, can yield understanding that hand-built models could not.","why":"Recommended as a favorite tech talk showing how huge data availability changes how problems are approached.","type":"lecture","level":"intermediate","score":3.5,"topics":["AI & ML","LLMs"],"recs":3,"years":[2012,2026],"quote":"Norvig does an especially great job in making you truly appreciate the seismic impact that the availability of massive quantities of data can have","quote_url":"https://news.ycombinator.com/item?id=12640863","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('z8MVKianh54','hn',3.5,'{"vid":"z8MVKianh54","title":"Does APL Need a Type System? by Aaron W Hsu at #FnConf18","channel":"ConfEngine","summary":"Aaron Hsu''s FnConf18 talk asks whether APL needs a static type system. He argues that APL''s expressiveness and rapid iteration already deliver the benefits usually credited to types.","why":"HN points to it as the main argument from the array-language camp that types are unnecessary there, and as a nuanced take on typed versus untyped programming.","type":"talk","level":"advanced","score":3.5,"topics":["Languages & compilers"],"recs":3,"years":[2019,2025],"quote":"which argues that APL already provides the development ergonomics that are typically acribed to type systems.","quote_url":"https://news.ycombinator.com/item?id=21373433","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zZ_nI9E9g0I','hn',3.5,'{"vid":"zZ_nI9E9g0I","title":"Redoing Make - Haskell from Scratch #1","channel":"jekor","summary":"The first episode of a screencast series building djb''s redo build system from scratch in Haskell. It explains the purpose of redo, writes initial code and sets up a GitHub repository.","why":"Recommended to Haskell learners as a rare example of building a real program step by step beyond toy examples.","type":"tutorial","level":"intermediate","score":3.5,"topics":["Languages & compilers","Software design & craft"],"recs":3,"years":[2014,2021],"quote":"the Jekor Redo [1] videos are fantastic, and demonstrate the slow building up of more complicated things than \"reverse this string.","quote_url":"https://news.ycombinator.com/item?id=7199464","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('zeLToGnjIUM','hn',3.5,'{"vid":"zeLToGnjIUM","title":"Modeling Data Concurrency w/ Asynchronous I/O in Zig - RedisConf 2020","channel":"Redis","summary":"Zig creator Andrew Kelley''s RedisConf 2020 talk on modeling data flow with asynchronous I/O in Zig. It explains how Zig''s async/await avoids function coloring, and Loris Cro demonstrates OkRedis, a zero-allocation Redis client.","why":"HN recommends it as the clearest explanation of how Zig achieves colorless async/await.","type":"talk","level":"intermediate","score":3.5,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2020,2021],"quote":"I highly recommend watching Andrew Kelley''s video","quote_url":"https://news.ycombinator.com/item?id=26941390","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ztspvPYybIY','hn',3.5,'{"vid":"ztspvPYybIY","title":"Ryan Dahl: Original Node.js presentation","channel":"stri8ted","summary":"Ryan Dahl''s first presentation of Node.js at JSConf 2009. He pitches event-driven, non-blocking I/O as the motivation, rather than JavaScript itself.","why":"HN recommends it as a classic dev tool pitch with palpable energy, and cites it for why Node was created.","type":"talk","level":"intermediate","score":3.5,"topics":["Web"],"recs":3,"years":[2016,2023],"quote":"There is a sort of palpable energy in (Ryan Dahl) node.js original presentation.","quote_url":"https://news.ycombinator.com/item?id=12638469","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('0rSMt1pAlbE','hn',3.0,'{"vid":"0rSMt1pAlbE","title":"Clasp: Common Lisp using LLVM and C++ for Designing Molecules","channel":"Google TechTalks","summary":"Christian Schafmeister''s Google Tech Talk on Clasp and CANDO, a Common Lisp implementation on LLVM and C++ used to design molecules, including energy minimization and force-field calculations.","why":"Held up in Lisp threads as a striking example of Lisp powering cutting-edge science.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers"],"recs":2,"years":[2016,2022],"quote":"I challenge anyone to watch this lecture from Christian Schafmeister and say they are not impressed","quote_url":"https://news.ycombinator.com/item?id=11175151","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('0vJJlVBVTFg','hn',3.0,'{"vid":"0vJJlVBVTFg","title":"Google Developers Day US - Python Design Patterns","channel":"GoogleDeveloperDay","summary":"Alex Martelli''s Google Developers Day talk on classic design patterns (creational, structural and behavioral) and how they appear in Python. He stresses that patterns must be studied in the context of the implementing language.","why":"HN commenters recommend it as a level-headed, practical take on design patterns without Java-style verbosity.","type":"talk","level":"intermediate","score":3.0,"topics":["Python","Software design & craft","Languages & compilers"],"recs":2,"years":[2011,2020],"quote":"I found Alex Martinelli''s talk on design patterns very level-headed and instructive","quote_url":"https://news.ycombinator.com/item?id=12851370","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('1OEu9C51K2A','hn',3.0,'{"vid":"1OEu9C51K2A","title":"CppCon 2015: Bjarne Stroustrup “Writing Good C++14”","channel":"CppCon","summary":"Bjarne Stroustrup''s CppCon 2015 keynote on using C++14 to write better code, not just different code. It introduces the C++ Core Guidelines and the machine-checkable rules and GSL library behind them.","why":"HN people recommend it as the starting point for modern C++ and for the language''s safety story.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance"],"recs":2,"years":[2016,2018],"quote":"If you want to start with modern c++ watch this","quote_url":"https://news.ycombinator.com/item?id=11799865","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3DtUzH3zoFo','hn',3.0,'{"vid":"3DtUzH3zoFo","title":"Origins of Go Concurrency style by Rob Pike","channel":"jasonofthel33t","summary":"Rob Pike''s 2010 talk at OSCON''s Emerging Languages Camp on where Go''s concurrency style comes from. It traces the idea from Hoare''s CSP through Squeak, Newsqueak and Limbo to Go.","why":"HN recommends it as the clearest account of the CSP lineage behind Go''s goroutines and channels.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2013,2025],"quote":"Check out this video by Pike","quote_url":"https://news.ycombinator.com/item?id=19020539","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3HxVMGaiZbc','hn',3.0,'{"vid":"3HxVMGaiZbc","title":"ClojureScript in the Age of TypeScript — David Nolen","channel":"ChariotSolutions","summary":"David Nolen explains how ClojureScript is used at Vouch.io to build mobile and web software with a single language and REPL-driven workflow. The talk includes a live coding demo of React Native development.","why":"Pointed to as a concrete demonstration of REPL-driven development and ClojureScript with React Native.","type":"talk","level":"intermediate","score":3.0,"topics":["Languages & compilers","Web"],"recs":3,"years":[2021,2022],"quote":"David Nolen gave a relevant talk[0] about the workflow they use to integrate Clojure and React Native for mobile and web development","quote_url":"https://news.ycombinator.com/item?id=32518837","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3Y2weLDiUWw','hn',3.0,'{"vid":"3Y2weLDiUWw","title":"17. Succinct Structures I","channel":"MIT OpenCourseWare","summary":"Erik Demaine''s MIT 6.851 Advanced Data Structures lecture introducing succinct data structures, covering rank, select and tries. It is part of the Spring 2012 course.","why":"HN recommends it as a clear, high-quality introduction to succinct data structures from a leading authority.","type":"lecture","level":"advanced","score":3.0,"topics":["DSA"],"recs":3,"years":[2018,2022],"quote":"Erik Demaine [1] gave two good lectures on succinct data structures [2] in the 2012 MIT 6.851 Advanced Data Structures course","quote_url":"https://news.ycombinator.com/item?id=18208110","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4AfRAVcThyA','hn',3.0,'{"vid":"4AfRAVcThyA","title":"CppCon 2017: Herb Sutter “Meta: Thoughts on generative C++”","channel":"CppCon","summary":"At CppCon 2017 Herb Sutter presents his work on evolving C++ through compile-time code generation, including metaclasses and reflection. The aim is to make the language both more powerful and simpler by letting programmers express intent directly.","why":"Praised as the best talk of CppCon 2017 and the key introduction to metaclasses and generative C++.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":2,"years":[2017,2020],"quote":"Herb Sutter''s talk about it is by far the best talk I''ve seen from from CppCon17.","quote_url":"https://news.ycombinator.com/item?id=15548269","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4F72VULWFvc','hn',3.0,'{"vid":"4F72VULWFvc","title":"\"The Clean Code Talks  -- Inheritance, Polymorphism, & Testing\"","channel":"Google TechTalks","summary":"Misko Hevery''s Clean Code Talk shows how to use object-oriented techniques such as polymorphism to remove repeated if and switch statements. The result is code that is easier to test, understand and maintain.","why":"HN commenters recommend it as a thorough treatment of replacing conditionals with polymorphism and why flags and deep ifs can be code smells.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft"],"recs":3,"years":[2009,2023],"quote":"This talk gives a great overview of why boolean flags (rather, if-statements) can be a code smell","quote_url":"https://news.ycombinator.com/item?id=31464312","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4HgShra-KnY','hn',3.0,'{"vid":"4HgShra-KnY","title":"ASPLOS Keynote: The Golden Age of Compiler Design in an Era of HW/SW Co-design by Dr. Chris Lattner","channel":"SiFive","summary":"Chris Lattner''s ASPLOS 2021 keynote on the golden age of compiler design in an era of hardware and software co-design, covering compiler infrastructure for accelerators and unifying hardware IRs.","why":"Recommended for explaining where the compiler ecosystem lacks standardization for accelerators and why efforts like MLIR and CIRCT matter.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2021,2021],"quote":"I watched Chris Lattner''s ASPLOS talk and it finally clicked.","quote_url":"https://news.ycombinator.com/item?id=27017940","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5Q9x16uIsKA','hn',3.0,'{"vid":"5Q9x16uIsKA","title":"miniKanren - Dan Friedman and William Byrd","channel":"ClojureTV","summary":"Dan Friedman and William Byrd demonstrate miniKanren, a logic programming system for Scheme, in an unconference talk. It includes generating programs by running relations in reverse.","why":"HN recommends it as a mind-blowing and fun introduction to logic programming for working programmers.","type":"talk","level":"intro","score":3.0,"topics":["Languages & compilers"],"recs":2,"years":[2013,2018],"quote":"I highly recommend watching Dan Friedman and William Byrd give their miniKanren conference talk","quote_url":"https://news.ycombinator.com/item?id=17959353","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5kj5ApnhPAE','hn',3.0,'{"vid":"5kj5ApnhPAE","title":"OSCON 2010:  Rob Pike, \"Public Static Void\"","channel":"O''Reilly","summary":"A 13-minute OSCON 2010 talk in which Rob Pike argues about what is wrong with mainstream languages like C++, Java and C#, and presents Go as a response. He discusses verbosity and what lightness means in a language.","why":"HN uses it as a concise statement of the thinking behind Go''s design.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2012,2023],"quote":"gave this short speech at OSCON 2010 about what''s wrong with programming languages, their thinking, and their recent direction","quote_url":"https://news.ycombinator.com/item?id=7859879","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7kVeCqQCxlk','hn',3.0,'{"vid":"7kVeCqQCxlk","title":"CSS Grid Changes EVERYTHING - Amazing Presentation","channel":"Coding Tech","summary":"Morten Rand-Hendriksen''s WordCamp Europe 2017 talk presents CSS Grid Layout as a native two-dimensional layout system that changes how web pages are structured, including responsive layouts independent of source order. It was given as browsers began shipping support.","why":"HN commenters recommend it as an inspiring demonstration of how powerful CSS Grid is and how it repairs the relationship between HTML and CSS.","type":"talk","level":"intermediate","score":3.0,"topics":["Web"],"recs":4,"years":[2018,2019],"quote":"The speaker is good but I think I like it just because it fixes the relationship between HTML and CSS.","quote_url":"https://news.ycombinator.com/item?id=16839563","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9syvZr-9xwk','hn',3.0,'{"vid":"9syvZr-9xwk","title":"1. Introduction, Finite Automata, Regular Expressions","channel":"MIT OpenCourseWare","summary":"The first lecture of Michael Sipser''s MIT 18.404J Theory of Computation course, covering course mechanics, finite automata, regular languages and regular expressions. It proves closure of regular languages under union and begins concatenation.","why":"HN recommends Sipser''s free lectures as the companion to the standard theory of computation textbook and a path to understanding how computers fundamentally work.","type":"lecture","level":"intro","score":3.0,"topics":["Math & theory"],"recs":4,"years":[2021,2025],"quote":"Sipser also has corresponding lectures that are available for free on YouTube here","quote_url":"https://news.ycombinator.com/item?id=40797438","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('BCiZc0n6COY','hn',3.0,'{"vid":"BCiZc0n6COY","title":"Lecture 1: Introduction to Information Theory","channel":"Jakob Foerster","summary":"The first lecture of David MacKay''s Cambridge course on information theory, pattern recognition and neural networks. It introduces the core ideas of his book Information Theory, Inference, and Learning Algorithms.","why":"Recommended as an enjoyable, clear introduction to information theory that pairs well with MacKay''s free textbook.","type":"lecture","level":"intro","score":3.0,"topics":["Math for ML"],"recs":3,"years":[2018,2024],"quote":"It was very enjoyable for me to learn the material from his lectures.","quote_url":"https://news.ycombinator.com/item?id=23486218","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('BTHvs3V8DBA','hn',3.0,'{"vid":"BTHvs3V8DBA","title":"High Performance Web Sites and YSlow","channel":"Google TechTalks","summary":"A Google Tech Talk on Yahoo''s 14 rules for faster web pages and the YSlow tool. It covers front-end practices like avoiding @import and fixing ETags, with live analysis of popular sites.","why":"Praised as solid, research-backed advice on front-end web performance.","type":"talk","level":"intermediate","score":3.0,"topics":["Web","Systems & performance"],"recs":2,"years":[2009,2009],"quote":"Everything they produce about the subject (and I don''t just mean the plugin) is solid gold.","quote_url":"https://news.ycombinator.com/item?id=724417","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('F8sZRBdmqc0','hn',3.0,'{"vid":"F8sZRBdmqc0","title":"Bryan Cantrill on ARC: A Self-Tuning, Low Overhead Replacement Cache [PWL SF] 10/2017","channel":"PapersWeLove","summary":"Bryan Cantrill presents the ARC (Adaptive Replacement Cache) paper by Megiddo and Modha at Papers We Love. He opens with a survey of caching strategies before digging into the self-tuning LRU/MFU design.","why":"Recommended in cache-algorithm threads as a fun, informative walk through caching strategies and ARC.","type":"talk","level":"intermediate","score":3.0,"topics":["DSA","Databases & distributed"],"recs":3,"years":[2019,2024],"quote":"Bryan Cantrill does a pretty good survey of caching strategies in the intro","quote_url":"https://news.ycombinator.com/item?id=26673880","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HStF1RJOyxI','hn',3.0,'{"vid":"HStF1RJOyxI","title":"Making R run Fast - Jan Vitek","channel":"John O''Neill","summary":"Jan Vitek of Northeastern University gives a meetup talk on the challenges of making the R language run fast. He explains what in R''s semantics makes it hard to optimize and to build a JIT compiler for.","why":"HN points to it as the best explanation of why R is so hard to optimize, often paired with talks on Python and used to explain what makes Julia fast.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers","Systems & performance"],"recs":3,"years":[2017,2023],"quote":"Another talk on the difficulty of optimising R is this fantastic one by Jan Vitek","quote_url":"https://news.ycombinator.com/item?id=14801954","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Ie-gqwSHQr0','hn',3.0,'{"vid":"Ie-gqwSHQr0","title":"\"Building a Toolkit for Design\" by Matthew Griffith","channel":"elm-conf","summary":"Matthew Griffith, creator of elm-ui, presents a toolkit for designing layouts in Elm as an alternative to CSS. He explains the opinionated approach to layout and styling.","why":"HN commenters recommend it as a fresh perspective on layout and styling in CSS discussions.","type":"talk","level":"intermediate","score":3.0,"topics":["Web","Languages & compilers"],"recs":2,"years":[2020,2022],"quote":"For those who want a fresh perspective on CSS, layout and styling, check out this talk by Matthew Griffith","quote_url":"https://news.ycombinator.com/item?id=27366787","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Iq9DzN6mvYA','hn',3.0,'{"vid":"Iq9DzN6mvYA","title":"Jake Vanderplas - Statistics for Hackers - PyCon 2016.mp4","channel":"PyCon 2016","summary":"Jake Vanderplas''s PyCon 2016 talk shows how sampling-based methods such as simulation, shuffling and bootstrapping make statistics intuitive. His pitch is that if you can write a for-loop, you can do statistics.","why":"It is recommended to programmers who want to learn statistics through simulation rather than memorized formulas.","type":"talk","level":"intro","score":3.0,"topics":["Python","AI & ML","Languages & compilers"],"recs":3,"years":[2017,2025],"quote":"The presenters advocate using simulation/bootstrapping/shuffling methods instead of memorizing formulas.","quote_url":"https://news.ycombinator.com/item?id=43356510","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KINIAgRpkDA','hn',3.0,'{"vid":"KINIAgRpkDA","title":"GopherCon 2016: The Design of the Go Assembler - Rob Pike","channel":"Gopher Academy","summary":"Rob Pike''s GopherCon 2016 talk on the design of the Go assembler, explaining why Go uses a common assembly language translated to each architecture.","why":"HN points to it for background on how the Go toolchain targets many architectures and why its assembler is designed that way.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2017,2025],"quote":"Its Rob Pike talking about the go assembler and he answers a few of your questions.","quote_url":"https://news.ycombinator.com/item?id=15177402","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('KeLBd2EJLOU','hn',3.0,'{"vid":"KeLBd2EJLOU","title":"C++ and Beyond 2012: Herb Sutter - atomic Weapons 2 of 2","channel":"alexsmail","summary":"Part two of Herb Sutter''s C++ and Beyond 2012 session on atomic weapons, a deep dive into the C++ memory model, atomics, memory ordering, and hardware behavior. It ends with the modern meaning of volatile.","why":"HN recommends it as an in-depth, practical introduction to atomics and weak versus strong memory ordering, relevant to ARM and Rust as well as C++.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance"],"recs":2,"years":[2019,2024],"quote":"For a more in depth introduction to the topic with a lot of practical code examples, I highly recommend","quote_url":"https://news.ycombinator.com/item?id=38449565","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('LwicN2u6Dro','hn',3.0,'{"vid":"LwicN2u6Dro","title":"\"Liberating the Smalltalk lurking in C and Unix\" by Stephen Kell","channel":"Strange Loop Conference","summary":"Stephen Kell''s Strange Loop talk argues that C and Unix already contain Smalltalk-like dynamism and introspection that can be exposed. He presents his liballocs research on bridging dynamic and compiled languages.","why":"HN commenters recommend it in Smalltalk and Unix threads as a demonstration of runtime dynamism hiding in native binaries and shared libraries.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers","Systems & performance"],"recs":2,"years":[2016,2023],"quote":"there''s a great video of one of his talks","quote_url":"https://news.ycombinator.com/item?id=23879540","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('N9RUqGYuGfw','hn',3.0,'{"vid":"N9RUqGYuGfw","title":"JSON Parser 100% From Scratch in Haskell (only 111 lines)","channel":"Tsoding","summary":"Tsoding live-codes a JSON parser from scratch in Haskell in about 111 lines, using only the standard library. It is an edited Twitch stream that explains the intuition behind parser combinators, functors, applicatives and monads.","why":"HN recommends it as a hands-on way to understand Haskell and parser combinators by watching a parser get built live.","type":"tutorial","level":"intermediate","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2020,2022],"quote":"this guy writes a json parser live, giving his intuition along the way. It''s helped me immensely.","quote_url":"https://news.ycombinator.com/item?id=23961926","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OyFJWRnt_AY','hn',3.0,'{"vid":"OyFJWRnt_AY","title":"CS480/680 Lecture 19: Attention and Transformer Networks","channel":"Pascal Poupart","summary":"A university lecture from CS480/680 by Pascal Poupart on attention mechanisms and transformer networks, worked through on a chalkboard.","why":"HN recommends it to newcomers as a clear explanation of attention, including the query/key/value intuition.","type":"lecture","level":"intermediate","score":3.0,"topics":["AI & ML","LLMs"],"recs":3,"years":[2023,2023],"quote":"I would also recommend Pascal Poupart''s talk [1] on Attention and Transformers.","quote_url":"https://news.ycombinator.com/item?id=35723748","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('PaCmpygFfXo','hn',3.0,'{"vid":"PaCmpygFfXo","title":"The spelled-out intro to language modeling: building makemore","channel":"Andrej Karpathy","summary":"Andrej Karpathy builds a bigram character-level language model from scratch, introducing torch.Tensor and the framework of training, sampling and loss evaluation. It is the first step toward a GPT-style Transformer in his makemore series.","why":"HN recommends it as a long but worthwhile way to demystify how language models work technically.","type":"tutorial","level":"intro","score":3.0,"topics":["Karpathy","AI & ML","LLMs"],"recs":2,"years":[2024,2024],"quote":"It''s long (2h), but well worth the time if anyone is curious about the technical workings of LLMs.","quote_url":"https://news.ycombinator.com/item?id=39224425","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QpAhX-gsHMs','hn',3.0,'{"vid":"QpAhX-gsHMs","title":"Modern C and What We Can Learn From It - Luca Sas [ ACCU 2021 ]","channel":"ACCU Conference","summary":"Luca Sas''s ACCU 2021 talk on Modern C, a style of C and C-like C++ aligned with data-oriented design. It covers centralized memory management, zero-is-initialization, error handling and API design.","why":"HN recommends it as a good overview of modern C patterns, including in threads about learning C.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance","Software design & craft"],"recs":3,"years":[2021,2022],"quote":"This video gives a good overview of some modern patterns in C","quote_url":"https://news.ycombinator.com/item?id=34106582","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('S2Hp_1jqpY8','hn',3.0,'{"vid":"S2Hp_1jqpY8","title":"Differential Synchronization","channel":"Google TechTalks","summary":"Neil Fraser of Google presents Differential Synchronization, the algorithm behind MobWrite, for keeping multiple copies of a document in sync in real time. The talk argues the approach is robust, convergent and efficient.","why":"HN points to it as a simple diff-and-patch alternative to operational transforms and CRDTs for collaborative editing.","type":"talk","level":"intermediate","score":3.0,"topics":["Databases & distributed","DSA"],"recs":3,"years":[2012,2020],"quote":"The really nice bits, though, are that it is a simple algorithm","quote_url":"https://news.ycombinator.com/item?id=7905216","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SAc0vQCC6UQ','hn',3.0,'{"vid":"SAc0vQCC6UQ","title":"Ryan Dahl - History of Node.js","channel":"phxtagsoup","summary":"Ryan Dahl tells the history of Node.js and why he created it at a Phoenix meetup. He explains the push for non-blocking IO on a clean slate rather than extending an existing ecosystem.","why":"HN recommends it as the creator''s own account of why Node was built and how he thinks about humility.","type":"talk","level":"intermediate","score":3.0,"topics":["Web"],"recs":3,"years":[2011,2013],"quote":"He didn''t want to use an ecosystem that had existing blocking code.","quote_url":"https://news.ycombinator.com/item?id=3983911","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SKtQgFBRUvQ','hn',3.0,'{"vid":"SKtQgFBRUvQ","title":"RustConf 2016 - A Modern Editor Built in Rust by Raph Levien","channel":"Confreaks","summary":"Raph Levien presents Xi editor at RustConf 2016, a high-performance text editor built in Rust. The talk goes into technical details, building polished GUI apps, and running a community-focused open source project.","why":"HN lists it among good resources on building text editors and as a recommended lunch-and-learn talk.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Software design & craft"],"recs":4,"years":[2016,2018],"quote":"So far I''ve found and enjoyed reading/watching the resources below","quote_url":"https://news.ycombinator.com/item?id=12832111","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SrKj4hYic5A','hn',3.0,'{"vid":"SrKj4hYic5A","title":"\"Programming Should Eat Itself\" by Nada Amin","channel":"Strange Loop Conference","summary":"Nada Amin''s Strange Loop talk on programming languages that build on themselves, centered on towers of interpreters and nestable interpretation in Scheme. She shows how interpreters can be stacked and collapsed.","why":"HN recommends it as a quick, wonderful look at infinite towers of interpreters and what they make possible.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2015,2024],"quote":"Here''s a wonderful demonstration of the power of nestability","quote_url":"https://news.ycombinator.com/item?id=18745511","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SzA2YODtgK4','hn',3.0,'{"vid":"SzA2YODtgK4","title":"Getting Started With Org Mode","channel":"thoughtbot","summary":"Harry Schwartz gives a roughly hour-long tour of Emacs Org mode as an outliner, task manager, markup language and agenda tool. He demonstrates how he uses it for documents, presentations and todo lists.","why":"Recommended as a thorough introduction showing what Org mode can do for personal organization.","type":"tutorial","level":"intro","score":3.0,"topics":["Software design & craft"],"recs":3,"years":[2018,2022],"quote":"which is a great demonstration on Emacs and Org Mode''s potential as an organizational tool.","quote_url":"https://news.ycombinator.com/item?id=34056717","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Uv1UfLPK7_Q','hn',3.0,'{"vid":"Uv1UfLPK7_Q","title":"Joe Armstrong & Jeremy Ruston - Intertwingling the Tiddlywiki with Erlang | Code Mesh LDN 18","channel":"Code Sync","summary":"Joe Armstrong, creator of Erlang, and Jeremy Ruston, creator of TiddlyWiki, discuss hypertext, Ted Nelson''s idea of intertwingled knowledge, and a way to combine TiddlyWiki with Erlang. It is a Code Mesh LDN 2018 talk.","why":"Recommended in note-taking and personal wiki threads for its enthusiasm about granular, densely linked notes and TiddlyWiki.","type":"talk","level":"intro","score":3.0,"topics":["Languages & compilers"],"recs":2,"years":[2020,2024],"quote":"great talk by its creator Jeremy Ruston and the late creator of Erlang, Joe Armstrong","quote_url":"https://news.ycombinator.com/item?id=24825096","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('W71BTkUbdqE','hn',3.0,'{"vid":"W71BTkUbdqE","title":"Why Google Stores Billions of Lines of Code in a Single Repository","channel":"@Scale","summary":"Rachel Potvin describes the scale of Google''s codebase and its custom monolithic source repository. She explains the reasons for the monorepo model, the tooling that makes it workable, and its tradeoffs.","why":"The go-to reference in monorepo and trunk-based development discussions, recommended as a firsthand account of how Google manages source control.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft"],"recs":2,"years":[2016,2022],"quote":"I''d recommend this video that describes it.","quote_url":"https://news.ycombinator.com/item?id=13514652","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XJ9ckqCMiKk','hn',3.0,'{"vid":"XJ9ckqCMiKk","title":"Erlang Factory SF 2016 Keynote  Phoenix and Elm – Making the Web Functional","channel":"Erlang Solutions","summary":"A joint Erlang Factory 2016 keynote by Phoenix creator Chris McCord and Elm creator Evan Czaplicki on using the two together, including Phoenix.Presence design and PubSub optimizations.","why":"Pointed to as the best source on Phoenix Presence internals and for combining Phoenix with Elm.","type":"talk","level":"intermediate","score":3.0,"topics":["Languages & compilers","Web"],"recs":2,"years":[2016,2022],"quote":"My Erlang Factory keynote also goes into the design considerations and PubSub layer optimizations that sits underneath Phoenix.Presence","quote_url":"https://news.ycombinator.com/item?id=11361872","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('YdiZa0Y3F3c','hn',3.0,'{"vid":"YdiZa0Y3F3c","title":"Shared memory parallelism in Julia | Kiran Pamnany | Cambridge Julia Meetup (May 2018)","channel":"The Julia Programming Language","summary":"Kiran Pamnany''s Cambridge Julia Meetup talk on Julia''s shared memory parallelism and its new task scheduler. It argues that fork-join and work-stealing models nest poorly and presents depth-first scheduling for composable parallelism.","why":"Recommended in Julia threading threads as an insightful, simple explanation of the new task scheduler.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":4,"years":[2018,2019],"quote":"I found his talk to be an insightful overview of this work","quote_url":"https://news.ycombinator.com/item?id=18286534","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZQc9-seU-5k','hn',3.0,'{"vid":"ZQc9-seU-5k","title":"\"Swift as C++ Successor in FoundationDB\" by Konrad Malawski (Strange Loop 2023)","channel":"Strange Loop Conference","summary":"Konrad Malawski''s Strange Loop 2023 talk shows how the FoundationDB team adopted Swift incrementally in a C++ codebase. It covers Swift''s C++ interoperability, which let them move single functions or entire types over one at a time.","why":"HN commenters recommend it as the main resource on Swift as an incremental successor to C++ and on how the interoperability works in practice.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Databases & distributed"],"recs":3,"years":[2023,2025],"quote":"The fairly recent presentation about starting to move FoundationDB to Swift[0] was also very interesting.","quote_url":"https://news.ycombinator.com/item?id=41209294","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ZRV3pBuPxEQ','hn',3.0,'{"vid":"ZRV3pBuPxEQ","title":"PHP doesn''t suck (anymore)","channel":"Aaron Francis","summary":"Aaron Francis walks through how PHP has changed from 2012 to 2023, covering traits, array destructuring, generators, typed properties and more. It is a quick chaptered tour of modern PHP features.","why":"HN commenters share it to show that modern PHP is much better than its reputation.","type":"explainer","level":"intro","score":3.0,"topics":["Languages & compilers","Web"],"recs":3,"years":[2023,2024],"quote":"I was quite surprised to see how far PHP has come since I used it many years ago","quote_url":"https://news.ycombinator.com/item?id=38597216","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('b0EF0VTs9Dc','hn',3.0,'{"vid":"b0EF0VTs9Dc","title":"Monads and Gonads","channel":"Google TechTalks","summary":"Douglas Crockford''s Google Tech Talk explains monads without category theory or Haskell, implementing them in JavaScript and tying them to Ajax and promises. He also touches on odd asides such as coloring code by scope.","why":"Often recommended as a demystifying monad talk in plain JavaScript, though some find it light on definitions.","type":"talk","level":"intermediate","score":3.0,"topics":["Languages & compilers","Web"],"recs":2,"years":[2013,2022],"quote":"what I thought to be one of DC''s greatest talks","quote_url":"https://news.ycombinator.com/item?id=12423630","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('boPEO2auJj4','hn',3.0,'{"vid":"boPEO2auJj4","title":"CppCon 2015: Timur Doumler “C++ in the Audio Industry”","channel":"CppCon","summary":"Timur Doumler''s CppCon 2015 talk on how C++ is used in the audio industry. It covers the patterns and tools audio developers rely on, including handling real-time constraints.","why":"HN commenters recommend it as an introduction to real-time and low-latency programming in C++ for people getting into audio.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance"],"recs":3,"years":[2016,2026],"quote":"he goes through real time strategies to keep the response time under around 30ms IIRC","quote_url":"https://news.ycombinator.com/item?id=27275571","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('c1UBJbfR-H0','hn',3.0,'{"vid":"c1UBJbfR-H0","title":"\"Compacting the Uncompactable\" by Bobby Powers","channel":"Strange Loop Conference","summary":"Bobby Powers presents Mesh, a drop-in malloc replacement that eliminates memory fragmentation in unmodified C/C++ programs by compacting memory. The talk covers how it works despite C''s fixed object addresses, and its benefits for programs like Redis.","why":"Recommended as a great talk on solving fragmentation for C/C++ and runtimes like Ruby and Python without code changes.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance"],"recs":3,"years":[2020,2025],"quote":"There was a great talk at Strange Loop about a drop-in malloc replacement which compacts.","quote_url":"https://news.ycombinator.com/item?id=32283251","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gKWNjFagR9k','hn',3.0,'{"vid":"gKWNjFagR9k","title":"CUFP 2013: Julien Verlaguet, Facebook: Analyzing PHP statically","channel":"CUFP 2013","summary":"Julien Verlaguet of Facebook describes applying static analysis and type inference to a very large PHP codebase, using OCaml. The work led to the Hack language.","why":"Pointed to as the origin story of Hack and a real-world example of OCaml in production.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2013,2014],"quote":"Another cool one from CUFP this year is how Facebook is using OCaml to add incremental type inference to their vast PHP code base.","quote_url":"https://news.ycombinator.com/item?id=6712173","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ghtpJnrdgbo','hn',3.0,'{"vid":"ghtpJnrdgbo","title":"Richard Hipp - Git: Just Say No","channel":"southeastlinuxfest","summary":"SQLite author Richard Hipp''s talk at SouthEast LinuxFest criticizing Git''s workflow and introducing Fossil as an alternative. He lists Git enhancements and argues for keeping history intact.","why":"Recommended for the SQLite author''s reasoned case for a different approach to version control, and as an introduction to Fossil.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft","Databases & distributed"],"recs":3,"years":[2020,2021],"quote":"If the author of SQLite advances some arguments around the proper way of doing version management, I would advise to error on the side of caution and listen at least a second time.","quote_url":"https://news.ycombinator.com/item?id=27738825","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hzPd3umu78g','hn',3.0,'{"vid":"hzPd3umu78g","title":"High-performance Tree Wrangling, the APL Way // Aaron Hsu // Dyalog ''18","channel":"Dyalog User Meetings","summary":"Aaron Hsu shows how to manipulate and transform tree data in APL using arrays and inverted tables instead of pointers. He claims much smaller code, better performance and easier parallelisation.","why":"HN recommends it as a striking example of high-performance tree handling with array programming.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers","DSA"],"recs":3,"years":[2019,2021],"quote":"He has one talk (available on YouTube) about his approach to using arrays to working with tree structures in a high-performance way in APL","quote_url":"https://news.ycombinator.com/item?id=27401189","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('i1vbvikDiI8','hn',3.0,'{"vid":"i1vbvikDiI8","title":"The Joy of Programming in Jai - Part 1: Hello World","channel":"Nuno Afonso","summary":"The first part of a series on programming in Jai, Jonathan Blow''s in-development language. It covers compiling, writing hello world and using code from other files.","why":"Jai had no public release, so commenters point to this beta user''s videos as a way to see what the language is actually like.","type":"tutorial","level":"intro","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2020,2021],"quote":"One of the beta testers has published some more up to date videos with his language introduction and initial experience","quote_url":"https://news.ycombinator.com/item?id=22204143","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kb-m2fasdDY','hn',3.0,'{"vid":"kb-m2fasdDY","title":"What I Wish I Had Known Before Scaling Uber to 1000 Services • Matt Ranney • GOTO 2016","channel":"GOTO Conferences","summary":"Matt Ranney of Uber talks at GOTO Chicago 2016 about what Uber learned from growing past 1,000 production microservices. He covers regrets, sprawl and organizational effects.","why":"Often brought up as an honest account of microservice sprawl, including the fact that nobody at Uber knew exactly how many services existed.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft","Databases & distributed"],"recs":3,"years":[2016,2023],"quote":"I enjoyed that video","quote_url":"https://news.ycombinator.com/item?id=12626814","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lgivCGdmFrw','hn',3.0,'{"vid":"lgivCGdmFrw","title":"Introducing a Memory-Safe Successor Language in Large C++ Code Bases - John McCall - CppNow 2023","channel":"CppNow","summary":"John McCall of Apple''s Swift team presents at CppNow 2023 on introducing a memory-safe successor language into large C++ code bases. He argues incremental improvement of C++ hits hard limits and explains Swift''s C++ interoperability for gradual migration.","why":"Used as the primary source for Apple''s stated plan to make Swift its successor to C++ and for how interop supports gradual transition.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2023,2025],"quote":"Finaly a recent gem from CppNow 2023","quote_url":"https://news.ycombinator.com/item?id=37479190","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lnA9DMvHtfI','hn',3.0,'{"vid":"lnA9DMvHtfI","title":"Large Language Models from scratch","channel":"Graphics in 5 Minutes","summary":"A short cartoon explaining how language models like ChatGPT work, from autocomplete and conditional probabilities to neural networks, gradient descent and backpropagation. It shows how networks act as universal function approximators.","why":"HN recommends it as a quick, non-dumbed-down way to get up to speed on how LLMs are built.","type":"explainer","level":"intro","score":3.0,"topics":["AI & ML","LLMs"],"recs":3,"years":[2023,2024],"quote":"I highly recommend this video by Steve Seitz","quote_url":"https://news.ycombinator.com/item?id=35704811","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mHtdZgou0qU','hn',3.0,'{"vid":"mHtdZgou0qU","title":"Speed Up Your JavaScript","channel":"Google TechTalks","summary":"A 2009 Google Tech Talk by Nicholas Zakas on the hidden performance pitfalls of JavaScript. It covers what is fast and slow in the language and how to avoid common bottlenecks.","why":"Recommended as a classic JavaScript performance talk whose fundamentals about reflow and efficient code still apply.","type":"talk","level":"intermediate","score":3.0,"topics":["Systems & performance","Web"],"recs":3,"years":[2012,2025],"quote":"the fundamental ideas are still the same.","quote_url":"https://news.ycombinator.com/item?id=44654180","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oSmqbnhHp1c','hn',3.0,'{"vid":"oSmqbnhHp1c","title":"RacketCon 2013: Dan Liebgold - Racket on the Playstation 3? It''s Not What you Think!","channel":"Racket","summary":"Dan Liebgold of Naughty Dog gives a RacketCon 2013 keynote on using Racket in PlayStation 3 game development. He explains the Racket-based DSLs used for game data and scripting, which replaced the studio''s earlier GOAL-based toolchain.","why":"HN cites it whenever Lisp in games, Naughty Dog or Racket in production comes up, as the main first-hand account.","type":"talk","level":"intermediate","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2014,2022],"quote":"There''s a talk by one of the engine devs at RacketCon from a few years ago on youtube about how they use these DSLs","quote_url":"https://news.ycombinator.com/item?id=18904632","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('pdJQ8iVTwj8','hn',3.0,'{"vid":"pdJQ8iVTwj8","title":"Chris Lattner: Future of Programming and AI | Lex Fridman Podcast #381","channel":"Lex Fridman","summary":"Lex Fridman''s long podcast conversation with Chris Lattner, creator of Swift, LLVM and MLIR and co-founder of Modular. Topics include the Mojo language, the future of programming and AI, and hardware.","why":"HN points to it as the main place to hear Lattner''s motivations and design ideas for Mojo, often in Mojo threads.","type":"podcast","level":"intermediate","score":3.0,"topics":["Languages & compilers"],"recs":4,"years":[2023,2026],"quote":"further emboldened my stance that if Mojo can succeed, Lattner is one of the best-positioned engineers to see it through","quote_url":"https://news.ycombinator.com/item?id=36293296","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('qbKGw8MQ0i8','hn',3.0,'{"vid":"qbKGw8MQ0i8","title":"\"NTFS really isn''t that bad\" - Robert Collins (LCA 2020)","channel":"linux.conf.au","summary":"Robert Collins explains why rustup installs were painfully slow on Windows and how changes to rustup and Windows cut install time from 3m30s to 14s. The talk covers NTFS, small files and the cost of antivirus hooks on file close.","why":"The go-to reference for why file operations are slow on Windows and how antivirus filters, not NTFS itself, are the cause.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance"],"recs":5,"years":[2020,2025],"quote":"This is a great talk on the topic","quote_url":"https://news.ycombinator.com/item?id=41085991","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rAl-9HwD858','hn',3.0,'{"vid":"rAl-9HwD858","title":"Crust of Rust: Lifetime Annotations","channel":"Jon Gjengset","summary":"In this first Crust of Rust episode, Jon Gjengset live-codes an example that needs multiple explicit lifetime annotations. Along the way he covers string types and generics over a custom trait.","why":"Recommended as a slow-paced, detailed live-coding session that makes lifetimes click once you are past Rust basics.","type":"tutorial","level":"intermediate","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2020,2023],"quote":"each one is actually writing carefully chosen code that runs and talking through what''s going on","quote_url":"https://news.ycombinator.com/item?id=32928377","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rURRYI66E54','hn',3.0,'{"vid":"rURRYI66E54","title":"AI Language Models & Transformers - Computerphile","channel":"Computerphile","summary":"Rob Miles explains on Computerphile how language models generate plausible text and how transformers improved on recurrent networks, with a look at what comes next.","why":"Pointed to as an accessible early explanation of transformers and attention for newcomers.","type":"explainer","level":"intro","score":3.0,"topics":["AI & ML","LLMs"],"recs":3,"years":[2022,2025],"quote":"You can check-out his other videos on NLP as well they are all excellent.","quote_url":"https://news.ycombinator.com/item?id=35980149","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sCZJblyT_XM','hn',3.0,'{"vid":"sCZJblyT_XM","title":"The Unix Chainsaw - Gary Bernhardt","channel":"timmonta","summary":"Gary Bernhardt''s Cascadia Ruby Conference 2011 talk on using the Unix shell for practical problem solving. He builds pipelines interactively by iterative refinement, using small tools as levers.","why":"Recommended as a brilliant demonstration of how to think in Unix pipelines.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft","Systems & performance"],"recs":2,"years":[2016,2022],"quote":"gave a great talk about practical problem solving with the unix shell","quote_url":"https://news.ycombinator.com/item?id=19161505","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('t0mhvd3-60Y','hn',3.0,'{"vid":"t0mhvd3-60Y","title":"Simon Peyton Jones - Linear Haskell: practical linearity in a higher-order polymorphic language","channel":"Curry On!","summary":"Simon Peyton Jones presents linear types for Haskell, showing how practical linearity can fit into a higher-order polymorphic language. The talk covers motivations such as resource handling and relates the ideas to Rust.","why":"HN recommends it as a clear introduction to linear types in GHC from the language''s lead designer.","type":"talk","level":"advanced","score":3.0,"topics":["Languages & compilers"],"recs":3,"years":[2018,2020],"quote":"Simon Peyton Jones has a great talk on YouTube [3]","quote_url":"https://news.ycombinator.com/item?id=22712365","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('tAACYA1Mwv4','hn',3.0,'{"vid":"tAACYA1Mwv4","title":"Keynote: What is a Component (and Why)? - Luke Wagner, Distinguished Engineer, Fastly","channel":"The Linux Foundation","summary":"Luke Wagner of Fastly explains what a WebAssembly component is, how it relates to familiar concepts, and what the Component Model enables. It emphasizes security, composability and modularity.","why":"HN recommends it as the best starting point for understanding the Wasm Component Model and WASI direction, straight from its designer.","type":"talk","level":"intermediate","score":3.0,"topics":["Web","Software design & craft"],"recs":3,"years":[2024,2026],"quote":"I thought this keynote presentation[0] by Luke Wagner at Wasmcon was great and covered it very well.","quote_url":"https://news.ycombinator.com/item?id=39145871","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('tcdVC4e6EV4','hn',3.0,'{"vid":"tcdVC4e6EV4","title":"Deadly Truth of General AI? - Computerphile","channel":"Computerphile","summary":"A Computerphile video in which Rob Miles warns against assuming a general AI will think like a human. He uses the thought experiment of a stamp-collecting AI to show how a goal-driven system could pursue its aim with dangerous results.","why":"Often pointed to as an accessible first introduction to AI safety and why a superintelligent AI could be dangerous.","type":"explainer","level":"general","score":3.0,"topics":["AI & ML"],"recs":3,"years":[2016,2024],"quote":"There''s a great Computerphile video from 2015 that introduced me to the idea of AI safety awhile ago.","quote_url":"https://news.ycombinator.com/item?id=33962078","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vHWiDx_l4V0','hn',3.0,'{"vid":"vHWiDx_l4V0","title":"What''s a Memory Allocator Anyway? - Benjamin Feng","channel":"Zig SHOWTIME","summary":"A Zig SHOWTIME talk by Benjamin Feng on what a memory allocator is, followed by an interview. It covers allocation strategies and different allocator types in Zig.","why":"Recommended as a quick, clear overview of allocators and arenas that also shows how Zig approaches allocation.","type":"talk","level":"intro","score":3.0,"topics":["Systems & performance"],"recs":3,"years":[2020,2021],"quote":null,"quote_url":null,"source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vWkgEddb4-A','hn',3.0,'{"vid":"vWkgEddb4-A","title":"Introduction to Julia - Part 1 | SciPy 2014 | David Sanders","channel":"Enthought","summary":"David Sanders gives the first part of a two-part introduction to the Julia programming language at SciPy 2014. It walks through the language''s basics and its appeal for scientific computing.","why":"HN commenters point newcomers to it as a solid starting point for getting to know Julia.","type":"tutorial","level":"intro","score":3.0,"topics":["Python","Languages & compilers","AI & ML"],"recs":3,"years":[2014,2015],"quote":"I''ve found these talks useful as a starting point","quote_url":"https://news.ycombinator.com/item?id=10569645","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wTPGW1PNy_Y','hn',3.0,'{"vid":"wTPGW1PNy_Y","title":"How Modern SQL Databases Come up with Algorithms that You Would Have Never Dreamed Of by Lukas Eder","channel":"Devoxx","summary":"Lukas Eder''s Devoxx talk on how modern cost-based SQL optimizers rewrite and plan queries in ways developers would not expect. It argues that declarative SQL, used well, can run complex queries very fast.","why":"HN commenters recommend it to developers unfamiliar with how much leverage and intelligence there is in a SQL database.","type":"talk","level":"intermediate","score":3.0,"topics":["DSA","Databases & distributed"],"recs":3,"years":[2019,2023],"quote":"I''d suggest watching this video to get a flavor of how much leverage using the database can give you","quote_url":"https://news.ycombinator.com/item?id=30297604","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wlvKAT7SZIQ','hn',3.0,'{"vid":"wlvKAT7SZIQ","title":"Parsing JSON Really Quickly: Lessons Learned","channel":"InfoQ","summary":"Daniel Lemire''s QCon talk on how simdjson parses gigabytes of JSON per second. It covers SIMD vectorization, branch prediction and the lessons learned building a fast parser.","why":"HN points to it as the best explanation of simdjson internals and of why fast parsing is rarely disk-bound.","type":"talk","level":"advanced","score":3.0,"topics":["Systems & performance","Languages & compilers"],"recs":3,"years":[2020,2026],"quote":"It''s worth looking at if you''re into this sort of thing.","quote_url":"https://news.ycombinator.com/item?id=28738355","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('x2-rSnhpw0g','hn',3.0,'{"vid":"x2-rSnhpw0g","title":"Visualising software architecture with the C4 model - Simon Brown, Agile on the Beach 2019","channel":"Agile on the Beach","summary":"Simon Brown''s Agile on the Beach 2019 talk presents the C4 model, a lightweight approach to diagramming software architecture with a shared vocabulary and simple notation.","why":"Recommended as the introduction to C4 when people ask how to visualize and communicate software architecture.","type":"talk","level":"intro","score":3.0,"topics":["Software design & craft"],"recs":3,"years":[2021,2023],"quote":"If C4 is new to you too, I recommend their intro video","quote_url":"https://news.ycombinator.com/item?id=37230817","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('yy8jQgmhbAU','hn',3.0,'{"vid":"yy8jQgmhbAU","title":"CppCon 2018: Stoyan Nikolov “OOP Is Dead, Long Live Data-oriented Design”","channel":"CppCon","summary":"A CppCon 2018 talk arguing that OOP has failed to deliver on reuse and performance, and presenting data-oriented design for C++ with practical worked examples from real systems.","why":"HN cites it as a concrete, worked example of data-oriented design and as an alternative to OOP in performance-sensitive code.","type":"talk","level":"intermediate","score":3.0,"topics":["Software design & craft","Systems & performance"],"recs":3,"years":[2018,2021],"quote":"a more recent video on it from CppCon 2018 where the presenter goes over a specific worked example.","quote_url":"https://news.ycombinator.com/item?id=21676176","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-J8YyfrSwTk','hn',2.5,'{"vid":"-J8YyfrSwTk","title":"Effective ML","channel":"Jane Street","summary":"Yaron Minsky of Jane Street gave this talk to Harvard''s OCaml-based CS51 class in 2010. It collects advice on being an effective ML programmer in an industrial setting.","why":"It is the go-to source for the idea of making illegal states unrepresentable through types, with the key moment at 28:02.","type":"lecture","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2018,2021],"quote":"Richard Feldman dives deeper into the topic with a lot more examples in","quote_url":"https://news.ycombinator.com/item?id=18371870","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('0GzzFeS5cMc','hn',2.5,'{"vid":"0GzzFeS5cMc","title":"Zach Oakes - Making Games at Runtime with Clojure","channel":"ClojureTV","summary":"Zach Oakes explains why Clojure suits making games at runtime, so designers can experience their work as they build it. He combines abstract discussion with live demonstrations, drawing on his play-clj library and Nightmod tool.","why":"Recommended as a great talk on live, functional-style game programming.","type":"talk","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2015,2017],"quote":"here is his presentation on this subject at the last Conj (great talk)","quote_url":"https://news.ycombinator.com/item?id=8940734","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('0fpDlAEQio4','hn',2.5,'{"vid":"0fpDlAEQio4","title":"Four Languages from Forty Years Ago - Scott Wlaschin","channel":"NDC Conferences","summary":"Scott Wlaschin''s NDC Oslo talk on four 1970s languages, SQL, Prolog, ML and Smalltalk. It explains their philosophies and what practical principles they still offer modern developers.","why":"HN recommends it as a sampling of truly different programming paradigms beyond mainstream OOP.","type":"talk","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2019,2022],"quote":"Check out this fantastic talk by Scott Wlaschin to get a sampling of truly different language paradigms","quote_url":"https://news.ycombinator.com/item?id=22401834","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('0jI-AlWEwYI','hn',2.5,'{"vid":"0jI-AlWEwYI","title":"Alexis King -  “Effects for Less” @ ZuriHac 2020","channel":"Zürich Friends of Haskell","summary":"Alexis King''s ZuriHac 2020 talk on how effect systems in Haskell can be implemented efficiently. It looks at the performance cost of effect libraries and how to reduce it.","why":"HN commenters call it among the best talks of 2020 for understanding Haskell effect systems.","type":"talk","level":"advanced","score":2.5,"topics":["Languages & compilers","Systems & performance"],"recs":2,"years":[2020,2020],"quote":"the best one I did watch this year was Alexis King''s ''Effects for Less'' (Haskell).","quote_url":"https://news.ycombinator.com/item?id=25538018","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('8XUutFBbUrg','hn',2.5,'{"vid":"8XUutFBbUrg","title":"A Tour of Prolog","channel":"The Power of Prolog","summary":"Markus Triska tours Prolog''s most distinctive features, including its use as a database and query language, rule processing, constraint solving and compile-time rewriting. It also covers concise meta-interpreters.","why":"HN recommends it as the best short introduction to what makes Prolog unique.","type":"tutorial","level":"intro","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2022,2024],"quote":"check out this video introduction by Markus Triska about what makes Prolog unique","quote_url":"https://news.ycombinator.com/item?id=35624654","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('HZGCoVF3YvM','hn',2.5,'{"vid":"HZGCoVF3YvM","title":"Bayes theorem, the geometry of changing beliefs","channel":"3Blue1Brown","summary":"3Blue1Brown presents Bayes'' theorem through a geometric diagram, showing how evidence should update beliefs. It works through the Kahneman and Tversky style questions and base rates.","why":"HN people recommend it as the most intuitive introduction to Bayes'' theorem and cite it in base-rate arguments.","type":"explainer","level":"intro","score":2.5,"topics":["Math for ML"],"recs":2,"years":[2022,2024],"quote":"There''s a very cool 3Blue1Brown video [0] that helps give you an intuitive feel for Bayes Theorem.","quote_url":"https://news.ycombinator.com/item?id=29773486","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Nsjsiz2A9mg','hn',2.5,'{"vid":"Nsjsiz2A9mg","title":"Robert C Martin - Clean Architecture and Design","channel":"gnbitcom","summary":"Robert C. Martin (Uncle Bob) talks about clean architecture and design, including keeping the database and frameworks out of the center of an application. It is an hour-long conference talk.","why":"Recommended as a formative talk on architecture that argues against putting the database at the center of a design.","type":"talk","level":"intermediate","score":2.5,"topics":["Software design & craft"],"recs":2,"years":[2018,2024],"quote":"This talk was really formative for me","quote_url":"https://news.ycombinator.com/item?id=40663465","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('P76Vbsk_3J0','hn',2.5,'{"vid":"P76Vbsk_3J0","title":"Clojure for Java Programmers Part 1 - Rich Hickey","channel":"ClojureTV","summary":"Rich Hickey introduces Clojure to the NYC Java Study Group in the first of a two-part talk. It covers reader syntax, core data structures, code-as-data, evaluation, special operators, functions, macros and sequences, assuming no Lisp background.","why":"Recommended as a clear, well-paced introduction to Clojure and Lisp ideas like code as data and macros, straight from the language''s creator.","type":"talk","level":"intro","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2013,2022],"quote":"It''s just a great talk.","quote_url":"https://news.ycombinator.com/item?id=6103627","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QHnLmvDxGTY','hn',2.5,'{"vid":"QHnLmvDxGTY","title":"\"Uncle\" Bob Martin","channel":"Program on Entrepreneurship","summary":"Robert ''Uncle Bob'' Martin speaks at Yale School of Management about clean, well-written code and what makes good software development. The talk covers his views on OOP, architecture and professional practice.","why":"HN cites it as a formative talk on what OOP really is, and on why teams write code that slows them down.","type":"talk","level":"general","score":2.5,"topics":["Software design & craft"],"recs":2,"years":[2017,2024],"quote":"This talk was really formative for me","quote_url":"https://news.ycombinator.com/item?id=40663465","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QPgqfnKG_T4','hn',2.5,'{"vid":"QPgqfnKG_T4","title":"Militarizing Your Backyard with Python: Computer Vision and the Squirrel Hordes","channel":"Next Day Video","summary":"A PyCon 2012 talk by Kurt Grandis on building an automated water-squirting turret that uses Python and computer vision to detect and drive off squirrels from a bird feeder.","why":"HN loves it as a funny, inspiring hobby project and calls it one of the best conference talks ever.","type":"talk","level":"intermediate","score":2.5,"topics":["Python","Languages & compilers","AI & ML"],"recs":3,"years":[2014,2023],"quote":"Perhaps the best presentation to a programming language conference in history.","quote_url":"https://news.ycombinator.com/item?id=8440420","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('RNsEsZbXE-4','hn',2.5,'{"vid":"RNsEsZbXE-4","title":"RustConf 2020 - Closing Keynote by Siân Griffin","channel":"Rust Programming Language","summary":"RustConf 2020 closing keynote by Sian Griffin that dives into Pokemon Blue glitches, notably Missingno and arbitrary-code-execution tricks. It uses them to explain how memory unsafety works and how memory-safe languages like Rust prevent such bugs.","why":"HN points to it as a fun, technically deep talk that makes memory-safety bugs vivid through a beloved game.","type":"talk","level":"general","score":2.5,"topics":["Systems & performance"],"recs":2,"years":[2020,2022],"quote":"I really enjoyed the RustConf 2020 Closing Keynote","quote_url":"https://news.ycombinator.com/item?id=25537492","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Sg4U4r_AgJU','hn',2.5,'{"vid":"Sg4U4r_AgJU","title":"Computer Science - Brian Kernighan on successful language design","channel":"University of Nottingham","summary":"Brian Kernighan gives a talk at the University of Nottingham on how to succeed in language design without really trying. He draws on his experience with awk and other languages.","why":"HN cites it as a practical talk on language design and for background on awk from one of its authors.","type":"lecture","level":"general","score":2.5,"topics":["Languages & compilers"],"recs":3,"years":[2015,2022],"quote":"This is an excellent talk on designing successful programming language by Brian Kernighan","quote_url":"https://news.ycombinator.com/item?id=34047243","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Tml94je2edk','hn',2.5,'{"vid":"Tml94je2edk","title":"Why Static Typing Came Back • Richard Feldman • GOTO 2022","channel":"GOTO Conferences","summary":"Richard Feldman''s GOTO Copenhagen 2022 talk on why dynamic languages like Python, Ruby, PHP and JavaScript rose in the 1990s and why each now has a popular static type checker. It argues that modern static typing recovers the advantages that made dynamic languages attractive.","why":"HN commenters cite it as a clear account of the trade-offs between static and dynamic typing and why the industry is swinging back to types.","type":"talk","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2023,2024],"quote":"It gives the major reasons why one would prefer one over the other","quote_url":"https://news.ycombinator.com/item?id=36590025","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('V6VP-2aIcSc','hn',2.5,'{"vid":"V6VP-2aIcSc","title":"Object-Oriented Programming is Garbage: 3800 SLOC example","channel":"Brian Will","summary":"Brian Will critiques object-oriented programming and rewrites a roughly 3800-line OO program in a procedural style, cutting code and complexity. It is part of a series of OOP critiques.","why":"HN recommends it as a concrete, worked example of the case against heavy OOP rather than abstract argument.","type":"lecture","level":"intermediate","score":2.5,"topics":["Software design & craft"],"recs":2,"years":[2016,2022],"quote":"I recommend the whole series","quote_url":"https://news.ycombinator.com/item?id=31866740","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('W4SxKWwFhA0','hn',2.5,'{"vid":"W4SxKWwFhA0","title":"Browser hacking: Let''s make \"Cookie Clicker\" playable in Ladybird!","channel":"Andreas Kling","summary":"In a long live-coding session, Andreas Kling works on making the Cookie Clicker game playable in the Ladybird browser from SerenityOS. He tracks down bugs in the browser engine and fixes them.","why":"HN loves the Browser hacking series for its clear debugging method of reducing bugs to minimal reproductions, which people say influenced their own testing.","type":"tutorial","level":"advanced","score":2.5,"topics":["Web"],"recs":2,"years":[2022,2024],"quote":"At one point, he deletes half the HTML file to isolate where in the site the problematic code is.","quote_url":"https://news.ycombinator.com/item?id=35522475","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('X1T3IQ4N-3g','hn',2.5,'{"vid":"X1T3IQ4N-3g","title":"CppCon 2014: Jeff Preshing \"How Ubisoft Develops Games for Multicore - Before and After C++11\"","channel":"CppCon","summary":"CppCon 2014 talk by Jeff Preshing on how Ubisoft Montreal developed games for multicore hardware, before and after C++11 concurrency support. It goes into atomics and lock-free programming in practice.","why":"Recommended as a clear, practical introduction to atomics and lock-free programming in C++.","type":"talk","level":"intermediate","score":2.5,"topics":["Systems & performance"],"recs":2,"years":[2015,2021],"quote":"Jeff Preshing gave a really good introduction to atomics at CppCon 2014.[1]","quote_url":"https://news.ycombinator.com/item?id=9061485","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('dPK6t7echuA','hn',2.5,'{"vid":"dPK6t7echuA","title":"\"How to Think about Parallel Programming: Not!\" - Guy L. Steele Jr. (Strange Loop 2010)","channel":"Strange Loop Conference","summary":"Guy Steele''s Strange Loop 2010 talk argues that programmers should not have to think about parallelism, and that languages should support algorithms built on independence and divide-and-conquer. He also recounts fitting a program onto a single punch card.","why":"Recommended as a fantastic talk, valued both for its parallelism ideas and for the punch-card story.","type":"talk","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2022,2024],"quote":"It''s a fantastic talk in its own right","quote_url":"https://news.ycombinator.com/item?id=38166248","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('er_lLvkklsk','hn',2.5,'{"vid":"er_lLvkklsk","title":"Barliman: trying the halting problem backwards, blindfolded - William Byrd, Greg Rosenblatt","channel":"ClojureTV","summary":"A Clojure/conj 2016 talk demoing Barliman, a prototype smart editor that does program synthesis. Given a partial program and tests, it completes the program using a relational interpreter written in miniKanren.","why":"HN people point to it as an amazing demonstration of relational programming and program synthesis that still looks exciting after LLM code generation.","type":"talk","level":"intermediate","score":2.5,"topics":["Languages & compilers"],"recs":3,"years":[2017,2024],"quote":"I work on miniKanren, which is a logic programming language with a complete search that doesn''t hit the nontermination issues you mention.","quote_url":"https://news.ycombinator.com/item?id=14047984","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hIZxTQP1ifo','hn',2.5,'{"vid":"hIZxTQP1ifo","title":"Edward Kmett - Type Classes vs. the World","channel":"Boston Haskell","summary":"Edward Kmett speaks at the Boston Haskell meetup about type classes and the design tradeoffs of global coherence compared with other approaches to implicit instances. It covers why uniqueness of instances matters for reasoning and refactoring.","why":"HN points to it as the definitive explanation of why coherence and the orphan rule matter, in debates over Haskell, Rust traits, OCaml modules and Elm.","type":"talk","level":"advanced","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2015,2024],"quote":"Ed Kmett''s fantastic \"Typeclasses v. the World\" talk covers","quote_url":"https://news.ycombinator.com/item?id=10306544","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('j6ow-UemzBc','hn',2.5,'{"vid":"j6ow-UemzBc","title":"Design Microservice Architectures the Right Way","channel":"InfoQ","summary":"Michael Bryzek of Flow gives a QCon London 2018 talk on key decisions for building maintainable microservices. It covers infrastructure, continuous deployment, communication, event streaming and language choice.","why":"HN commenters recommend it for showing the tooling possible when schemas and APIs are treated as code.","type":"talk","level":"intermediate","score":2.5,"topics":["Software design & craft"],"recs":2,"years":[2019,2021],"quote":"There''s a great talk that I highly recommend about some of the magic you can do","quote_url":"https://news.ycombinator.com/item?id=24948311","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lqJUIqZNzP8','hn',2.5,'{"vid":"lqJUIqZNzP8","title":"Avoiding Negative Side Effects: Concrete Problems in AI Safety part 1","channel":"Robert Miles AI Safety ","summary":"Robert Miles introduces the first of several videos on the paper ''Concrete Problems in AI Safety'', focusing on how AI systems can cause accidental negative side effects. It explains the problem in accessible terms.","why":"HN recommends Robert Miles'' channel as a clear starting point for people curious about AI safety.","type":"explainer","level":"intro","score":2.5,"topics":["AI & ML"],"recs":2,"years":[2018,2023],"quote":"For those curious about AI safety I heavily recommend Robert Miles channel on YouTube.","quote_url":"https://news.ycombinator.com/item?id=34459007","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('mSgXWpvQEHE','hn',2.5,'{"vid":"mSgXWpvQEHE","title":"Keynote. Professor Steven G. Johnson | JuliaCon 2019","channel":"The Julia Programming Language","summary":"Steven G. Johnson, MIT professor and FFTW co-author, gives a JuliaCon 2019 keynote on metaprogramming and staged programming in Julia, showing how it enables high-performance numerical code and when not to use macros.","why":"Cited for showing how Julia''s metaprogramming can beat C and Fortran, along with sound advice not to overuse it.","type":"talk","level":"advanced","score":2.5,"topics":["Languages & compilers"],"recs":2,"years":[2019,2022],"quote":"really interesting, informative, entertaining and well delivered.","quote_url":"https://news.ycombinator.com/item?id=20584922","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('oLkfnc_UMcE','hn',2.5,'{"vid":"oLkfnc_UMcE","title":"Nathaniel J. Smith - Trio: Async concurrency for mere mortals - PyCon 2018","channel":"PyCon 2018","summary":"Nathaniel J. Smith''s PyCon 2018 talk introducing Trio, a Python concurrency library designed around usability and structured concurrency. He live-codes a problem and analyzes pitfalls in other async libraries.","why":"Recommended as a clear introduction to structured concurrency and as an explanation of subtle asyncio bugs that Trio avoids.","type":"talk","level":"intermediate","score":2.5,"topics":["Python","Languages & compilers","Software design & craft"],"recs":2,"years":[2020,2023],"quote":"one of the best explanations I''ve seen about what subtle bugs are easy to make with asyncio","quote_url":"https://news.ycombinator.com/item?id=28882968","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('rC4FCS-oMpg','hn',2.5,'{"vid":"rC4FCS-oMpg","title":"Makepad: Designing modern UIs with Rust - Rik Arends - RustNL 2023","channel":"RustNL","summary":"Rik Arends presents Makepad, a Rust UI framework, at RustNL 2023. The talk covers designing modern, GPU-fast UIs with Rust and includes live-coded demos of an IDE and a synthesizer.","why":"HN commenters recommend it for the live-coded demos running at high frame rates, calling the performance impressive.","type":"talk","level":"intermediate","score":2.5,"topics":["Systems & performance","Web"],"recs":2,"years":[2023,2024],"quote":"Greg Johnston, creator of Leptos, has made a video with performance comparisons","quote_url":"https://news.ycombinator.com/item?id=37037807","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('sgHbC6udIqc','hn',2.5,'{"vid":"sgHbC6udIqc","title":"Pragmatic Unicode, or, How do I stop the pain?","channel":"Next Day Video","summary":"Ned Batchelder''s PyCon 2012 talk gives a quick overview of what Unicode is, then focuses on what a Python programmer needs to handle text correctly. It presents the ''Unicode sandwich'' strategy: decode bytes at input, work with Unicode internally, encode at output.","why":"Commenters point to it as the clearest explanation of Python''s bytes versus Unicode model and the Unicode sandwich, which finally makes the confusion click.","type":"talk","level":"intro","score":2.5,"topics":["Python","Languages & compilers"],"recs":2,"years":[2015,2019],"quote":"After A TON OF PAIN I decided to put the time in to watch the talk","quote_url":"https://news.ycombinator.com/item?id=19949547","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-C-JoyNuQJs','hn',2.0,'{"vid":"-C-JoyNuQJs","title":"Douglas Crockford: The JSON Saga","channel":"YUI Library","summary":"Douglas Crockford tells how JSON was discovered rather than invented, and how its simplicity made it a dominant data interchange format. He also covers surrounding history such as earlier Netscape usage and the ''Good, not Evil'' license story.","why":"HN commenters cite it as Crockford''s first-hand account of JSON''s origins and of the no-evil license anecdote.","type":"talk","level":"general","score":2.0,"topics":["Web"],"recs":2,"years":[2012,2025],"quote":"JSON by being so simple actually became really easy to use.","quote_url":"https://news.ycombinator.com/item?id=17833864","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('-K11rY57K7k','hn',2.0,'{"vid":"-K11rY57K7k","title":"Dmitry Vyukov — Go scheduler: Implementing language with lightweight concurrency","channel":"Hydra","summary":"Go runtime contributor Dmitry Vyukov looks inside the Go scheduler, explaining how goroutines and channels are implemented. He covers the main scheduler components and overall operation, then goes into details such as preemption and stacks.","why":"Recommended as a good watch on how Go''s M:N:P scheduler works and why it was designed that way compared with alternative schemes.","type":"talk","level":"advanced","score":2.0,"topics":["Systems & performance","Languages & compilers"],"recs":2,"years":[2020,2026],"quote":"This one notably also explains the design considerations for golangs M:N:P in comparison to other schemes","quote_url":"https://news.ycombinator.com/item?id=47359538","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('13cmHf_kt-Q','hn',2.0,'{"vid":"13cmHf_kt-Q","title":"Stuart Sierra - Components Just Enough Structure","channel":"ClojureTV","summary":"Stuart Sierra presents the Component library for Clojure, a way to manage stateful services like database connections and thread pools without global mutable state. He draws on both functional and object-oriented principles.","why":"Pointed to as a thought-provoking talk on structuring large systems, including outside Clojure.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2014,2015],"quote":"it is a tiny clojure framework but the ideas should be thought provoking","quote_url":"https://news.ycombinator.com/item?id=10296432","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('3TYT1QfdfsM','hn',2.0,'{"vid":"3TYT1QfdfsM","title":"AI \"Stop Button\" Problem - Computerphile","channel":"Computerphile","summary":"Rob Miles explains on Computerphile why implementing an off switch for a general AI is hard. A capable agent would resist being stopped because shutdown prevents it from achieving its goal.","why":"HN points to it as the standard response to the argument that we can just unplug a dangerous AI.","type":"explainer","level":"general","score":2.0,"topics":["AI & ML"],"recs":2,"years":[2017,2026],"quote":"here’s an interesting video response to the “just unplug it” argument on the Compuerphile channel","quote_url":"https://news.ycombinator.com/item?id=46863202","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('4moyKUHApq4','hn',2.0,'{"vid":"4moyKUHApq4","title":"A Possible Future of Software Development","channel":"Google TechTalks","summary":"Sean Parent of Adobe argues that object-oriented frameworks ultimately fail to deliver scalable, high quality software and proposes combining generic and declarative programming instead. It draws on Stepanov''s Elements of Programming.","why":"Frequently cited for the claim that Photoshop''s codebase could shrink dramatically with generic programming.","type":"talk","level":"advanced","score":2.0,"topics":["Software design & craft","Systems & performance"],"recs":2,"years":[2012,2019],"quote":"Watch this Sean Parent video","quote_url":"https://news.ycombinator.com/item?id=14902789","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5ZjhNTM8XU8','hn',2.0,'{"vid":"5ZjhNTM8XU8","title":"\"Transactions: myths, surprises and opportunities\" by Martin Kleppmann","channel":"Strange Loop Conference","summary":"Martin Kleppmann''s Strange Loop talk on database transactions, covering why they were dropped by NoSQL, their reputation for being slow, and newer algorithms that make serializable transactions perform and scale. It touches on consistency, linearizability and the CAP theorem.","why":"Recommended as a compact preview of Kleppmann''s data systems material, including from his book on the subject.","type":"talk","level":"intermediate","score":2.0,"topics":["Databases & distributed"],"recs":2,"years":[2018,2023],"quote":"I recommend watching this talk from him to give a little glimpse of the book","quote_url":"https://news.ycombinator.com/item?id=19901785","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('5eqRuVp65eY','hn',2.0,'{"vid":"5eqRuVp65eY","title":"AI can''t cross this line and we don''t know why.","channel":"Welch Labs","summary":"A Welch Labs explainer on neural scaling laws and the compute-efficient frontier, asking why model loss seems to hit a line it cannot cross. It draws an analogy to an ideal gas law for AI.","why":"Recommended as a well-made, digestible introduction to scaling laws and why models cluster along a similar efficiency frontier.","type":"explainer","level":"intermediate","score":2.0,"topics":["AI & ML"],"recs":2,"years":[2024,2025],"quote":"see eg for a well made/easily digestable intro","quote_url":"https://news.ycombinator.com/item?id=41844225","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7PKx3kS7f4A','hn',2.0,'{"vid":"7PKx3kS7f4A","title":"Why Asimov''s Laws of Robotics Don''t Work - Computerphile","channel":"Computerphile","summary":"Rob Miles explains for Computerphile why simple rule sets like Asimov''s Three Laws cannot make robots and AI safe. Terms like harm and human are too ambiguous to specify precisely.","why":"Pointed to in AI safety debates as a short explanation of why encoding human values as simple rules is so hard.","type":"explainer","level":"intro","score":2.0,"topics":["AI & ML"],"recs":2,"years":[2015,2023],"quote":"I found this video insightful on the matter from Computerphile","quote_url":"https://news.ycombinator.com/item?id=35304223","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('7PoajCqNKpg','hn',2.0,'{"vid":"7PoajCqNKpg","title":"Physics in Clojure - Colin Smith","channel":"ClojureTV","summary":"Colin Smith introduces Structure and Interpretation of Classical Mechanics and his Clojure port, sicmutils. He shows how higher-order functions and a symbolic algebra system can represent Lagrangian mechanics.","why":"Recommended as the best introduction to SICM and sicmutils and a showcase of what such symbolic systems can do.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2019,2023],"quote":"The Strange Loop talk [3] is a good showcase of the power and simplicity of these kind of systems.","quote_url":"https://news.ycombinator.com/item?id=26357900","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('9i1WlcCudpU','hn',2.0,'{"vid":"9i1WlcCudpU","title":"10 Reasons to Ignore AI Safety","channel":"Robert Miles AI Safety ","summary":"Robert Miles goes through ten common reasons people give for dismissing AI safety, adapted from Stuart Russell''s list, and answers each one. It is aimed at skeptics and newcomers.","why":"HN commenters link it as a compact rebuttal to dismissive arguments and as a way to see why people consider AI safety important.","type":"explainer","level":"intro","score":2.0,"topics":["AI & ML"],"recs":2,"years":[2022,2024],"quote":"This video might be interesting to see some arguments for why people think it’s important","quote_url":"https://news.ycombinator.com/item?id=40402810","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('AnZ0uTOerUI','hn',2.0,'{"vid":"AnZ0uTOerUI","title":"Unconditional Code • Michael Feathers • GOTO 2018","channel":"GOTO Conferences","summary":"Michael Feathers'' GOTO Chicago 2018 talk on reducing error checks and conditional logic in code. He offers a framework for handling errors and decisions at the level of code and architecture.","why":"HN recommends it for the idea of giving data instead of asking for it, and ties it to zero values and exception-free design.","type":"talk","level":"intermediate","score":2.0,"topics":["Software design & craft"],"recs":2,"years":[2018,2021],"quote":"giving data instead of asking for data avoids error conditions","quote_url":"https://news.ycombinator.com/item?id=22227745","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('CuD7SCqHB7k','hn',2.0,'{"vid":"CuD7SCqHB7k","title":"RustConf 2017 - Closing Keynote: Safe Systems Software and the Future of Computing by Joe Duffy","channel":"Confreaks","summary":"Joe Duffy''s RustConf 2017 closing keynote on his experience at Microsoft building Midori, an operating system written in a Rust-like safe systems language. He covers the technical and cultural challenges of applying those lessons to Windows.","why":"HN repeatedly cites it for Midori lessons: compatibility matters for adoption, and the Windows team stayed sceptical even with Midori running real workloads.","type":"talk","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2017,2025],"quote":"I summarized this excellent talk here [1], but one of the main points is that compatibility with existing systems is important for adoption.","quote_url":"https://news.ycombinator.com/item?id=15179941","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('EeYvFl7li9E','hn',2.0,'{"vid":"EeYvFl7li9E","title":"Ryan Dahl: Node JS","channel":"JSConf","summary":"Ryan Dahl''s JSConf EU talk introducing Node.js to the world. He explains the motivation for event-driven, non-blocking I/O, with JavaScript chosen mainly for its asynchronous nature.","why":"Cited as the primary source for why Node exists and why JavaScript was chosen, in debates about async models and language choice.","type":"talk","level":"intermediate","score":2.0,"topics":["Web"],"recs":2,"years":[2023,2024],"quote":"it''s kind of refreshing to see the original node.js presentation, where using javascript is sort of a side-note","quote_url":"https://news.ycombinator.com/item?id=41766721","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IS3i3DTUnAI','hn',2.0,'{"vid":"IS3i3DTUnAI","title":"The Maximal Graph - Wilker Silva","channel":"ClojureTV","summary":"A Clojure/conj 2019 talk by Wilker Silva on how namespace-qualified keywords and context-free federated names can be used pragmatically for data modeling, drawn from his experience at Nubank. It builds toward a graph-based view of connecting data from many sources.","why":"Cited as a demonstration of the Pathom/graph approach to connecting APIs, as an alternative to GraphQL.","type":"talk","level":"advanced","score":2.0,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2019,2020],"quote":"Just watch the last part of Wilker Silva''s The Maximal Graph talk to see the potential","quote_url":"https://news.ycombinator.com/item?id=21747883","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('IZmaeC_Ma5A','hn',2.0,'{"vid":"IZmaeC_Ma5A","title":"Developing the best free photo editor - Ivan KUCKIR - Web2day 2019","channel":"Web2day","summary":"Photopea founder Ivan Kutskir talks about developing a free browser-based photo editor, one of the most complex JavaScript programs ever written, and the web technologies behind it.","why":"HN points to it as a look under the hood of a remarkable one-developer project.","type":"talk","level":"intermediate","score":2.0,"topics":["Web"],"recs":2,"years":[2019,2021],"quote":"here''s a cool talk about it: the whole thing is just 2MB of JS written by one guy!","quote_url":"https://news.ycombinator.com/item?id=23491058","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('M2fKMP47slQ','hn',2.0,'{"vid":"M2fKMP47slQ","title":"C++Now 2018: You Can Do Better than std::unordered_map: New Improvements to Hash Table Performance","channel":"CppNow","summary":"Malte Skarupke''s C++Now 2018 talk on hash table performance, explaining why std::unordered_map is slow and memory hungry and presenting faster designs, including his bytell hash map.","why":"Recommended as a thorough, well-regarded explanation of hash table design tradeoffs and why the standard container is a poor choice.","type":"talk","level":"advanced","score":2.0,"topics":["DSA","Systems & performance"],"recs":2,"years":[2021,2024],"quote":"Many videos on hash table are great. I found this one particularly good.","quote_url":"https://news.ycombinator.com/item?id=41998812","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NVEgyJCTee4','hn',2.0,'{"vid":"NVEgyJCTee4","title":"01 The History of Standard ML: Ideas, Principles, Culture","channel":"ICFP Video","summary":"An ICFP 2015 keynote on the history of Standard ML, covering its ideas, principles and culture. It traces ML from Strachey, Landin and Milner through SML''s development and its interplay with OCaml.","why":"Pointed to in language-history discussions as a good account of how ML and SML came to be.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2016,2022],"quote":"You can hear a bunch more about the full history of development of SML and interaction with OCaml here","quote_url":"https://news.ycombinator.com/item?id=13295847","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Nbv9L-WIu0s','hn',2.0,'{"vid":"Nbv9L-WIu0s","title":"Bloat: How and Why UNIX Grew Up (and Out) - Rusty Russell,Matt Evans","channel":"Linux.conf.au 2012 -- Ballarat, Australia","summary":"Rusty Russell and Matt Evans examine why Unix utilities like ls and cat grew from a few kilobytes to over a hundred kilobytes. They take apart common tools to see where the growth comes from.","why":"Used in software bloat debates as a measured look at why binaries got larger.","type":"talk","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2014,2015],"quote":"Well worth a viewing.","quote_url":"https://news.ycombinator.com/item?id=9825958","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NcUJnmBqHTY','hn',2.0,'{"vid":"NcUJnmBqHTY","title":"\"Cursorless: A spoken language for editing code\" by Pokey Rule (Strange Loop 2023)","channel":"Strange Loop Conference","summary":"Pokey Rule presents Cursorless, a spoken language designed for editing code by voice, built on tree-sitter parsing with smart structural and simple token-level primitives. The talk is from Strange Loop 2023.","why":"HN recommends it as the best overview of Cursorless, likened to vim with your voice, and relevant to accessibility and voice coding discussions.","type":"talk","level":"intermediate","score":2.0,"topics":["Software design & craft","Languages & compilers"],"recs":2,"years":[2023,2026],"quote":"If you want a general overview of cursorless, along with seeing what it looks like in practice, the talk from Strange Loop this year was great","quote_url":"https://news.ycombinator.com/item?id=38221949","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NftT6HWFgq0','hn',2.0,'{"vid":"NftT6HWFgq0","title":"Mountain West Ruby 2012 Capability vs. Suitability by Gary Bernhardt","channel":"Confreaks","summary":"Gary Bernhardt argues that software history moves in reactions to earlier tools, and that new tools are not simply better in every way. He distinguishes capability (what a tool allows) from suitability (what it fits), and warns against repeating past mistaken reactions.","why":"HN commenters reuse the capability-versus-suitability framing to discuss languages, restriction versus freedom, and tool design.","type":"talk","level":"intermediate","score":2.0,"topics":["Software design & craft","Languages & compilers"],"recs":2,"years":[2015,2023],"quote":"Very nearly exactly what you''re describing","quote_url":"https://news.ycombinator.com/item?id=36395974","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('OgRFOjVzvm0','hn',2.0,'{"vid":"OgRFOjVzvm0","title":"SICP: o fim de uma era","channel":"Computação Raiz","summary":"A short Portuguese-language excerpt of Gerald Sussman''s 2016 NYC Lisp Meetup talk explaining why MIT replaced the Scheme-based 6.001 (SICP) course with Python courses. The full talk is linked in the description.","why":"HN uses it as the canonical explanation from Sussman himself of why SICP ended at MIT.","type":"talk","level":"general","score":2.0,"topics":["Python","Languages & compilers"],"recs":2,"years":[2023,2025],"quote":"we can''t mention SICP without referencing this (relatively recent) video","quote_url":"https://news.ycombinator.com/item?id=43683335","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QAz-maaH0KM','hn',2.0,'{"vid":"QAz-maaH0KM","title":"Rust NYC: Jon Gjengset - Demystifying unsafe code","channel":"Rust Programming Language","summary":"Jon Gjengset''s Rust NYC talk explaining what `unsafe` in Rust actually means, why it is dangerous, and why it is sometimes necessary. He works through the Rustonomicon to separate fair concerns from overblown ones.","why":"HN recommends it as the best calm explanation of unsafe Rust, from a speaker commenters trust on the topic.","type":"talk","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2020,2024],"quote":"There''s a great new talk by on Gjengset on youtube that tackles just this question","quote_url":"https://news.ycombinator.com/item?id=22968384","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QMVIJhC9Veg','hn',2.0,'{"vid":"QMVIJhC9Veg","title":"PDE: A different take on editing code","channel":"TJ DeVries","summary":"TJ DeVries coins the term PDE (Personalized Development Environment) to describe editors like Neovim that you shape to your own workflow. He contrasts this with out-of-the-box IDEs and discusses why customizable tools appeal to developers.","why":"It is the cited origin of the ''PDE'' term, which HN uses when discussing vim, Neovim and Emacs as personally customized environments.","type":"talk","level":"general","score":2.0,"topics":["Software design & craft"],"recs":2,"years":[2022,2025],"quote":"For anyone not understanding why (neo)vim exists, or why some developers prefer it to IDEs, I suggest watching","quote_url":"https://news.ycombinator.com/item?id=34366035","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('QjJaFG63Hlo','hn',2.0,'{"vid":"QjJaFG63Hlo","title":"Seminar with Alan Kay on Object Oriented Programming (VPRI 0246)","channel":"Yoshiki Ohshima (大島芳樹)","summary":"A long recorded seminar in which Alan Kay discusses object-oriented programming, probably from the mid-1980s. He covers the original idea of objects, messaging and the work done at Xerox.","why":"HN points to it as primary-source evidence of what Kay meant by objects, which resembled services and message passing rather than modern class-based OOP.","type":"lecture","level":"intermediate","score":2.0,"topics":["Software design & craft"],"recs":2,"years":[2017,2025],"quote":"Most Alan Kay''s presentations I''ve seen were worth watching. Tons of great ideas in each.","quote_url":"https://news.ycombinator.com/item?id=19587194","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('SFv8Wm2HdNM','hn',2.0,'{"vid":"SFv8Wm2HdNM","title":"The Forgotten Art of Structured Programming - Kevlin Henney [C++ on Sea 2019]","channel":"cpponsea","summary":"Kevlin Henney revisits structured programming, from Go To Statement Considered Harmful to block-structured code and object orientation. He argues it still matters for how we write code today.","why":"HN commenters point to it in discussions of goto, early returns and cognitive load when reading code.","type":"talk","level":"intermediate","score":2.0,"topics":["Software design & craft","Systems & performance"],"recs":2,"years":[2021,2022],"quote":null,"quote_url":null,"source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('T-TwcmT6Rcw','hn',2.0,'{"vid":"T-TwcmT6Rcw","title":"Raymond Hettinger - Dataclasses:  The code generator to end all code generators - PyCon 2018","channel":"PyCon 2018","summary":"Raymond Hettinger explains Python''s dataclasses module, showing the problem it solves and its key design decisions. He places it in a progression from tuples and dicts through named tuples and attrs.","why":"HN commenters recommend it as an approachable talk from a respected Python core developer on dataclasses.","type":"talk","level":"intermediate","score":2.0,"topics":["Python","Languages & compilers"],"recs":2,"years":[2018,2021],"quote":"Raymond Hettinger''s talks are great.","quote_url":"https://news.ycombinator.com/item?id=27268487","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('TTM_b7EJg5E','hn',2.0,'{"vid":"TTM_b7EJg5E","title":"The Do''s and Don''ts of Error Handling • Joe Armstrong • GOTO 2018","channel":"GOTO Conferences","summary":"Joe Armstrong, inventor of Erlang, gives a GOTO Chicago 2018 talk on building fault-tolerant systems. He covers what to do and avoid when handling errors, arguing for letting processes fail and recover.","why":"Recommended as a conceptual rather than code-heavy talk on failure recovery from Erlang''s creator.","type":"talk","level":"intermediate","score":2.0,"topics":["Databases & distributed","Languages & compilers"],"recs":2,"years":[2018,2022],"quote":"it''s well worth listening to this talk, which is conceptual and not code-centric","quote_url":"https://news.ycombinator.com/item?id=34198802","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ThjvMReOXYM','hn',2.0,'{"vid":"ThjvMReOXYM","title":"Crust of Rust: async/await","channel":"Jon Gjengset","summary":"Jon Gjengset''s long live-coding Crust of Rust episode on async/await, focused on the mental model for using it rather than on Futures, Pin and Wakers internals. Topics include awaiting multiple futures, cancellation, executors and select.","why":"Recommended as a deep, practical dive for learning how Rust async works.","type":"tutorial","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2023,2026],"quote":"these two videos are also great deep dives into Rust async","quote_url":"https://news.ycombinator.com/item?id=37184071","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Uwuv05aZ6ug','hn',2.0,'{"vid":"Uwuv05aZ6ug","title":"The Mental Game of Python - Raymond Hettinger [synced version]","channel":"Tech Ma","summary":"Raymond Hettinger''s PyBay 2019 talk on the mental strategies he uses when programming in Python, such as chunking, solving a simpler related problem, and repeating tasks manually until patterns emerge. This version is re-synced with the slides.","why":"HN recommends it as an entertaining talk on how working memory shapes code and how to reduce cognitive load.","type":"talk","level":"intermediate","score":2.0,"topics":["Python","Languages & compilers"],"recs":2,"years":[2020,2026],"quote":"Raymond Hettinger gave an entertaining talk [0] on a related topic.","quote_url":"https://news.ycombinator.com/item?id=30482281","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('VxINoKFm-S4','hn',2.0,'{"vid":"VxINoKFm-S4","title":"\"A Little Taste of Dependent Types\" by David Christiansen","channel":"Strange Loop Conference","summary":"David Christiansen gives a Strange Loop 2018 introduction to dependent types, where one language serves for both compile-time and run-time code and programs unite with proofs. It draws on his book The Little Typer.","why":"Recommended as an approachable introduction to dependent types and a preview of what The Little Typer covers.","type":"talk","level":"intro","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2018,2023],"quote":"Here''s an intro to dependent types from David Christiansen","quote_url":"https://news.ycombinator.com/item?id=34457848","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('WjTrfoiB0MQ','hn',2.0,'{"vid":"WjTrfoiB0MQ","title":"CppCon 2015: Andrei Alexandrescu “Declarative Control Flow\"","channel":"CppCon","summary":"Andrei Alexandrescu''s CppCon 2015 talk on handling exceptional control flow declaratively in C++. It uses scope guards with success and failure variants, built on std::uncaught_exceptions, to replace ad hoc RAII classes and rethrowing try/catch blocks.","why":"Pointed to in threads on defer, scope_exit and RAII as the clearest treatment of scope guards.","type":"talk","level":"advanced","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2016,2022],"quote":"Andrei Alexandrescu has a fun talk about implementing scope_exit","quote_url":"https://news.ycombinator.com/item?id=16324582","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Wo2m3jaJixU','hn',2.0,'{"vid":"Wo2m3jaJixU","title":"Scaling the Linear Sync Engine","channel":"Linear","summary":"A Linear engineer talks about scaling the company''s sync engine, which keeps client data local and synchronized. It follows an earlier talk on the same system.","why":"Recommended whenever local-first software, sync engines and CRDT alternatives come up, as a practical production account.","type":"talk","level":"advanced","score":2.0,"topics":["Web","Databases & distributed"],"recs":2,"years":[2023,2025],"quote":"This talk by Karri about Linear''s \"sync engine\" is also a good watch","quote_url":"https://news.ycombinator.com/item?id=38292108","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('XRAP3lBivYM','hn',2.0,'{"vid":"XRAP3lBivYM","title":"CppCon 2019: Emery Berger “Mesh: Automatically Compacting Your C++ Application''s Memory”","channel":"CppCon","summary":"Emery Berger''s CppCon 2019 talk introducing Mesh, a drop-in malloc replacement that compacts memory in unmodified C and C++ programs. It tackles fragmentation by merging pages without changing pointers.","why":"HN recommends Berger''s talks as fascinating and cites Mesh as mind-blowing memory allocator work.","type":"talk","level":"advanced","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2019,2023],"quote":"the weird and wonderful work of Emery Berger et al with their “Mesh” malloc implementation, which blows my mind","quote_url":"https://news.ycombinator.com/item?id=36035793","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('Zn7oWIhFffs','hn',2.0,'{"vid":"Zn7oWIhFffs","title":"AI Ethics, Impossibility Theorems and Tradeoffs - Chris Stucchio | Crunch 2018","channel":"CraftHub Events","summary":"Chris Stucchio presents the ethical principles behind algorithmic decision making and shows with examples from lending, criminology and education that they cannot all be satisfied at once. The talk frames AI fairness as a set of quantitative tradeoffs.","why":"HN cites it in algorithmic-bias threads for the impossibility result that an algorithm cannot be procedurally fair, group fair and maximally useful at once.","type":"talk","level":"intermediate","score":2.0,"topics":["AI & ML"],"recs":2,"years":[2019,2021],"quote":"it''s impossible to simultaneously treat everyone the same way, to have a useful model, and to have uniformly distributed ''bias''-free outcomes.","quote_url":"https://news.ycombinator.com/item?id=21961200","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('_B_4vhsmRRI','hn',2.0,'{"vid":"_B_4vhsmRRI","title":"Marco Baringer''s SLIME Tutorial Video","channel":"손주일 (Cecil)","summary":"Marco Baringer''s tutorial video on SLIME, the Emacs mode for developing Common Lisp. It demonstrates the interactive workflow of working against a live Lisp image.","why":"HN points to it to show what the Lisp REPL workflow is like and as a good tour of SLIME.","type":"tutorial","level":"intro","score":2.0,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2019,2024],"quote":"This is what the lisp repl is like. There''s not much else like it","quote_url":"https://news.ycombinator.com/item?id=40128726","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('a1rC79DHpmY','hn',2.0,'{"vid":"a1rC79DHpmY","title":"Tree-sitter: a new parsing system for programming tools - GitHub Universe 2017","channel":"GitHub","summary":"Max Brunsfeld of GitHub presents Tree-sitter, a parsing system for programming tools that supports incremental, error-tolerant parsing. He demos its integration into GitHub.com and Atom for syntax highlighting and code navigation.","why":"Recommended as the canonical introduction to tree-sitter and why fast incremental parsing enables live editor support.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2018,2022],"quote":"There is a long (42 minutes) but worth to watch talk about tree-sitter","quote_url":"https://news.ycombinator.com/item?id=30955317","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('aMnn0Jq0J-E','hn',2.0,'{"vid":"aMnn0Jq0J-E","title":"Three Beautiful Quicksorts","channel":"Google TechTalks","summary":"Jon Bentley walks through three implementations of Hoare''s Quicksort, from a dozen-line C function to a series of systematic code transformations that make the program ever simpler and more powerful. It is a Google Tech Talk on code elegance and program derivation.","why":"HN commenters point to it as programming inspiration and as a source of Bentley''s anecdotes about adding function by deleting code.","type":"talk","level":"intermediate","score":2.0,"topics":["DSA","Software design & craft"],"recs":2,"years":[2010,2023],"quote":"If you''re looking for programming inspiration I love these videos","quote_url":"https://news.ycombinator.com/item?id=37248336","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('bl8jQ2wRh6k','hn',2.0,'{"vid":"bl8jQ2wRh6k","title":"Web Development in Emacs, Common Lisp and Clojurescript - Emacs SG","channel":"Engineers.SG","summary":"Elias Martenson presents his Emacs-based workflow for building a web application (the Potato chat platform) with Common Lisp on the backend and ClojureScript on the frontend. He demonstrates SLIME, Paredit, CIDER and debugger-driven interactive development. The talk is 79 minutes and was given at Emacs SG.","why":"HN commenters point to it as a live demonstration of interactive Lisp development, including compiling single functions in a running program and debugger-driven workflows.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers","Software design & craft"],"recs":2,"years":[2018,2022],"quote":"This video also has great examples of other crazy interactive development workflows and is worth watching in its entirety","quote_url":"https://news.ycombinator.com/item?id=28349671","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('cNICGEwmXLU','hn',2.0,'{"vid":"cNICGEwmXLU","title":"\"Systems that run forever self-heal and scale\" by Joe Armstrong (2013)","channel":"Strange Loop Conference","summary":"Joe Armstrong''s Strange Loop 2013 talk on building large scalable systems from small isolated parallel components. It covers detecting and correcting errors at run time, changing code while it runs, and how Erlang embodies these principles.","why":"Pointed to as the canonical pitch for Erlang''s fault-tolerance and self-healing model.","type":"talk","level":"intermediate","score":2.0,"topics":["Databases & distributed","Languages & compilers"],"recs":2,"years":[2023,2023],"quote":"is a great talk too.","quote_url":"https://news.ycombinator.com/item?id=35967771","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('ctS8FzqcRug','hn',2.0,'{"vid":"ctS8FzqcRug","title":"2017 LLVM Developers’ Meeting: “Implementing Swift Generics ”","channel":"LLVM","summary":"Swift compiler engineers explain how Swift implements generics using dictionary-passing with reified type metadata. They compare it with Java-style uniform representation and C++ or Rust monomorphization.","why":"Recommended as the clearest explanation of how Swift generics compile and how that differs from other languages.","type":"talk","level":"advanced","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2017,2026],"quote":"there''s a very nice talk on how Swift''s generics compile.","quote_url":"https://news.ycombinator.com/item?id=15933648","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('fBt5NuNsoII','hn',2.0,'{"vid":"fBt5NuNsoII","title":"BetrFS: A Right-Optimized Write-Optimized File System","channel":"Microsoft Research","summary":"A Microsoft Research talk on BetrFS, a file system built on B-epsilon trees, a write-optimized data structure. It covers WODS such as LSM-trees, how to design a file system around them, and benchmark wins over ext4 and xfs.","why":"HN points to it as a solid, if long, introduction to B-epsilon trees and why BetrFS is built the way it is.","type":"talk","level":"advanced","score":2.0,"topics":["Databases & distributed","DSA"],"recs":2,"years":[2016,2023],"quote":"It''s a great example of theoreticians and systems researchers working together.","quote_url":"https://news.ycombinator.com/item?id=29403597","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gC295d3V9gE','hn',2.0,'{"vid":"gC295d3V9gE","title":"\"Datafun: a functional query language\" by Michael Arntzenius","channel":"Strange Loop Conference","summary":"Michael Arntzenius''s Strange Loop talk on Datafun, a functional query language that brings database-style querying into a general-purpose language. It discusses bridging database theory and programming languages.","why":"HN recommends it as an approachable talk on a total functional generalization of Datalog, by the language''s author.","type":"talk","level":"intermediate","score":2.0,"topics":["Databases & distributed","Languages & compilers"],"recs":2,"years":[2018,2025],"quote":"Also be sure to watch Datafun author Michael Arntzenius''s Strangeloop talk.","quote_url":"https://news.ycombinator.com/item?id=44274287","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('gfh-VCTwMw8','hn',2.0,'{"vid":"gfh-VCTwMw8","title":"Avoiding Microservice Megadisasters - Jimmy Bogard","channel":"NDC Conferences","summary":"Jimmy Bogard presents a post-mortem of a real microservices migration that turned into a slow distributed monolith. He covers the modeling, development and production problems and how the team recovered.","why":"Recommended as an entertaining cautionary talk on microservice failures and Conway''s law.","type":"talk","level":"intermediate","score":2.0,"topics":["Software design & craft","Databases & distributed"],"recs":2,"years":[2018,2023],"quote":"Inverse Conway Maneuver: Design the organization you want, the architecture will follow, kicking and screaming.","quote_url":"https://news.ycombinator.com/item?id=18531030","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('jf_ddGnum_4','hn',2.0,'{"vid":"jf_ddGnum_4","title":"Implementing (part of) a BitTorrent client in Rust","channel":"Jon Gjengset","summary":"Jon Gjengset''s roughly four-hour live stream implementing part of a BitTorrent client in Rust, following CodeCrafters'' test-guided challenge. He builds from scratch and shows idiomatic error handling along the way.","why":"HN recommends it as a comprehensive walkthrough of the build-your-own-BitTorrent challenge and as an introduction to CodeCrafters.","type":"tutorial","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2023,2023],"quote":"Jon Gjengset did a comprehensive stream going through the Build your own BitTorrent challenge","quote_url":"https://news.ycombinator.com/item?id=38429356","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kIoZDUd5DKw','hn',2.0,'{"vid":"kIoZDUd5DKw","title":"CppCon 2019: Matt Godbolt “Compiler Explorer: Behind The Scenes”","channel":"CppCon","summary":"Matt Godbolt tells the story of Compiler Explorer, from a hacky basement server to a cloud-scaled service handling tens of thousands of daily requests. He also shows its features and how it is built.","why":"Recommended as the source on how Compiler Explorer began and for its lesser-known features like the machine code analyzer.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers","Systems & performance"],"recs":2,"years":[2021,2025],"quote":"a cool feature he presented is the integrated LLVM Machine Code Analyser tool","quote_url":"https://news.ycombinator.com/item?id=27728834","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('kTrOg19gzP4','hn',2.0,'{"vid":"kTrOg19gzP4","title":"Geo Carncross: How to program computers (kos)","channel":"Justin Cormack","summary":"A 2014 talk by Geo Carncross (geocar) demonstrating kOS, a minimalist operating system and programming environment built around the k language, with early screenshots.","why":"HN commenters recommend it as a rare live look at kOS in action, and one that is fascinating and mind-bending.","type":"talk","level":"advanced","score":2.0,"topics":["Systems & performance","Languages & compilers"],"recs":2,"years":[2015,2020],"quote":"For those who want to see it in action, there''s actually a talk about kOS on YouTube","quote_url":"https://news.ycombinator.com/item?id=20253417","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('koTf7u0v41o','hn',2.0,'{"vid":"koTf7u0v41o","title":"Plenary: Performance Matters - Emery Berger - CppCon 2020","channel":"CppCon","summary":"Emery Berger''s CppCon 2020 plenary on why performance is hard on modern hardware after the end of Dennard scaling. It covers benchmarking pitfalls and introduces new profiling tools for finding real bottlenecks.","why":"Recommended for treating benchmarking and profiling scientifically rather than by myth, with innovative tools.","type":"talk","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2021,2022],"quote":"covers the basics of how to attempt benchmarking with actual computer science instead of myth and voodoo rituals","quote_url":"https://news.ycombinator.com/item?id=27483997","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('macM_MtS_w4','hn',2.0,'{"vid":"macM_MtS_w4","title":"Turing & The Halting Problem - Computerphile","channel":"Computerphile","summary":"A Computerphile video in which Mark Jago of the University of Nottingham explains Turing''s halting problem and how it led to the blueprint for the modern computer.","why":"Offered as a short, clear explanation of the halting problem and its link to decidability.","type":"explainer","level":"intro","score":2.0,"topics":["Math & theory"],"recs":2,"years":[2019,2022],"quote":"Here''s a short video on it","quote_url":"https://news.ycombinator.com/item?id=27458208","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('qgG5Jhi_Els','hn',2.0,'{"vid":"qgG5Jhi_Els","title":"Vim universe. fzf - command line fuzzy finder","channel":"Alexey Samoshkin","summary":"A screencast showing how to use the fzf command-line fuzzy finder in the shell and in Vim. It covers searching files and also using the Vim plugin for help tags, buffers, lines and grep matches.","why":"Recommended as a useful early tutorial for learning fzf with Vim.","type":"tutorial","level":"intro","score":2.0,"topics":["Software design & craft"],"recs":2,"years":[2020,2023],"quote":"another resource I found valuable early on","quote_url":"https://news.ycombinator.com/item?id=30739185","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('s19G6n0UjsM','hn',2.0,'{"vid":"s19G6n0UjsM","title":"Rust at speed — building a fast concurrent database","channel":"Jon Gjengset","summary":"A guest lecture Jon Gjengset gave at Two Sigma on using Rust for large, high-performance systems. It covers why Rust suits such projects, the Noria research database, a concurrent data structure used in it, and practical experience.","why":"HN points to it as a detailed, captivating talk by the Noria author, including a good explanation of deduplicating data between maps using unsafe.","type":"lecture","level":"advanced","score":2.0,"topics":["DSA","Systems & performance","Databases & distributed"],"recs":2,"years":[2019,2022],"quote":"gave a great talk about the system","quote_url":"https://news.ycombinator.com/item?id=29617226","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('swQbA4zub20','hn',2.0,'{"vid":"swQbA4zub20","title":"AWS re:Invent 2018: How AWS Minimizes the Blast Radius of Failures (ARC338)","channel":"Amazon Web Services","summary":"An AWS re:Invent 2018 talk on how AWS limits the blast radius of failures. It covers design techniques such as cell-based architecture and shuffle sharding.","why":"It is the go-to reference whenever HN discusses cell-based architecture and outage isolation, as an explanation straight from AWS engineers.","type":"talk","level":"advanced","score":2.0,"topics":["Databases & distributed"],"recs":2,"years":[2019,2023],"quote":"This YouTube video[1] of a re:invent presentation does a great job of explaining it.","quote_url":"https://news.ycombinator.com/item?id=25237836","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('tIeHLnjs5U8','hn',2.0,'{"vid":"tIeHLnjs5U8","title":"Backpropagation calculus | Deep Learning Chapter 4","channel":"3Blue1Brown","summary":"3Blue1Brown''s chapter 4 on deep learning gives a more formal, symbol-based account of backpropagation calculus, connecting the intuition from the previous chapter to the math found in textbooks and code.","why":"Recommended as an accessible, visual way to understand backpropagation and neural networks.","type":"explainer","level":"intro","score":2.0,"topics":["AI & ML"],"recs":3,"years":[2017,2024],"quote":"3Blue1Brown which explains math in very accessible way","quote_url":"https://news.ycombinator.com/item?id=15689936","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('taaEzHI9xyY','hn',2.0,'{"vid":"taaEzHI9xyY","title":"Crockford on JavaScript - Section 8: Programming Style & Your Brain","channel":"YUI Library","summary":"Douglas Crockford''s YUIConf 2011 keynote on why programming style matters, particularly in JavaScript. He draws on science about the brain and shows how tools like JSLint help.","why":"HN points to it as an entertaining, insightful talk about the nature of programming, with memorable lines about programmers and a refreshing slide style.","type":"talk","level":"intermediate","score":2.0,"topics":["Web"],"recs":3,"years":[2014,2015],"quote":"entertaining and insightful talk","quote_url":"https://news.ycombinator.com/item?id=9585637","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('uaje5I22kgE','hn',2.0,'{"vid":"uaje5I22kgE","title":"Anthony Scopatz - xonsh - PyCon 2016","channel":"PyCon 2016","summary":"Anthony Scopatz presents xonsh at PyCon 2016, a shell that is a superset of Python combining the best features of bash, zsh and fish. It covers rich history, tab completion, and how the language compiles to a Python AST.","why":"Recommended as the author''s own explanation of xonsh''s design and how Python and shell interplay.","type":"talk","level":"intermediate","score":2.0,"topics":["Python","Languages & compilers","Software design & craft"],"recs":2,"years":[2016,2025],"quote":"It''s very easy to switch if you''re willing to spend 30 minutes to go through this talk about its design by the author","quote_url":"https://news.ycombinator.com/item?id=43178627","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('vmwnhZmEZjc','hn',2.0,'{"vid":"vmwnhZmEZjc","title":"The Stellar Consensus Protocol | David Mazières | Talks at Google","channel":"Talks at Google","summary":"David Mazieres presents the Stellar Consensus Protocol at Google, introducing federated Byzantine agreement. The model lets participants choose whom to trust rather than assuming fixed membership.","why":"Recommended as the protocol designer''s own detailed explanation of SCP.","type":"talk","level":"advanced","score":2.0,"topics":["Databases & distributed"],"recs":2,"years":[2018,2021],"quote":"This is a great video explaining SCP in detail","quote_url":"https://news.ycombinator.com/item?id=16235047","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wbp-3BJWsU8','hn',2.0,'{"vid":"wbp-3BJWsU8","title":"Google I/O 2011: Java Puzzlers - Scraping the Bottom of the Barrel","channel":"Google for Developers","summary":"Josh Bloch and Jeremy Manson present the eighth installment of Java Puzzlers at Google I/O 2011, a set of surprising corner cases in the Java language and libraries. It includes puzzlers on traps such as regular expression performance.","why":"HN commenters recommend it as an entertaining tour of exotic Java corner cases.","type":"talk","level":"intermediate","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2015,2018],"quote":"Java Puzzlers by Joshua Bloch and Jeremy Manson are pretty entertaining.","quote_url":"https://news.ycombinator.com/item?id=18217966","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('wgHIkdUQbp0','hn',2.0,'{"vid":"wgHIkdUQbp0","title":"Episode 1: A basic expression evaluator","channel":"Immo Landwerth (terrajobst)","summary":"The first episode of a long live-coding series in which Immo Landwerth builds the Minsk compiler for a small language in C#. It starts with a basic expression evaluator and builds toward a full language.","why":"Recommended as a practical, approachable build-it-step-by-step introduction to writing compilers, light on theory.","type":"course","level":"intro","score":2.0,"topics":["Languages & compilers"],"recs":2,"years":[2020,2026],"quote":"Not too much theory but from a nuts and bolts perspective I found it extremely approachable.","quote_url":"https://news.ycombinator.com/item?id=23195604","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xEDZQtAHpX8','hn',2.0,'{"vid":"xEDZQtAHpX8","title":"Modern SQL: A lot has changed since SQL-92 by Markus Winand","channel":"Devoxx","summary":"Markus Winand shows how SQL has evolved since SQL-92, comparing old-style solutions to modern features such as window functions and system versioning, and notes that many developers never learn them.","why":"Recommended as the best introduction to modern SQL standard features that textbooks skip.","type":"talk","level":"intermediate","score":2.0,"topics":["Databases & distributed"],"recs":2,"years":[2019,2023],"quote":"the whole talk is good","quote_url":"https://news.ycombinator.com/item?id=34207893","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('xFKFoGiGlXQ','hn',2.0,'{"vid":"xFKFoGiGlXQ","title":"Finding the BEST sine function for Nintendo 64","channel":"Kaze Emanuar","summary":"Kaze Emanuar searches for the best sine approximation for the Nintendo 64, comparing the lookup tables in Mario 64 and Ocarina of Time with polynomial alternatives. It walks through numerics and 3rd, 4th and 5th order approximations.","why":"Cited in discussions of sine implementations and whether lookup tables beat computation on memory-bound hardware.","type":"explainer","level":"intermediate","score":2.0,"topics":["Systems & performance"],"recs":2,"years":[2023,2026],"quote":"This guy puts a lot of work into figuring out if there is a faster way to do trig calcs on the N64","quote_url":"https://news.ycombinator.com/item?id=41156746","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NfnWJUyUJYU','hn',1.5,'{"vid":"NfnWJUyUJYU","title":"CS231n Winter 2016: Lecture1: Introduction and Historical Context","channel":"Andrej Karpathy","summary":"The first lecture of Stanford''s CS231n Winter 2016 course on convolutional neural networks for visual recognition, introducing the course and the historical context of computer vision.","why":"HN lists it as a free, brilliant introduction to deep learning and computer vision, often within ML self-study plans.","type":"course","level":"intro","score":1.5,"topics":["Karpathy","AI & ML"],"recs":2,"years":[2016,2023],"quote":"I will suggest two brilliant courses from Stanford","quote_url":"https://news.ycombinator.com/item?id=16168374","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('LCEmiRjPEtQ','hn',1.0,'{"vid":"LCEmiRjPEtQ","title":"Andrej Karpathy: Software Is Changing (Again)","channel":"Y Combinator","summary":"Andrej Karpathy''s keynote at AI Startup School laying out software 1.0, 2.0 and 3.0, with LLMs seen as utilities, fabs and operating systems. It covers LLM quirks, partial-autonomy apps and keeping a human in the generate-and-verify loop.","why":"HN mostly cites it as a source for Karpathy''s framing of programming in English and his generate-then-verify workflow, with a few critics finding it hype.","type":"talk","level":"general","score":1.0,"topics":["Karpathy","AI & ML","LLMs"],"recs":1,"years":[2025,2025],"quote":"I enjoyed Andrej Karpathy''s talk about software in the era of AI.","quote_url":"https://news.ycombinator.com/item?id=44942098","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('NSDTZQdo6H8','hn',1.0,'{"vid":"NSDTZQdo6H8","title":"Andrej Karpathy (Tesla): CVPR 2021 (see description for better quality version)","channel":"YarrowFlower","summary":"Andrej Karpathy''s CVPR 2021 presentation on Tesla''s Autopilot, covering its vision-based approach, sensor choices and the scale of Tesla''s deep learning compute cluster. This upload is a lower-quality copy of the talk.","why":"HN cites it as the primary source for Tesla''s vision-only reasoning, LIDAR arguments and sensor fusion challenges.","type":"talk","level":"intermediate","score":1.0,"topics":["Karpathy","AI & ML"],"recs":1,"years":[2021,2022],"quote":"it''s quite long, but the whole thing is quite interesting","quote_url":"https://news.ycombinator.com/item?id=30170027","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('hM_h0UA7upI','hn',1.0,'{"vid":"hM_h0UA7upI","title":"No Priors Ep. 80 | With Andrej Karpathy from OpenAI and Tesla","channel":"No Priors: AI, Machine Learning, Tech, & Startups","summary":"A No Priors podcast conversation with Andrej Karpathy covering self-driving (Tesla versus Waymo), the Optimus robot, bottlenecks in AI development, and his education project Eureka Labs.","why":"Commenters cite it for Karpathy''s views on Tesla versus Waymo, neural networks as a path to AGI, and the quality of internet data for LLMs.","type":"podcast","level":"general","score":1.0,"topics":["Karpathy","LLMs","AI & ML"],"recs":1,"years":[2024,2025],"quote":"he''s talking for 5 minutes in detail about exactly why he believes Tesla is ahead of Waymo and will beat them to scale.","quote_url":"https://news.ycombinator.com/item?id=41807046","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('y57wwucbXR8','hn',1.0,'{"vid":"y57wwucbXR8","title":"Building the Software 2 0 Stack (Andrej Karpathy)","channel":"Databricks","summary":"Andrej Karpathy''s Databricks talk on Software 2.0, the shift from human-written code to code produced by neural network training. It covers how developer work moves toward curating datasets, the advantages and challenges, and opportunities for new tooling.","why":"HN uses it as the primary source for the ''Software 2.0'' idea and recommends it as a quick talk on the next software stack.","type":"talk","level":"intermediate","score":1.0,"topics":["Karpathy","AI & ML"],"recs":1,"years":[2019,2022],"quote":"here''s a good/quick talk by Andrej Kapathy on what it will take to build the next software stack.","quote_url":"https://news.ycombinator.com/item?id=23826188","source":"hn"}',0);
INSERT OR IGNORE INTO videos (vid,source,score,payload,added_at) VALUES ('lXUZvyajciY','hn',0.0,'{"vid":"lXUZvyajciY","title":"Andrej Karpathy — “We’re summoning ghosts, not building animals”","channel":"Dwarkesh Patel","summary":"Dwarkesh Patel interviews Andrej Karpathy on why reinforcement learning is flawed, why AGI may blend into steady GDP growth, why self-driving took so long, and the future of education. The conversation runs about two and a half hours.","why":"Mostly cited as a source for Karpathy''s views on agents, AGI timelines and LLMs, rather than recommended outright.","type":"interview","level":"intermediate","score":0.0,"topics":["Karpathy","AI & ML","LLMs"],"recs":0,"years":[2025,2026],"quote":"I just watched this recent (and great!) interview","quote_url":"https://news.ycombinator.com/item?id=45679811","source":"hn"}',0);